/* ÇEVİRİ pt · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("pt","olay",{
"OLAYLAR_EK5:1785-04-27:0":{"b": ["A destituição e execução do grão-vizir Halil Hamîd Paxá", "c44001ca"], "d": ["O grão-vizir reformador Halil Hamîd Paxá, de cujos serviços Abdülhamid I mostrara em várias ocasiões estar satisfeito, foi destituído de repente por volta da manhã de 31 de março de 1785 e exilado para Gallipoli, e todos os seus bens foram confiscados. Foram-lhe dadas primeiro a província da Abissínia, o sanjaco de Jidá e o cargo de xeique dos haremeyn de Meca; enquanto passava abril de 1785 em Tenedos com os preparativos para a viagem, foi destituído também deste governo e, pelo firmão de execução que saiu, foi morto por Karakethüdâzâde Ali, homem de Cezayirli Gazi Hasan Paxá. A cabeça cortada foi enviada a Istambul e exibida em Ortakapı. Segundo a TDV, embora esta queda súbita tenha sido interpretada com a acusação de uma trama para depor o sultão e pôr em seu lugar o príncipe Selim, as verdadeiras causas devem ter sido a indignação pelo seu silêncio perante a anexação da Crimeia, a hostilidade dos meios lesados pelas suas reformas e a oposição de Gazi Hasan Paxá.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Declaração de guerra à Rússia — começou a guerra otomano-russa de 1787-1792", "3bfb870c"], "d": ["Perante a ostentosa viagem de Catarina II à Crimeia e o facto de ela ter tomado a Geórgia sob a sua proteção, o Divã decidiu a guerra para reverter a anexação, e o embaixador russo foi de novo encerrado em Yedikule. Mas o exército não estava pronto, o tesouro estava vazio e a busca de aliados fora infrutífera. A guerra, que duraria cinco anos, terminaria com a queda de Özi com massacre, a perda de İsmail e as duras condições do Tratado de Iaşi.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["A entrada da Áustria na guerra — luta em duas frentes", "ae912290"], "d": ["Em virtude da aliança secreta que fizera com a Rússia em 1781, o imperador austríaco José II declarou guerra ao Estado Otomano e pôs-se em marcha na direção de Belgrado e da Bósnia. O exército otomano viu-se de repente obrigado a combater em duas frentes ao mesmo tempo: a Rússia a norte e a Áustria a oeste. Apesar das vitórias obtidas contra os austríacos em Lazarethane, Muhâdiye e Şebeş, a frente ocidental ruiria também em 1789 com a perda de Belgrado.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Aliança otomano-prussiana", "03b88e51"], "d": ["Selim III, que procurava aliados na Europa logo que subiu ao trono, assinou com a Prússia um tratado de aliança que previa assistência mútua; a Prússia comprometeu-se a declarar guerra à Rússia e à Áustria, e o Estado Otomano a não fazer a paz sem que a Crimeia fosse recuperada. Este foi, na história otomana, o primeiro verdadeiro texto de aliança recíproca assinado com um Estado europeu e mostrava que fora abandonada a concepção clássica de que 'não há aliança com os infiéis'. A Prússia não entrou na guerra, mas, forçando a Áustria à paz, abriu caminho ao Tratado de Sistova.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["A queda da fortaleza de İsmail e o massacre", "6a296b0c"], "d": ["A fortaleza de İsmail, considerada a mais forte praça do delta do Danúbio, foi tomada num só dia por um sangrento assalto geral organizado pelo general Suvorov; a guarnição e a população da cidade foram em grande parte passadas a fio de espada. Este massacre, que teve grande eco na Europa, provocou um choque profundo na opinião pública otomana e quebrou a espinha dorsal da linha de defesa do Danúbio. A fortaleza seria recuperada um ano depois pelo Tratado de Iaşi, mas o destino da guerra já estaria decidido.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Tratado de Sistova — o encerramento da frente austríaca", "58741f1d"], "d": ["Graças à pressão da Prússia e ao facto de a Revolução Francesa ocupar a Áustria a ocidente, os dois Estados chegaram à paz tomando como base as fronteiras anteriores à guerra. A Áustria devolveu todos os lugares que ocupara, incluindo Belgrado; o Estado Otomano aceitou apenas pequenas correções na fronteira da Croácia. O encerramento da frente ocidental nestas condições permitiu ao Estado Otomano concentrar todas as suas forças contra a Rússia e limitou a perda no Tratado de Iaşi.", "45643640"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Tratado de Iaşi — a perda definitiva da Crimeia e a fronteira do Turla", "a56fd194"], "d": ["Pelo tratado assinado no fim da guerra de cinco anos, o rio Turla (Dniestre) foi aceite como fronteira; a margem esquerda do rio ficou para a Rússia e a direita para os otomanos, e Özi e os seus arredores perderam-se definitivamente. O Estado Otomano abandonou por completo a esperança de recuperar a Crimeia e reconheceu juridicamente a anexação de 1783; a Valáquia e a Moldávia foram restituídas com isenção de impostos por dois anos. Aceite também a obrigação de uma indemnização de guerra de doze milhões de kuruş, o norte do mar Negro ficou cedido de modo permanente à Rússia. Outros lugares que passaram na mesma data: İsmail.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["A evacuação de Orão pelos espanhóis e a sua cedência a Argel", "9f95cee6"], "d": ["Quando a fortaleza e a cidade foram em grande parte destruídas pelo sismo de 1790, a Espanha, que já não podia suportar a dispendiosa guarnição mantida havia três séculos, entendeu-se com a milícia (ocak) de Argel e cedeu sem guerra Orão e Mers el-Kébir. Foi assim liquidada também a última posição europeia na costa do Norte de África. A Argélia otomana manteve-se senhora de toda a costa durante os trinta e oito anos que passariam até à ocupação francesa.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["O domínio de facto de Pazvandoğlu Osman em Vidin", "0ce70361"], "d": ["Pazvandoğlu Osman, que se revoltou contra as medidas do Nizâm-ı Cedîd, fez fugir o governador de Vidin, apoderou-se da cidade e fortificou-a com fossos profundos ao longo do Danúbio. Em 1797, no auge do seu poder, reuniu cerca de oitenta mil homens e pôs sob o seu controlo Nikopol, Sistova, Ruse, Sófia e Niš; apresentava-se a si próprio não como rebelde, mas como reformador. O cerco de meses que a Sublime Porta lhe pôs em 1798-1799 foi infrutífero, e ele governou de forma semi-independente no norte da Bulgária até à sua morte, em 1807.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["A abertura da Mühendishâne-i Berrî-i Hümâyun", "e9a3a34b"], "d": ["Para formar oficiais de artilharia, de fortificação e cartógrafos para o exército do Nizâm-ı Cedîd, abriu em Hasköy a escola de engenharia terrestre; era o equivalente, no exército de terra, da Escola de Engenharia Naval fundada em 1773. O programa ensinava álgebra, geometria, mecânica, fortificação e balística, e foram traduzidos de línguas europeias livros de matemática e de artilharia. Esta escola, considerada a raiz do ensino moderno de engenharia na Turquia, é tida como o início da atual Universidade Técnica de Istambul.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Declaração de guerra à França e aliança com a Rússia e a Inglaterra", "80e95bd7"], "d": ["Com a invasão do Egito por Napoleão, o Estado Otomano rompeu a tradicional amizade francesa de dois séculos e meio e declarou guerra à França. No mesmo processo, aliou-se pela primeira vez na sua história à Rússia e permitiu que a frota russa passasse pelos Estreitos e saísse para o Mediterrâneo; a seguir foi assinada também uma aliança com a Inglaterra. Graças a estas alianças, as ilhas Jónicas foram tomadas aos franceses, mas a abertura dos Estreitos a uma frota estrangeira criou um precedente de pesado custo futuro.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["A tomada de Preveza aos franceses — a Batalha de Nicópolis", "d8e5e892"], "d": ["Quando a República de Veneza foi destruída, em 1797, as ilhas Jónicas e, em terra firme, Preveza, Parga e Vonitsa caíram nas mãos da França. O governador de Ioannina, Tepedelenli Ali Paxá, aproveitando a guerra aberta com a invasão do Egito pela França, marchou sobre Preveza e infligiu uma pesada derrota à guarnição francesa nas ruínas de Nicópolis, fora da cidade. Assim, este porto, deixado a Veneza em Požarevac, entrou na administração otomana oitenta anos depois.", "eeebcaf6"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["A defesa de Acre — a repulsa de Napoleão", "56b5c45b"], "d": ["Napoleão, que avançava do Egito para a Síria, cercou Acre e lançou ataques sucessivos durante dois meses; a cidade foi defendida por Cezzâr Ahmed Paxá, com o apoio da frota inglesa e das tropas do Nizâm-ı Cedîd enviadas de Istambul. Napoleão, obrigado a levantar o cerco e a recuar para o Egito, enterrou diante destas muralhas o sonho de se estender para o Oriente. A notícia foi recebida com grande alegria em Istambul e considerada a prova de que o exército disciplinado recém-criado passara o seu primeiro exame sério.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["A incursão wahhabita a Cerbala", "522341ed"], "d": ["As forças wahhabitas, partidas de Najd, entraram em Cerbala, saquearam a cidade, destruíram o mausoléu do imam Hussein e mataram mais de três mil pessoas. Os governadores mamelucos do Estado Otomano no Iraque não conseguiram impedir a incursão; o caso suscitou grande reação tanto no Irão como em Istambul. Este ataque foi a proclamação de que o movimento saudita deixara de ser um emirado de oásis e se transformara numa potência regional que ameaçava as cidades santas otomanas.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["Kartli-Kakheti (Geórgia Oriental) foi anexada à Rússia", "3b650c5e"], "d": ["O czarado de Kartli-Kakheti, que aceitara a proteção russa em 1783 e sofrera em 1795 a devastadora campanha do Irão, foi dissolvido; por ordem de 12 de setembro de 1801 foi declarado província da Rússia e começou a implantar-se o sistema administrativo russo. A Geórgia perdeu a independência a partir desta data; em poucos anos, também Mingrélia (1803), Imerécia e Guria (1804) entraram no domínio russo e a Rússia chegou à fronteira otomana do Cáucaso.", "957f5cd5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["A evacuação do Egito pelos franceses", "00cfdc8c"], "d": ["Em resultado da operação conjunta das forças otomanas e inglesas por terra e por mar, foram entregues primeiro o Cairo e depois Alexandria, e as forças francesas foram enviadas de navio para o seu país. Ao terminar a ocupação de três anos, o Egito regressou no papel à administração otomana, mas a luta pelo domínio entre os seus beis mamelucos e as tropas albanesas lançou o país no caos. Este vazio preparou, em poucos anos, o terreno para a ascensão de Mehmed Ali de Cavala.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Tratado de Paris — o restabelecimento da paz com a França", "1b76991f"], "d": ["Com o tratado assinado depois da evacuação do Egito, o estado de guerra entre o Estado Otomano e a França terminou oficialmente e foram renovadas as antigas capitulações. Foi permitida a entrada de navios mercantes franceses no mar Negro; em contrapartida, a França reconheceu a integridade territorial otomana. O estabelecimento da paz devolveu margem de manobra à política externa de Selim III, apertada entre a Rússia e a Inglaterra.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["A tomada de Taif pelos wahhabitas", "7b791359"], "d": ["As forças wahhabitas comandadas por Suûd b. Abdülazîz, no primeiro movimento contra o Hejaz, cercaram e saquearam Taif; a cidade caiu como a primeira porta que se abria para as terras santas. Para o sultão otomano, que ostentava o título de protetor dos Haremeyn, foi um golpe que abalou diretamente a legitimidade do sultanato. Dois meses e meio depois, o mesmo exército marcharia sobre Meca.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["A primeira tomada de Meca pelos wahhabitas", "21157c05"], "d": ["Dois meses e meio depois da queda de Taif, as forças wahhabitas entraram em Meca, derrubaram os mausoléus e instauraram uma ordem segundo a sua própria compreensão; o xarife Gālib foi obrigado a retirar-se para Jidá. O encerramento das rotas da peregrinação ecoou em todo o mundo islâmico e obrigou Istambul a pedir ajuda militar ao governador do Egito, Mehmed Ali. Este primeiro domínio duraria apenas três meses.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["A reconquista de Meca pelo xarife Gālib", "83d08dff"], "d": ["O xarife Gālib, que se retirara para Jidá, cercou Meca com as forças que reuniu e, depois de um cerco de vinte e cinco dias, retomou a cidade aos wahhabitas; a hutbe voltou a ser lida em nome dos otomanos. Este segundo domínio também não seria duradouro, pois as forças de Suûd retomariam a cidade em 1806.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["O início da Primeira Insurreição Sérvia", "0f6e8767"], "d": ["Quando os dahis janízaros rebeldes, que tinham tomado o poder em Belgrado, massacraram em massa os notáveis sérvios, começou uma resistência armada sob a liderança de Karađorđe. O movimento, conduzido inicialmente apenas contra os dahis, mantendo-se fiel ao sultão, transformou-se em pouco tempo numa revolta nacional que reclamava autonomia e independência. As forças sérvias tomaram Belgrado em 1806; esta insurreição foi o primeiro elo dos movimentos nacionalistas de independência nos Balcãs.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["A ocupação de Medina pelos wahhabitas", "84e310d7"], "d": ["Depois de Meca, também Medina caiu nas mãos das forças wahhabitas; o tesouro de Ravza-i Mutahhara foi distribuído e os mausoléus abobadados da cidade foram derrubados. Assim, as duas cidades santas saíram ao mesmo tempo do controlo otomano, e as caravanas de peregrinos vindas de Damasco e do Egito não puderam partir durante anos. Medina só pôde ser recuperada sete anos depois, em 1812, pelo exército egípcio comandado por Tosun Paxá, filho de Mehmed Ali Paxá.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["O início da guerra com a Rússia (guerra otomano-russa de 1806-1812) e o encerramento dos Estreitos", "ea170804"], "d": ["Depois de Selim III, que se aproximara da França após a vitória de Napoleão em Austerlitz, ter deposto, apesar da pressão russa, os voivodas da Valáquia e da Moldávia, os exércitos russos ocuparam os dois principados e a guerra começou. O Estado Otomano fechou os Estreitos à frota russa; em contrapartida, a Inglaterra, ao lado da Rússia, enviou uma esquadra a Istambul. Esta guerra, que duraria seis anos, entrelaçada com a Revolta de Kabakçı e a deposição de Selim III, terminaria no Tratado de Bucareste de 1812 com a perda da Bessarábia.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["A chegada da frota inglesa diante de Istambul (operação de Duckworth)", "195bb58f"], "d": ["A Inglaterra, que queria forçar o Estado Otomano a romper os laços com a França, fez passar por Çanakkale a esquadra comandada pelo almirante Duckworth e fundeou-a diante de Istambul. Com a orientação também do embaixador francês Sébastiani, o povo de Istambul mobilizou-se, as baterias costeiras foram reforçadas em poucos dias e a esquadra, sem poder bombardear a cidade, teve de recuar; no regresso sofreu pesadas perdas em Çanakkale. O facto de a capital ser pela primeira vez ameaçada tão de perto por uma frota estrangeira colocou a questão dos Estreitos no centro da diplomacia europeia.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["O estrangulamento de Mustafa IV", "eeb75c20"], "d": ["Quando Alemdar Mustafa Paxá foi atacado e morreu e os rebeldes quiseram marchar sobre o palácio, o deposto Mustafa IV foi estrangulado por ordem do irmão Mahmud II. O seu funeral foi sepultado em Bahçekapı, no mausoléu do pai, Abdülhamid I; espalhou-se entre os rebeldes o rumor de que o caixão estava vazio.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Tratado de Kal'a-i Sultâniyye — paz com a Inglaterra e regra dos Estreitos", "fe282117"], "d": ["Com o tratado assinado com a Inglaterra após o fracasso da operação de Duckworth, terminou a guerra entre os dois Estados e foram restituídos os antigos privilégios dos comerciantes ingleses. A disposição do texto, chamada 'regra antiga', registou que em tempo de paz nenhum navio de guerra estrangeiro podia passar pelos Estreitos. Este princípio tornou-se o fundamento jurídico de todos os arranjos internacionais que moldariam o regime dos Estreitos ao longo do século XIX.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["O desastre de Slobozia — o cerco do exército do Danúbio", "54b60fd1"], "d": ["A maior parte do exército otomano que atravessara o Danúbio diante de Ruse foi encurralada em Slobozia pela manobra de envolvimento de Kutuzov a partir da margem oposta do rio e deixada à fome. Milhares de soldados foram obrigados a render-se; a força nas mãos do grão-vizir derreteu de facto, e a Sublime Porta teve de pedir um armistício um mês depois. Esta derrota é a causa direta de se ter consentido, no Tratado de Bucareste de 1812, na cedência da Bessarábia.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["A reconquista de Belgrado e a repressão da Primeira Insurreição Sérvia", "06f56f52"], "d": ["Privados do apoio russo pelo Tratado de Bucareste, os insurretos sérvios não resistiram à operação conjunta das forças vindas da Bósnia e da Rumélia; Hurşid Ahmed Paxá entrou em Belgrado e a insurreição de nove anos foi totalmente reprimida. Karađorđe fugiu para a Áustria e o sanjaco de Semendire voltou a ficar diretamente sob administração otomana. Mas as duras medidas aplicadas desencadeariam, dois anos depois, uma segunda e duradoura insurreição sob a liderança de Miloš Obrenović.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["A Segunda Insurreição Sérvia e o título de grão-cnez de Miloš Obrenović", "e6e82ad2"], "d": ["Contra as duras medidas aplicadas após a repressão da primeira insurreição, rebentou uma nova revolta sob a liderança de Miloš Obrenović; desta vez a Sublime Porta preferiu o acordo à força. Pelo entendimento alcançado, Miloš foi reconhecido com o título de 'grão-cnez' e a competência de cobrar impostos e conduzir os assuntos internos foi deixada aos cnezes sérvios. Este primeiro núcleo de autonomia de facto foi o ponto de partida do processo que se prolongaria até ao firmão de 1830 e à independência de 1878.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["A Revolta da Valáquia — a travessia do Prut por Ypsilanti e a insurreição de Vladimirescu", "67d46a98"], "d": ["Aleksandr Ypsilanti, general do exército russo, tentou iniciar, em nome da Filikí Etería, uma insurreição geral grega na Valáquia e na Moldávia, atravessando o Prut; nos mesmos dias, Tudor Vladimirescu pôs também em movimento os camponeses locais. Os dois movimentos não se uniram: Vladimirescu respondeu ao apelo de Ypsilanti para combaterem juntos os turcos com 'Não me revoltei contra os turcos, mas contra os gregos', e pouco depois foi morto pelos homens de Ypsilanti. A revolta foi reprimida pelas forças otomanas em maio, mas a ordem dos voivodados fanariotas terminou e o fogo da insurreição propagou-se à Moreia.", "935b260a"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["A fundação do Segundo Estado Saudita em Riade", "34dad3bd"], "d": ["Seis anos depois da queda de Dir'iye em 1818 e da destruição do primeiro Estado Saudita, Türkî b. Abdullah expulsou de Najd as guarnições egípcias e fundou um novo emirado saudita com capital em Riade. A nova estrutura evitou estender-se ao Hejaz, preferindo ficar em Najd, e manteve-se afastada do confronto direto com as forças otomano-egípcias. Este segundo Estado duraria até ao fim do século e formaria o segundo elo da cadeia que conduziria à fundação da atual Arábia Saudita. Outros povoamentos perdidos na mesma data: Dir'iye (Najd).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Tratado de Akkirman — concessões à Sérvia e aos principados", "c75f15d0"], "d": ["O Estado Otomano, que ficara sem exército logo após a abolição do Corpo dos Janízaros, foi obrigado a aceitar, perante o ultimato da Rússia, um tratado de condições pesadas. Foi confirmada a autonomia prometida à Sérvia, aceitou-se que os voivodas da Valáquia e da Moldávia não pudessem ser depostos sem a aprovação russa e foi concedida aos navios mercantes russos plena liberdade nos Estreitos. Quando a Sublime Porta declarou, dois anos depois, que não reconhecia o tratado por causa da questão grega, a Rússia viria a tomar isso como pretexto de guerra.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["A liquidação do sistema do timar", "84d5d1d6"], "d": ["Um ano depois da abolição do Corpo dos Janízaros, cerca de 5.200 sipahis com timar, existentes em cinquenta e três sanjacos da Rumélia e da Anatólia, foram convertidos, com as rendas dos seus timares, em cavalaria do Asâkir-i Mansûre. Assim terminou de facto o regime do timar, espinha dorsal de quatro séculos da ordem otomana da terra, dos impostos e do exército. Os timares vagos foram transferidos para o tesouro, abrindo-se o caminho para a passagem a um exército central assalariado e a um sistema de impostos em dinheiro.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["A fundação da Tıphâne-i Âmire — o início do ensino moderno da medicina", "ac3e57c0"], "d": ["Para formar médicos e cirurgiões para o exército recém-criado do Asâkir-i Mansûre, abriu em Şehzadebaşı a Tıphâne-i Âmire, por proposta do médico-chefe Mustafa Behçet Efendi. As aulas foram organizadas segundo o currículo europeu e o ensino foi inicialmente dado em francês; alguns anos depois foi fundada também a Cerrahhâne-i Âmire e as duas instituições foram unidas. Esta escola, considerada o início do ensino moderno da medicina na Turquia, é tida como a origem da atual Faculdade de Medicina de Istambul.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["O início da guerra otomano-russa de 1828-1829", "9dff4e05"], "d": ["Depois da queima da frota em Navarino e de a Sublime Porta ter declarado que não reconhecia o Tratado de Akkirman, a Rússia declarou guerra em duas frentes ao mesmo tempo. Como o Corpo dos Janízaros acabara de ser abolido e o novo exército estava ainda em fase de formação, a defesa otomana foi fraca desde o início; enquanto os russos atravessavam o Danúbio, tomaram a leste Kars e Ahıska. O exército russo, que em um ano avançou até Edirne, imporia as duras condições do Tratado de Edirne de 1829 e a independência da Grécia.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["O primeiro tratado com os Estados Unidos da América", "d737516f"], "d": ["Com o tratado de comércio e navegação assinado após anos de contactos, os EUA obtiveram nas terras otomanas o estatuto de nação mais favorecida e o direito de passagem comercial pelos Estreitos. Um artigo secreto separado previa que os otomanos pudessem, quando quisessem, mandar construir navios em estaleiros americanos e comprar navios prontos e madeira; o Senado dos EUA ratificou o tratado, mas rejeitou este artigo secreto por 27 votos contra 18. Ainda assim, o caminho dos navios não se fechou: Henry Eckford vendeu aos otomanos, em 1831, o navio que trouxera, e os mestres americanos que trabalhavam em Aynalıkavak deram à marinha novos tipos de navios. Este tratado foi o documento da primeira relação abrangente do Estado Otomano com um Estado fora da Europa.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["O fim do governo mameluco em Bagdade", "7e1d38a3"], "d": ["Mahmud II, que seguia uma política de centralização, declarou rebelde o governador de Bagdade, Dâvud Paxá, que não enviava o dinheiro pedido e mandara matar o funcionário vindo do centro. A força comandada por Ali Rızâ Paxá tomou a cidade após um cerco de noventa dias e quase todos os mamelucos foram liquidados. Assim terminou o governo mameluco semi-independente que durava desde 1704, e o Iraque voltou a depender diretamente do centro.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["A fundação da Mekteb-i Harbiye no quartel de Maçka", "bf31c7d9"], "d": ["Para fornecer ao Asâkir-i Mansûre-i Muhammediyye oficiais formados à europeia, abriu no quartel de Maçka a Mekteb-i Fünûn-ı Harbiyye. Aos alunos ensinaram-se matemática, cartografia, fortificação e línguas estrangeiras; pouco depois foram enviados alunos a Viena e a Paris para reforçar o quadro. Esta escola foi o lugar onde nasceram a tradição do oficial formado em escola no exército otomano e, por conseguinte, a nova geração de militares-intelectuais que surgiria no fim do século XIX.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["A ligação direta de Trípoli de Barbaria ao centro — o fim da dinastia Karamanlı", "faabcb96"], "d": ["Perante as lutas pelo trono dentro da família Karamanlı e a crescente pressão europeia após a ocupação de Argel pela França em 1830, a Sublime Porta interveio diretamente em Trípoli de Barbaria. A esquadra enviada de Istambul entrou na cidade, o último bei Karamanlı foi deposto e levado para Istambul, e a província foi entregue a um governador nomeado pelo centro. Ao terminar o período dinástico de 124 anos, ficou consolidado o último pedaço de território que o Estado Otomano governava diretamente no Norte de África.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["A abolição do defterdarlık e a criação do Ministério das Finanças", "89f8125e"], "d": ["Abolido o cargo de defterdar, chefe da ordem financeira otomana clássica, foi criado o Maliye Nezâreti, um ministério à maneira europeia, e os tesouros dispersos foram reunidos numa só mão. No mesmo ano, as outras unidades da Sublime Porta foram também reorganizadas sob o nome de nezâret, passando-se a uma estrutura de conselho de ministros moderno. Esta organização foi um dos passos mais importantes na preparação da infraestrutura administrativa do Édito de Tanzimat, que seria proclamado um ano depois.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["A instalação dos ingleses em Áden", "ddbd556b"], "d": ["A Inglaterra, apoiando-se no acordo de comércio e amizade que assinara em 1802 com o sultão de Lahej, Ahmed b. Abdülkerîm, desembarcou tropas no porto de Áden e pôs a cidade sob o seu controlo. Este porto, que guarda a entrada do mar Vermelho, converteu-se em ponto-chave da estratégia imperial inglesa como base de abastecimento de carvão da rota da Índia. Embora a pretensão do Estado Otomano sobre o Iémen subsistisse no papel, o seu domínio de facto na costa meridional nunca mais voltou depois desta data.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["O regresso à costa de Tihâme: a tomada de Hudeida, Zabid e Moca", "353982d2"], "d": ["À costa do Iémen, que ficara sem dono com a retirada do exército egípcio em 1840, desembarcaram forças comandadas por Tevfik Paxá, sob a supervisão do xarife de Meca, e puseram os portos de Hudeida, Zabid e Moca sob a administração otomana. Embora se quisesse avançar até Sana, voltou-se a Hudeida devido à resistência da população; assim, as terras altas ficaram com os imames zaiditas e o domínio otomano durou vinte e três anos apenas na faixa de Tihâme. O interior do Iémen só seria recuperado em 1872, com a campanha de Ahmed Muhtar Paxá.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["A Convenção de Baltalimanı: protetorado conjunto otomano-russo na Valáquia e na Moldávia", "d3bb22e9"], "d": ["Com a propagação das revoluções de 1848 à Valáquia e à Moldávia, as forças otomanas e russas tinham ocupado em conjunto os principados. Pela convenção assinada em Baltalimanı, decidiu-se que os voivodas fossem nomeados pelo sultão por sete anos, e não por eleição, e que os dois Estados estabelecessem um controlo conjunto na região. O acordo, ao mesmo tempo que preservava a soberania otomana no papel, concedeu à Rússia um direito de parceria de facto e acelerou a separação dos principados do Danúbio do Império Otomano.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["A questão dos refugiados húngaros: o asilo de Kossuth e dos seus companheiros no Império Otomano", "1c7d7ef4"], "d": ["Quando a revolução húngara de 1848-1849 foi reprimida pela intervenção russo-austríaca, Lajos Kossuth e milhares de refugiados húngaros e polacos acolheram-se em terras otomanas. A Áustria e a Rússia exigiram com dureza a extradição dos refugiados; a Sublime Porta, com o apoio da Inglaterra e da França, recusou a extradição e instalou o grupo em Kütahya. O círculo de Kossuth ficou aí cerca de dezoito meses, e centenas de refugiados converteram-se ao islão e entraram ao serviço otomano. O caso foi considerado uma das raras vitórias diplomáticas que elevaram o prestígio do Império Otomano do Tanzimat na opinião pública europeia.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["A fundação do Encümen-i Dâniş: a primeira academia otomana em Istambul", "6fda1365"], "d": ["O Encümen-i Dâniş, criado por decisão do Meclis-i Maârif-i Umûmiyye, é a primeira academia científica otomana constituída para preparar obras de ciência e manuais em turco. Foi inaugurado com cerimónia no edifício do Dârülmaârif a 18 de julho de 1851; entre os seus membros, nacionais e estrangeiros, contava-se também Ahmed Cevdet Paxá. Embora de curta vida, obras como o Târih de Cevdet Paxá e o Kavâid-i Osmâniyye foram produto desta instituição, que é considerada uma pedra angular na afirmação do turco como língua da ciência.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["A vitória de Oltenița: o primeiro êxito otomano na frente do Danúbio", "a660ad2f"], "d": ["Na fase inicial da Guerra da Crimeia, o comandante-em-chefe Ömer Lütfi Paxá atravessou o Danúbio e repeliu em Oltenița as forças russas com pesadas perdas. Ao deter o avanço russo logo no início da guerra, a vitória mostrou à Europa a força que o exército otomano ganhara com a instrução posterior ao Tanzimat. Este êxito preparou o terreno psicológico que facilitou a decisão da Inglaterra e da França de entrarem na guerra ao lado dos otomanos.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["O tratado de aliança com a Inglaterra e a França em Istambul", "04809278"], "d": ["O tratado de aliança assinado na Guerra da Crimeia entre o Estado Otomano, a Inglaterra e a França, contra a Rússia, estipulou que os três Estados conduzissem operações conjuntas e que os aliados não fizessem paz separada antes do fim da guerra. Assim, o Estado Otomano entrou pela primeira vez na sua história numa aliança militar com as grandes potências europeias como parte em pé de igualdade. Este tratado constituiu também a base jurídica da admissão formal do Império Otomano no sistema de Estados europeus, dois anos depois, em Paris.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["A criação da Şehremaneti de Istambul: a primeira organização municipal moderna", "be4af27f"], "d": ["A crise de infraestruturas provocada pelos soldados aliados que afluíram a Istambul durante a Guerra da Crimeia e pelo aumento da população revelou a insuficiência da administração urbana clássica centrada no cádi. Com a Şehremaneti, criada segundo modelos europeus, a limpeza, o controlo de preços, a fiscalização dos mercados e as obras de urbanização foram reunidos numa só mão; no ano seguinte foi constituída, como região-piloto, em Beyoğlu-Galata a Sexta Circunscrição Municipal. Este passo é considerado o início do municipalismo moderno no Império Otomano.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["O Tratado de Paris: o fim da Guerra da Crimeia e a admissão do Império Otomano no sistema de Estados europeus", "4aee0e2a"], "d": ["Pelo Tratado de Paris, que pôs fim à Guerra da Crimeia, o Estado Otomano foi declarado membro igual do direito dos Estados europeus e a sua integridade territorial ficou sob a garantia comum das grandes potências. O mar Negro foi neutralizado, a pretensão russa de proteção sobre os súbditos ortodoxos, que mantinha desde Küçük Kaynarca, foi invalidada, e o sul da Bessarábia (os distritos de Kili, Cahul, İsmail e Bolgrad) foi dado à Moldávia. Contudo, o mesmo tratado, ao converter o Édito de Reforma num compromisso internacional, entreabriu também a porta à ingerência nos assuntos internos.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["A abertura do Palácio de Dolmabahçe: a transferência do centro administrativo do Topkapı", "71ad26d0"], "d": ["O palácio que Abdülmecid encomendara em 1842 à família Balyan foi aberto após catorze anos de construção, e o centro administrativo do Estado passou do Topkapı, de quatro séculos, para a margem do Bósforo. Com o seu estilo europeizante, a escadaria de cristal e o Salão de Cerimónias, o palácio foi a expressão em pedra da pretensão ocidentalizante do Tanzimat. O seu custo enorme tornou-se uma das rubricas mais criticadas dos anos em que as finanças otomanas entraram na espiral do endividamento externo.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["A união da Valáquia e da Moldávia sob Cuza: o nascimento da Roménia", "baef4da5"], "d": ["Nas eleições organizadas depois do Tratado de Paris, os dois principados elegeram voivoda o coronel Alexandru Ioan Cuza, realizando a união de facto. Embora a Sublime Porta e a Áustria se tivessem oposto, tiveram de aceitar o facto consumado, apoiado pela França. Esta união, que no papel continuava dependente dos otomanos, tomaria em 1862 o nome de Roménia e em 1877 proclamaria unilateralmente a independência; é um ponto de viragem na dissolução do domínio otomano ao longo do Danúbio.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["O Incidente de Kuleli: a primeira tentativa de golpe contra Abdülmecid em Istambul", "e3653b21"], "d": ["Uma sociedade secreta de composição mista, militar e civil, que reagia à política do Tanzimat e à igualdade concedida pelo Édito de Reforma aos não muçulmanos, foi surpreendida em reunião na Mesquita de Kılıç Ali Paxá quando planeava depor o sultão. Como os acusados foram julgados no Quartel de Kuleli, o caso ficou conhecido por este nome; as penas de morte foram comutadas em exílio. É considerado a primeira tentativa de golpe de palácio empreendida, na história otomana, por uma organização constituída por motivos ideológicos.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["A guerra civil drusa-maronita no Monte Líbano e os acontecimentos de Damasco", "5595fdd6"], "d": ["Os confrontos que rebentaram em maio de 1860 com a morte de dois drusos perto de Sídon converteram-se na mais sangrenta guerra civil drusa-maronita da montanha e, propagando-se a Damasco em julho, resultaram na morte de milhares de cristãos. Com o desembarque de tropas da França, a Sublime Porta enviou à região Fuad Paxá com poderes extraordinários; foi conduzida uma dura ação de repressão. Os acontecimentos serviram de pretexto à intervenção europeia e foram a causa direta de o Líbano obter um estatuto especial.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["O início da publicação do Tercümân-ı Ahvâl: o primeiro jornal turco privado em Istambul", "24792957"], "d": ["O Tercümân-ı Ahvâl, publicado por Agâh Efendi e cuja redação foi assumida por Şinâsi, é o primeiro jornal turco editado sem apoio do Estado. No prefácio do primeiro número defendeu-se o direito do povo de se pronunciar sobre os seus próprios assuntos, e o jornal, ao publicar em folhetim O Casamento do Poeta de Şinâsi, entreabriu também a porta da moderna literatura turca. O nascimento do conceito de opinião pública e da imprensa de oposição no Império Otomano é reportado a esta data.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["O Regulamento do Monte Líbano: estatuto de mutasarrifato privilegiado para o Líbano", "bf375603"], "d": ["O regulamento, preparado sob pressão das grandes potências após os massacres de 1860, fez do Monte Líbano um mutasarrifato privilegiado, dependente diretamente da Sublime Porta e governado por um conselho administrativo constituído segundo o equilíbrio entre as confissões. Estipulou-se que o mutasarrıf fosse um cristão católico, súbdito otomano, e que a sua nomeação fosse submetida à aprovação das grandes potências; o primeiro mutasarrıf foi Dâvud Paxá. Esta ordem duraria até 1915 e formaria o núcleo do moderno Estado libanês.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["A morte de Abdülmecid e a entronização do sultão Abdülaziz", "27204d7c"], "d": ["Quando Abdülmecid, que no seu reinado de vinte e dois anos assinara os Éditos de Tanzimat e de Reforma, sucumbiu à tuberculose, subiu ao trono o irmão Abdülaziz. O novo sultão deu esperança nos primeiros anos com medidas de poupança e uma vida simples; fez da marinha uma das poucas potências do mundo. Mas no fim do seu reinado a pesada dívida externa, a bancarrota de 1875 e as revoltas dos Balcãs acumulavam-se, preparando o terreno para a deposição de 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Os principados unidos tomam o nome de Roménia", "d960e3fc"], "d": ["A Valáquia e a Moldávia, unidas de facto desde a dupla eleição de Cuza em 1859, reuniram em 1862 as suas assembleias e governos sob um só teto em Bucareste e tomaram oficialmente o nome de Roménia. Embora o Estado Otomano conservasse juridicamente a qualidade de suserano e o tributo anual, perdeu de facto o controlo sobre o principado. O fim da influência otomana de quatro séculos a norte do Danúbio é simbolizado por esta data.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["A ligação de Suakin, Maçuá e Dahlak ao Egito", "a0924860"], "d": ["Maçuá, que em 1846 fora dada pelo sultão Abdülmecid, juntamente com Suakin, ao quediva Mehmed Ali Paxá do Egito como sâlyâne (atribuição de rendimentos), foi incorporada, no tempo do quediva İsmâil Paxá, juntamente com Dahlak e Suakin, nos domínios do Egito e organizada com o estatuto de kaymakamlık. Assim, estes três portos da costa africana do mar Vermelho, embora juridicamente continuassem território otomano, passaram administrativamente da Sublime Porta diretamente para o Cairo — entrando no mesmo estrato de dependência que o seu vizinho Egito e o Sudão.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["O início da Revolta de Creta (1866-1869)", "3679b861"], "d": ["A insurreição de grande envergadura que rebentou na ilha com o apoio aberto da Grécia converteu pela primeira vez em questão internacional a reivindicação de enosis (união com a Grécia) dos gregos de Creta. A dura guerra de montanha de três anos infligiu pesadas perdas ao exército otomano e teve grande eco na opinião pública europeia. A revolta só se extinguiu em 1868, quando Âlî Paxá foi à ilha e pôs em vigor o regulamento que concedia amplos privilégios.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["A retirada das últimas guarnições otomanas das fortalezas de Belgrado e da Sérvia", "b34217db"], "d": ["Sob a pressão das grandes potências e a insistente exigência do príncipe Mihailo, a Sublime Porta aceitou evacuar as últimas bases militares que lhe restavam na Sérvia; a 18 de abril de 1867 foi arriado o estandarte otomano na fortaleza de Belgrado e as chaves foram entregues ao príncipe. Assim terminou a presença militar otomana de facto, que durava desde 1521, e foi removido o último grande obstáculo no caminho da Sérvia para a independência. A suserania do sultão ficou reduzida apenas a uma questão simbólica de bandeira e de tributo.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["A concessão do título de quediva aos governadores do Egito", "09e10c12"], "d": ["Em resultado do intenso lóbi de İsmâil Paxá, da terceira geração da dinastia de Cavala, e do dinheiro que fez correr para Istambul, foi concedido ao governador do Egito o título de quediva, que sublinha a sua superioridade sobre os outros governadores. Nos mesmos anos, a ordem de sucessão foi também alterada para passar de pai para filho, e foram reconhecidas ao Egito competências de natureza soberana, como contrair dívidas externas, conferir medalhas e manter consulados. Estes passos são o primeiro elo da cadeia que acelerou a separação jurídica do Egito do Império Otomano.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["O Regulamento de Creta: amplos privilégios administrativos para a ilha", "12052262"], "d": ["Para pôr fim à revolta de três anos, o grão-vizir Âlî Paxá foi pessoalmente à ilha e, pelo regulamento publicado com a aprovação do sultão, foram concedidos aos cretenses conselhos administrativos mistos, tribunais locais, o uso do grego nos atos oficiais e facilidades fiscais. Esta disposição manteve de pé o domínio otomano na ilha por mais trinta anos. Mas os privilégios concedidos à população cristã enfraqueceram a posição dos cretenses muçulmanos e lançaram as sementes da crise de 1896-1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["A abertura do Şûrâ-yı Devlet: a fundação do Conselho de Estado otomano", "70b16497"], "d": ["Pela ordem imperial de 5 de março de 1868, o Meclis-i Ahkâm-ı Adliyye foi dividido em dois, ficando os assuntos administrativo-legislativos para o Şûrâ-yı Devlet e os assuntos judiciais para o Dîvân-ı Ahkâm-ı Adliyye; a instituição foi inaugurada com cerimónia na Sublime Porta e Midhat Paxá foi colocado na sua primeira presidência. Foi encarregada de preparar projetos de lei, resolver litígios administrativos e conduzir o julgamento de funcionários. Com a sua composição mista de membros muçulmanos e não muçulmanos, é considerada a primeira aplicação institucional da ideia de separação de poderes no Império Otomano.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["A abertura do Canal do Suez: o encurtamento da rota da Índia pelo Egito", "377ccd04"], "d": ["A construção, iniciada em 1859, durou dez anos, e o canal de 163 quilómetros que liga o Mediterrâneo ao mar Vermelho entrou em serviço com uma cerimónia grandiosa. Quando a rota que liga a Europa à Índia encurtou milhares de milhas, o Egito tornou-se de repente ponto-chave do comércio mundial. Este valor geoestratégico seria a principal causa da ocupação do Egito pela Inglaterra treze anos após a abertura do canal; e a dívida que o canal impôs ao Egito levaria o quediva à bancarrota.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["A fundação do Exarcado Búlgaro: a separação da igreja búlgara do Fener", "33a8272c"], "d": ["Por firmão imperial foi criada uma igreja búlgara autónoma (exarcado), separada do Patriarcado Grego, e deixou-se a um plebiscito popular decidir que distritos (kazas) ficariam ligados ao exarcado. Embora a Sublime Porta tivesse dado este passo para quebrar a influência grega, o resultado foi o inverso: a igreja converteu-se no centro organizado da identidade nacional búlgara e da pretensão búlgara sobre a Macedónia. Assim se lançou o terreno institucional da rivalidade búlgaro-greco-sérvia nos Balcãs e das revoltas de 1876.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["A colocação de Asir sob administração direta", "4559e099"], "d": ["Quando o valor estratégico do mar Vermelho aumentou com a abertura do Canal do Suez, viu-se que as montanhas de Asir, a meio da estrada terrestre para o Iémen, não podiam ficar sem controlo. As forças de Redif Paxá, que partiram em campanha para o Iémen, entraram em Abha e ligaram a região diretamente à administração otomana, e foi criado o sanjaco de Asir. Devido à geografia montanhosa e à influência dos Idrisidas, este domínio nunca se assentou por completo.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["A campanha de Midhat Paxá a Najd: o restabelecimento do domínio otomano em Lahsa", "7db51461"], "d": ["O governador de Bagdade, Midhat Paxá, aproveitando a luta pelo trono dentro da família saudita, enviou tropas à costa ocidental do golfo Pérsico e ligou a região de Lahsa à província de Bassorá com o nome de sanjaco de Najd. Abdullah b. Faysal foi nomeado mutasarrıf, estabelecendo-se no papel o domínio otomano. A campanha tinha por objetivo deter a expansão da influência inglesa no golfo e levou, no mesmo ano, a que também o Catar entrasse sob controlo otomano.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["A morte do grão-vizir Âlî Paxá: o fim do quadro do Tanzimat", "1cf0141c"], "d": ["Com a morte de Âlî Paxá, que depois do falecimento de Fuad Paxá em 1869 carregou sozinho a política do Tanzimat, esgotou-se a geração de mestres diplomatas que durante trinta anos dirigira a política externa do Estado. O governo pró-russo e arbitrário de Mahmud Nedim Paxá, que lhe sucedeu, consolidou a governação pessoal de Abdülaziz. Nos cinco anos seguintes à morte de Âlî Paxá, as finanças faliram, os Balcãs sublevaram-se e a mudança de sultão tornou-se inevitável.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["O estabelecimento do controlo otomano no Catar", "3b453165"], "d": ["A convite do xeique Kāsım b. Sânî, que estava sob pressão inglesa, forças otomanas desembarcaram na península do Catar e, no outono de 1871, foi assegurado na região o controlo otomano. O Catar foi organizado como um kaza dependente do sanjaco de Najd e o xeique foi nomeado kaymakam. Este lance foi o ganho mais concreto da política avançada que Midhat Paxá conduzia no golfo contra a Inglaterra; a bandeira otomana tremulou na península até 1913.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["O firmão de sucessão para Tunes — o beylik para a família de Mehmed Sâdık Paxá", "1509ebb0"], "d": ["Pelo firmão que saiu por iniciativa de Hayreddin Paxá, enviado a Istambul pelo bei de Tunes Mehmed Sâdık Paxá, que aproveitara a derrota da França perante a Prússia, Tunes foi dada a Mehmed Sâdık Paxá e aos seus descendentes por via de sucessão, continuando dependente diretamente de Istambul. Não se fariam negociações de guerra e paz sem a licença do sultão, nenhum território do país seria dado a outrem e seria satisfeito o pedido otomano de soldados. A França não reconheceu o firmão; dez anos depois ocupou Tunes.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["A tomada de Sana: o restabelecimento da autoridade otomana no Iémen", "978e20a0"], "d": ["Quando o valor estratégico do mar Vermelho aumentou com a abertura do Canal do Suez, a Sublime Porta enviou ao Iémen o exército da fırka-i ihtiyâtiyye sob o comando de Ahmed Muhtar Paxá. Com a tomada de Sana, foi restabelecida a autoridade do Estado no Iémen interior, de facto perdido havia dois séculos, e a região foi convertida em província. Mas a luta contra os imames zaiditas nunca terminou; as revoltas de 1891, 1898 e 1904 constituíram a frente interna mais cara e mais longa dos otomanos. Outros lugares que passaram na mesma data: Sana, Taiz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["O início da Revolta da Herzegovina: o reacender da Questão do Oriente", "571b18ec"], "d": ["A revolta dos camponeses cristãos em redor de Nevesinje, devida aos impostos pesados e à pressão dos âyan, propagou-se depressa a toda a Herzegovina e foi alimentada por voluntários vindos da Sérvia e de Montenegro. A revolta, que levou a Áustria e a Rússia a impor reformas, desencadeou no ano seguinte as insurreições búlgaras e as declarações de guerra da Sérvia e de Montenegro. Assim se quebrou o primeiro elo da grande cadeia que conduziu à Guerra de 93 e à perda dos Balcãs pelo Tratado de Berlim.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["A bancarrota das finanças otomanas: a redução a metade dos pagamentos da dívida externa", "2cac2fa5"], "d": ["Os empréstimos contraídos sucessivamente desde 1854, as despesas da Guerra da Crimeia, as construções de palácios e a fome de 1873-74 na Anatólia transformaram o défice orçamental num abismo superior a cinco milhões de liras. O governo de Mahmud Nedim Paxá declarou de facto uma moratória, anunciando que os pagamentos de juros e de capital da dívida seriam reduzidos a metade por cinco anos. Esta decisão, que suscitou grande reação nas bolsas europeias, iniciou o processo que, seis anos depois, resultaria no Decreto de Muharrem e na criação da Administração da Dívida Pública.", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["A deposição de Murad V e a entronização de Abdülhamid II", "cffb2271"], "d": ["Murad V, que subiu ao trono depois da deposição de Abdülaziz, tornou-se incapaz de exercer funções devido à sua saúde mental, abalada pela morte do tio e pelo Incidente de Çerkes Hasan; apenas em sete dias do seu reinado de noventa e três dias teve o juízo em ordem. Foi deposto por fetva do xeique do Islão (şeyhülislam) e em seu lugar foi posto o irmão Abdülhamid II. O novo sultão subiu ao trono depois de prometer a Midhat Paxá que proclamaria o regime constitucional; começava uma época que duraria trinta e três anos.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["A Conferência do Arsenal: a imposição das grandes potências sobre a reforma nos Balcãs", "b5006a2c"], "d": ["A conferência que as grandes potências reuniram em Istambul para resolver a crise dos Balcãs exigiu a divisão da Bulgária em duas províncias autónomas e a aplicação de reformas sob controlo internacional na Bósnia-Herzegovina. A Sublime Porta, no dia da abertura da conferência, anunciou com salvas de canhão a proclamação do Kanûn-ı Esâsî, procurando responder às imposições com uma reforma constitucional. Os delegados, considerando-o uma manobra dilatória, dispersaram-se a 20 de janeiro de 1877; quatro meses depois, a Rússia declarou guerra.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["A abertura da primeira Assembleia dos Deputados em Dolmabahçe", "429bb279"], "d": ["Os 115 deputados eleitos nos termos do Kanûn-ı Esâsî reuniram-se pela primeira vez a 19 de março de 1877, numa cerimónia no Salão de Cerimónias do Palácio de Dolmabahçe; assim começou, na história otomana, o período da assembleia representativa. Os deputados muçulmanos e não muçulmanos interrogaram o governo com dureza e discutiram a condução da guerra e a responsabilidade dos ministros. Esta oposição corajosa seria a principal causa do encurtamento da vida da assembleia.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["O início da defesa de Plevna: a resistência de Gazi Osman Paxá", "0e04a878"], "d": ["Osman Paxá, que marchou de Vidin a Plevna para cortar o caminho de Istambul ao exército russo que atravessara o Danúbio na Guerra de 93, fortificou a vila com redutos e trincheiras e iniciou uma lendária defesa de cinco meses. Três grandes ataques russo-romenos sucessivos foram repelidos com pesadas perdas, e o exército, dirigido pessoalmente pelo czar Alexandre II, foi obrigado a pôr cerco. Plevna ficou na história como o mais brilhante êxito defensivo do exército otomano no século XIX.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["A queda de Plevna: o colapso da frente do Danúbio", "185e7602"], "d": ["Osman Paxá, a quem se esgotaram os mantimentos no cerco de cinco meses, lançou uma operação de rutura pelo rio Vid; ao ser ferido e feito prisioneiro, a cidade rendeu-se. Os comandantes russos saudaram o paxá capturado devolvendo-lhe a espada, e a Osman Paxá foi dado o título de 'Gazi'. Com a queda de Plevna abriu-se o caminho ao exército russo; em dois meses caíram Sófia, Filipópolis e Edirne, e as vanguardas russas chegaram a Yeşilköy.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["A ocupação de Sófia pelas forças russas", "ef369d22"], "d": ["O exército russo, que transpusera os Balcãs depois da queda de Plevna, entrou em Sófia, que ficara indefesa. A cidade não voltaria à administração otomana, e seria no fim de 1878 a capital do Principado autónomo da Bulgária, e de facto em 1879. No mapa, Sófia passa, a partir desta data, da administração direta otomana para a ocupação russa provisória e, em seguida, para o governo búlgaro autónomo.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["O Armistício de Edirne: o silêncio das armas na Guerra de 93", "1f899180"], "d": ["Com a queda sucessiva de Sófia, Filipópolis e Edirne e com o exército russo chegado às costas do Mármara, a Sublime Porta foi obrigada a pedir um armistício. O cessar-fogo assinado em Edirne fez os otomanos aceitar condições preliminares de paz como a autonomia da Bulgária, a independência de Montenegro, da Sérvia e da Roménia e uma pesada indemnização de guerra. Estas condições converter-se-iam, um mês depois, em texto de tratado em Santo Estêvão.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["A suspensão por tempo indeterminado da Assembleia dos Deputados por Abdülhamid II", "e770b540"], "d": ["Perante as duras críticas dos deputados, que responsabilizavam o governo e o palácio pelo desfecho catastrófico da guerra, Abdülhamid II, apoiando-se no poder que o Kanûn-ı Esâsî lhe conferia, suspendeu a assembleia por tempo indeterminado. O primeiro parlamento otomano, que funcionara cerca de onze meses, encerrou-se assim e começou a época de despotismo que duraria trinta anos. A assembleia só voltaria a reunir-se depois da Revolução de 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["O Tratado de Santo Estêvão: o projeto da Grande Bulgária", "2c7cc611"], "d": ["O Tratado de Santo Estêvão, que pôs fim à Guerra de 93, criava uma enorme Bulgária autónoma que se estendia até ao Egeu e englobava a Macedónia; reconhecia a independência da Sérvia, de Montenegro e da Roménia; cedia à Rússia Kars, Ardahan, Batum e Doğubayazıt, e impunha ainda uma indemnização de guerra impossível de pagar. Este texto, que fazia descer a Rússia ao Mediterrâneo, suscitou a violenta reação da Inglaterra e da Áustria. Foi reordenado, sem ter sido aplicado, em quatro meses, pelo Congresso de Berlim; ainda assim, ficou como o documento que proclamou o fim da Rumélia otomana.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Kars, Ardahan e Batum foram cedidas à Rússia — elviye-i selâse", "99bdfad2"], "d": ["Pelo Tratado de Berlim, o Estado Otomano cedeu Kars, Ardahan e Batum à Rússia em contrapartida de uma parte da indemnização de guerra; Doğubayazıt e o vale de Eleşkirt, dados à Rússia em Santo Estêvão, ficaram com os otomanos. Embora Batum tenha sido dada como porto franco, só conservou esse estatuto até 1886. Os russos fizeram de Kars uma província dependente do governo-geral da Transcaucásia, com centro em Tbilisi; da elviye-i selâse, uma população que chegava a 100.000 pessoas foi obrigada a emigrar para o lado de Erzurum.", "e5049807"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["A ocupação da Bósnia-Herzegovina e de Novi Pazar pela Áustria-Hungria", "e5f901df"], "d": ["Apoiando-se na autorização dada pelo Tratado de Berlim, os exércitos austro-húngaros entraram na Bósnia; embora o governo otomano tivesse aceitado não resistir, a população local muçulmana e ortodoxa de Sarajevo e Mostar pegou em armas e ofereceu durante três meses uma resistência dura. A ocupação só pôde ser concluída a 20 de outubro de 1878. A soberania jurídica do sultão subsistiu no papel até 1908, mas a Bósnia otomana de quatro séculos perdeu-se de facto e começou uma grande vaga de emigração muçulmana. Outros povoamentos perdidos na mesma data: Banja Luka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["O Decreto de Muharrem e a fundação da Administração da Dívida Pública", "02b7cc03"], "d": ["As negociações conduzidas com os representantes dos Estados credores depois da bancarrota de 1875 resultaram no decreto de 28 de Muharrem de 1299 (20 de dezembro de 1881): o capital da dívida foi reduzido em mais de metade e, em contrapartida, as rubricas de receita mais produtivas, como as taxas do sal, do tabaco, da seda, do selo e do peixe, foram transferidas para a Administração da Dívida Pública, dirigida diretamente pelos credores. Esta administração, que empregava milhares de funcionários, converteu-se numa organização financeira separada dentro do Estado. É considerada a data em que terminou de facto a independência financeira otomana.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakin — o único porto que não caiu perante o Mahdi", "5a37b198"], "d": ["Enquanto, a partir de fevereiro de 1884, todas as regiões do Sudão oriental, exceto Suakin, passavam para o domínio de Muhammed Ahmed al-Mahdi, o porto manteve-se de pé com a proteção militar de uma força inglesa de três batalhões comandada pelo general Graham. Foi o início de um período em que se separaram a situação de facto e a de direito: embora a costa estivesse de facto sob controlo militar inglês, o seu vínculo administrativo seria retirado ao Egito em 1885 e ligado diretamente à província do Iémen, isto é, à Sublime Porta — essa ordem durou até 1888, quando terminou com a ocupação de Zeila pela França.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["A morte de Midhat Paxá na masmorra de Taif", "f4562261"], "d": ["Midhat Paxá, arquiteto do Kanûn-ı Esâsî e nome emblemático da Primeira Monarquia Constitucional, fora considerado culpado no Tribunal de Yıldız a propósito da morte de Abdülaziz e, comutada a pena de morte em exílio, fora enviado a Taif. Segundo o registo da TDV, na noite de 7 para 8 de maio de 1884 foi estrangulado na sua cela, e a causa oficial foi declarada como a doença 'şîrpençe'. A sua morte tornou-se, no tempo de Abdülhamid II, o símbolo da liquidação da oposição constitucional.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["A concessão da via-férrea Haydarpaşa-Ancara aos alemães", "5705b163"], "d": ["Por ordem do sultão, a concessão de construção e exploração da linha Haydarpaşa-Ancara foi dada ao banqueiro Alfred von Kaulla, representante do Deutsche Bank, e foi fundada a Companhia da Via-Férrea da Anatólia. Esta concessão foi o ponto de viragem que quebrou o monopólio anglo-francês nos transportes e na política externa otomanos e implantou a influência alemã. Juntamente com a concessão da linha de Bagdade, a atribuir à mesma companhia onze anos depois, nasceria o sonho 'Berlim-Bagdade', que se tornaria um dos principais eixos da rivalidade das grandes potências antes da Primeira Guerra Mundial.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["A fundação em Istambul da Sociedade de União Otomana", "b7187939"], "d": ["Quatro alunos da Escola Médica Militar fundaram, como organização secreta contra o governo despótico, a Sociedade de União Otomana; esta estrutura transformou-se em pouco tempo no Comité de União e Progresso, que reuniria sob o seu teto todos os elementos de oposição do movimento dos Jovens Turcos. A organização, baseada em células, juntou-se aos exilados na Europa e aos oficiais de Salónica. O quadro que faria proclamar a Segunda Monarquia Constitucional em 1908 e que governaria o Estado sozinho depois de 1913 saiu desta pequena célula de estudantes.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["O Assalto ao Banco Otomano: a ação dos militantes dashnaks em Galata", "08b3095f"], "d": ["Um grupo armado da organização arménia Dashnaktsutyun, com o fim de chamar a atenção da Europa para a questão arménia, assaltou a sede do Banco Otomano em Galata, tomou reféns e ameaçou fazer explodir o edifício. A crise terminou com a intervenção dos embaixadores, em troca de os militantes serem retirados do país num navio. Os sangrentos acontecimentos ocorridos em Istambul nos dias seguintes ao assalto foram decisivos para que a questão arménia se convertesse numa alavanca de intervenção internacional.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["O início da Guerra Otomano-Grega de 1897: a frente da Tessália", "33e490ab"], "d": ["Perante o desembarque de frota e tropas gregas em Creta e os ataques de bandos na fronteira da Rumélia, o Estado Otomano declarou guerra. O exército otomano, instruído pela missão de reforma alemã, avançou depressa na Tessália e em um mês tomou Yenişehir, Çatalca e Dömeke; o exército grego dispersou-se. Com a intervenção das grandes potências, os territórios conquistados foram devolvidos, mas a guerra ficou como a única vitória militar decisiva do tempo de Abdülhamid II e não impediu a perda de facto de Creta.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["A concessão da linha Konya-Bagdade aos alemães", "fd8b6cbd"], "d": ["Depois da visita do kaiser Guilherme II a Istambul e a Damasco em 1898, foi dada à Companhia da Via-Férrea da Anatólia a concessão preliminar da linha que se estenderia de Konya a Bagdade e a Bassorá. O projeto da Via-Férrea de Bagdade significava, para os otomanos, reforçar o controlo central sobre as províncias árabes e, para a Alemanha, chegar ao golfo Pérsico. Este projeto, a que a Inglaterra e a Rússia se opuseram com violência, tornou-se um dos dossiês mais controversos da rivalidade imperialista que conduziu à Primeira Guerra Mundial.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["O início da construção da Via-Férrea do Hejaz em Damasco", "62f58f68"], "d": ["A linha ordenada por Abdülhamid II por ordem imperial de 2 de maio de 1900 viu iniciar-se a construção a 1 de setembro de 1900, numa cerimónia oficial realizada em Damasco. O projeto, feito inteiramente com donativos recolhidos em todo o mundo islâmico e com o trabalho de engenheiros e soldados otomanos, reduziu de quarenta para cinco dias a viagem dos peregrinos entre Damasco e Medina. Era ao mesmo tempo uma obra de prestígio que consolidava a autoridade espiritual do califado e um investimento estratégico que reforçava o controlo militar sobre o Hejaz.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["O Programa de Mürzsteg: controlo internacional de reformas na Macedónia", "4c7464da"], "d": ["Depois da insurreição de Ilinden, os imperadores russo e austríaco encontraram-se em Mürzsteg e prepararam um novo pacote de reformas para a Macedónia. O programa previa a colocação de dois agentes civis estrangeiros junto do inspetor-geral otomano, a reorganização da gendarmaria por oficiais europeus e a alteração das fronteiras administrativas segundo o critério da nacionalidade. Embora a Sublime Porta tenha resistido, alegando lesão dos seus direitos de soberania, foi obrigada a aceitar perante a pressão conjunta; o programa foi um dos fatores fundamentais que aceleraram a organização unionista entre os jovens oficiais.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["A morte de Murad V", "396659a7"], "d": ["Murad V, que em 1876 ficou cerca de três meses no trono e foi deposto, depois das tentativas de o repor no trono viveu vinte e oito anos preso sob apertada vigilância e morreu de diabetes. Foi sepultado ao lado da mãe no Mausoléu de Cedîd Havâtîn, na Yenicami. Ficou na história como o sultão otomano que menos tempo esteve no trono.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["A perda de Sana para o imame Yahyâ", "e7f876cb"], "d": ["A insurreição iniciada em 1904 pelo imame zaidita Yahyâ Hamîdüddin resultou, em abril de 1905, na queda de Sana no fim de um cerco; a cidade saiu da administração otomana e, durante o cerco, surgiram a fome e a epidemia. A geografia montanhosa do Iémen, o comprimento das linhas de abastecimento e a legitimidade local do imamato zaidita tornavam frágil o domínio otomano ali desde a sua fundação. A cidade seria retomada cinco meses depois a custo de pesadas perdas, mas a questão do Iémen não se encerraria até 1918.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["O Atentado de Yıldız: ataque à bomba contra Abdülhamid II", "1ee2e1a6"], "d": ["A organização Dashnaktsutyun perpetrou o atentado fazendo explodir uma caleche com bomba de relógio junto à carruagem do sultão, que saía da cerimónia de sexta-feira (selâmlık); o atraso de alguns minutos de Abdülhamid, que conversava com o xeique do Islão (şeyhülislam), salvou-lhe a vida. Na explosão morreram vinte e seis pessoas e mais de cinquenta ficaram feridas. O caso endureceu ainda mais a obsessão de segurança do sultão e o seu governo despótico, baseado na organização de espiões; foi também tema do poema 'Bir Lahza-i Taahhur' de Tevfik Fikret.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["A reconquista de Sana: a repressão da revolta do imame Yahyâ", "dec3b8f9"], "d": ["A insurreição iniciada em 1904 sob a liderança do imame zaidita Yahyâ resultou, em abril de 1905, na queda de Sana, e na cidade surgiram a fome e a epidemia. Os exércitos de reforço comandados por Ali Rızâ Paxá e Ahmed Feyzi Paxá, numa operação conduzida entre 15 de julho e 1 de setembro de 1905 e apoiada também pelas forças de Taiz, retomaram a cidade a custo de pesadas perdas e a revolta foi reprimida. A campanha do Iémen trouxe ao exército otomano dezenas de milhares de baixas e um encargo financeiro enorme; entre os oficiais da Rumélia, o medo do 'exílio no Iémen' estava entre as queixas que alimentavam a organização unionista.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["A reunião da primeira Assembleia dos Deputados da Segunda Monarquia Constitucional", "e7fd2716"], "d": ["A assembleia formada pelas eleições em dois graus, realizadas após uma interrupção de trinta anos, foi aberta a 17 de dezembro de 1908 com o discurso do sultão, e para a sua presidência foi eleito Ahmed Rızâ Bey, líder do movimento dos Jovens Turcos. Composta por deputados turcos, árabes, albaneses, gregos, arménios e judeus, a assembleia foi a última grande tentativa do ideal otomanista. Mas a independência da Bulgária, a anexação da Bósnia e a proclamação da união de Creta à Grécia tinham ofuscado esse otimismo antes mesmo de a assembleia abrir.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["O Exército de Ação e a deposição de Abdülhamid II: a entronização de Mehmed V Reşad", "6a65a704"], "d": ["O Exército de Ação, que partiu de Salónica por causa do Incidente de 31 de Março, entrou em Istambul por quatro colunas na noite de 22 para 23 de abril e a 24 de abril o Palácio de Yıldız rendeu-se. A Assembleia Nacional Geral decidiu a 27 de abril a deposição de Abdülhamid II; o sultão foi enviado para Salónica e em seu lugar foi entronizado o irmão Mehmed V Reşad. O governo pessoal de trinta e três anos terminou assim, mas foi substituído por um novo período em que o sultão se tornara um símbolo e em que o Comité de União e Progresso governava com o apoio do exército.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["A Revolta da Albânia: resistência armada em Kosovo e Shkodër", "93ed30c6"], "d": ["A política fiscal centralista do governo unionista, a campanha de recolha de armas e a polémica sobre o alfabeto latino sublevaram as tribos albanesas, até então consideradas dos elementos mais fiéis ao Estado. Embora o exército comandado por Mahmud Şevket Paxá tenha reprimido a revolta com dureza, a agitação reacendeu-se em 1911 e 1912. Estas revoltas desgastaram o exército otomano às vésperas da Guerra dos Balcãs e aceleraram também o nascimento do movimento nacional albanês.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["O Tratado de Ouchy: a cedência de Trípoli de Barbaria e Benghazi à Itália", "4ffa1fd2"], "d": ["A Sublime Porta, que não podia arriscar um conflito em duas frentes perante os preparativos de guerra dos Estados balcânicos, assinou com a Itália uma paz secreta na localidade suíça de Ouchy e cedeu Trípoli de Barbaria e Benghazi. O Estado Otomano perdeu assim o seu último território em África; em contrapartida, foi prometida a devolução de Rodes e do Dodecaneso ocupados pela Itália, mas essa promessa nunca foi cumprida. Quando o tratado foi assinado, a Guerra dos Balcãs já tinha começado.", "d54a35d9"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["A ocupação de Lemnos pela Grécia", "9555af1d"], "d": ["Na Primeira Guerra dos Balcãs, a frota grega ocupou Lemnos; o porto de Mudros da ilha tornou-se base para o bloqueio do estreito de Çanakkale. A ilha foi deixada à Grécia em Lausana (24 de julho de 1923).", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["A ocupação de Taso pela Grécia", "6c03c7f0"], "d": ["Na Primeira Guerra dos Balcãs, a Grécia ocupou Taso e Samotrácia.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["A ocupação de Samotrácia pela Grécia", "911e82a3"], "d": ["Na Primeira Guerra dos Balcãs, a Grécia ocupou Samotrácia.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["A ocupação de Lesbos pela Grécia", "6b2b07ba"], "d": ["A frota grega desembarcou em Lesbos; a ilha foi tomada pelo exército e pela frota gregos no fim da Primeira Guerra dos Balcãs. A Conferência de Londres (maio de 1913) confirmou a situação.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["O desembarque grego em Quios", "901c6539"], "d": ["Os gregos desembarcaram em Quios, bombardeada a 7 de abril de 1912 na Primeira Guerra dos Balcãs; a guarnição otomana rendeu-se a 3 de janeiro de 1913. A ilha foi deixada à Grécia pelo Tratado de Lausana (24 de julho de 1923).", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["O assassinato do grão-vizir Mahmud Şevket Paxá em Istambul", "68e60e63"], "d": ["Mahmud Şevket Paxá, nomeado grão-vizir depois do Assalto à Sublime Porta, foi morto a tiro disparado contra a sua carruagem junto a Çarşıkapı quando se dirigia ao Ministério da Guerra. O Comité de União e Progresso, imputando o atentado à oposição, desencadeou uma vasta vaga de detenções e execuções, e o Partido da Liberdade e Entente foi liquidado de facto. Com este caso, ficou definitivamente estabelecida a ditadura de partido único dos unionistas, assente no triunvirato Enver-Talat-Cemal.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["O início da Segunda Guerra dos Balcãs: a disputa da partilha entre os aliados", "48d088a2"], "d": ["Os aliados balcânicos, que não conseguiram repartir os territórios tomados aos otomanos pelo Tratado de Londres, caíram uns contra os outros; a segunda guerra começou com o ataque da Bulgária às posições sérvias e gregas. Quando a Roménia e Montenegro entraram também na frente contra a Bulgária, o exército búlgaro ruiu. O Estado Otomano, aproveitando esta oportunidade, ultrapassou a linha Midye-Enez traçada pelo Tratado de Londres e recuperou a Trácia Oriental juntamente com Edirne.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["O Tratado de Istambul: paz com a Bulgária e o registo de Edirne", "c8c18b2d"], "d": ["O tratado assinado entre o Estado Otomano e a Bulgária depois da Segunda Guerra dos Balcãs, aceitando o rio Maritsa como fronteira, registou juridicamente que Edirne, Kırklareli, Dimotika e a Trácia Oriental ficavam com os otomanos. Dedeağaç ficou na Bulgária (Kavala, por sua vez, passara para a Grécia em julho de 1913, depois da ocupação búlgara do outono de 1912, e fora registada na Grécia pelo Tratado de Bucareste de 10 de agosto de 1913); regulou-se a troca recíproca de populações entre os dois países e os direitos dos muçulmanos na Bulgária. A garantia do único pedaço de território que pôde ser recuperado do desastre dos Balcãs é este texto. Outros lugares que passaram na mesma data: Gümülcine.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["A recuperação de Tenedos e Imbros — Tratado de Atenas", "ec084d09"], "d": ["De entre as ilhas do Egeu Norte ocupadas pela Grécia na Guerra dos Balcãs, Tenedos e Imbros, que guardam a entrada do Estreito, foram consideradas indispensáveis à defesa de Çanakkale nas negociações do Tratado de Atenas e foram devolvidas aos otomanos. As outras ilhas ficaram com a Grécia. Estas duas ilhas foram os últimos territórios que o império conservou no Egeu e foram também deixadas à Turquia em Lausana.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["O Tratado de Atenas: paz com a Grécia e a cedência de Salónica e Ioannina", "8e94def7"], "d": ["O tratado assinado entre o Estado Otomano e a Grécia reconheceu oficialmente a passagem para a Grécia de Salónica, Ioannina e da Macedónia do Sul, perdidas na Guerra dos Balcãs, e renunciou-se aos direitos otomanos sobre Creta. Regularam-se em pormenor os direitos de religião e de propriedade dos muçulmanos que ficavam na Grécia, o estatuto dos vakıfs e a nomeação dos mufties. O estatuto das ilhas do Egeu, esse, foi deixado sem solução, permanecendo como fonte de tensão contínua entre os dois Estados.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["A assinatura em Istambul do tratado secreto de aliança otomano-alemão", "0472efb3"], "d": ["Logo que rebentou a guerra na Europa, foi assinado, na mansão do grão-vizir Said Halim Paxá, um tratado secreto de aliança entre o Estado Otomano e a Alemanha; o texto previa que, no caso de a Rússia entrar em guerra contra a Alemanha, os otomanos ficassem também ao lado da Alemanha. O tratado foi escondido até do gabinete, sendo conhecido apenas por quatro pessoas. Três meses depois, com o Assalto ao Mar Negro, o Estado Otomano seria de facto arrastado para a guerra, e o destino do império ficaria atado a este documento.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["A abolição unilateral das capitulações", "ec773d18"], "d": ["O governo otomano, num momento em que a Europa estava ocupada com a guerra, declarou que abolia unilateralmente, a partir de 1 de outubro de 1914, as capitulações, que concediam aos estrangeiros privilégios judiciais, financeiros e aduaneiros. O fim desta ordem de privilégios de quatro séculos foi recebido no país com grande entusiasmo de independência e fizeram-se celebrações em Istambul. Todos os Estados, incluindo a aliada Alemanha, protestaram contra a decisão; as capitulações só passariam definitivamente à história em Lausana, em 1923.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["O Assalto ao Mar Negro: o bombardeamento de portos russos pela marinha otomana", "8ad4ef61"], "d": ["O Goeben e o Breslau (Yavuz e Midilli), que tinham fugido da Alemanha e se juntaram à marinha otomana como se tivessem sido 'comprados', saíram para o mar Negro sob o comando do almirante Souchon, bombardearam portos russos e afundaram navios. Esta ordem, dada por Enver Paxá às escondidas do gabinete, pôs fim de facto à neutralidade. Em uma semana, a Rússia, a Inglaterra e a França declararam guerra, e o Estado Otomano entrou de modo irreversível na Primeira Guerra Mundial.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["A tomada de Fao pelas forças anglo-indianas — a abertura da frente do Iraque", "08663813"], "d": ["Na manhã seguinte ao dia em que as potências da Entente declararam guerra ao Estado Otomano, a brigada anglo-indiana que aguardava no Bahrein desembarcou em Fao, na foz do Shatt al-Arab. A pequena unidade otomana da arruinada fortaleza de Fao retirou-se sob o fogo dos navios de guerra e a estação da linha telegráfica da Índia caiu nas mãos dos ingleses. A frente do Iraque ficou assim aberta.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["A proclamação da Jihad Maior: a leitura da fetva de jihad na Mesquita de Fatih", "2a6174e8"], "d": ["As cinco fetvas dadas pelo xeique do Islão Ürgüplü Hayri Efendi foram lidas na Mesquita de Fatih em nome do califa-sultão, convocando todos os muçulmanos para a jihad contra as potências da Entente. Este lance, em que a Alemanha depositava grandes esperanças, visava sublevar os muçulmanos das colónias inglesas e francesas. A esperada insurreição geral não se produziu; pelo contrário, a revolta, dois anos depois, do emir de Meca, o xarife Hussein, com apoio inglês, mostrou de forma amarga os limites da influência política do califado.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["A rendição de Kürne aos ingleses", "621d36b0"], "d": ["As forças do governador de Bassorá, Subhi Bey, que se tinham retirado, após a queda de Bassorá, para Kürne, onde se juntam o Tigre e o Eufrates, renderam-se na manhã de 9 de dezembro de 1914, depois dos combates de 4 a 8 de dezembro.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["A colocação do Egito sob protetorado inglês e a proclamação do sultanato", "55d4e520"], "d": ["Com a entrada do Estado Otomano na guerra, a Inglaterra declarou que colocava oficialmente sob o seu protetorado o Egito, que mantinha de facto ocupado desde 1882; o quediva Abbas Hilmi Paxá, que continuava ligado aos otomanos, foi deposto e em seu lugar foi posto Hüseyin Kâmil com o título de 'sultão'. Assim, a soberania jurídica otomana, que durava desde 1517, foi posta termo unilateralmente. A Sublime Porta não reconheceu a decisão e dois meses depois tentou recuperar o Egito com a Operação do Canal.", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["A Operação de Sarıkamış: catástrofe na frente do Cáucaso", "5cbde7f0"], "d": ["Enver Paxá, com o fim de recuperar Kars-Ardahan-Batum, perdidas em 1878, e de sublevar os turcos do Cáucaso, lançou o III Exército, em pleno inverno, por cima das montanhas de Allahuekber, numa manobra destinada a envolver as forças russas. Devido ao equipamento de inverno insuficiente, ao abastecimento esgotado e a tempestades de neve que chegaram a trinta graus negativos, o exército derreteu antes de entrar em combate; dezenas de milhares de soldados morreram de frio. A operação foi uma das mais pesadas catástrofes otomanas na guerra e deixou a frente oriental indefesa durante dois anos.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["A Primeira Operação do Canal: ataque ao Suez através do deserto do Sinai", "02dd72f5"], "d": ["Cemal Paxá, comandante do IV Exército, organizou uma ofensiva através do deserto do Sinai com o fim de libertar o Egito da ocupação inglesa e de encerrar à navegação o Canal do Suez. Embora as tropas otomanas tenham alcançado a margem oriental do canal e algumas conseguido atravessá-lo, recuaram perante a superioridade inglesa e por não se ter produzido a esperada insurreição popular egípcia. A operação não atingiu o seu objetivo, mas criou um efeito estratégico indireto ao obrigar a Inglaterra a manter uma grande força no Egito.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["A promulgação da Lei de Deslocação e Reassentamento (Tehcir)", "2f2bc22c"], "d": ["Após a revolta de Van e o avanço russo, o governo promulgou a lei temporária que permitia aos comandantes do exército transferir para outras regiões a população considerada perturbadora da segurança na retaguarda da frente, e o sultão sancionou-a a 27 de maio de 1915. Em resultado da aplicação, a maior parte da população arménia das províncias orientais e meridionais da Anatólia foi deslocada na direção da Síria e de Mossul; durante o transporte houve perdas de vidas muito grandes, devido a doenças, fome e ataques. A decisão continua a ser a questão mais pesada e, ainda hoje, mais controversa dos últimos anos do Império Otomano.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["As tropas otomanas retomaram Muş à ocupação russa", "fb1be113"], "d": ["Seis meses depois da primeira ocupação russa de Muş, o XVI Corpo otomano entrou na vila no contra-ataque de Bitlis-Muş.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Muş passou de novo para as mãos russas", "43ad8a03"], "d": ["Com o contra-ataque russo, o destacamento otomano evacuou Muş; a vila voltou à ocupação russa entre 22 e 25 de agosto de 1916 e permaneceu em suas mãos até à primavera de 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Muş foi libertada definitivamente da ocupação russa", "f0e89703"], "d": ["Muş, que caíra sob ocupação russa na Primeira Guerra Mundial, foi definitivamente retomada pelas forças otomanas a 1 de maio de 1917.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["A morte de Abdülhamid II no Palácio de Beylerbeyi", "c9662582"], "d": ["Abdülhamid II, deposto em 1909 e levado primeiro para Salónica e, com a perda da cidade na Guerra dos Balcãs, para Istambul, onde era mantido em prisão domiciliária no Palácio de Beylerbeyi, faleceu. Durante o seu reinado de trinta e três anos procurara ganhar tempo mantendo o Estado afastado das guerras, mas ficara também associado ao governo despótico. O seu funeral, com grande multidão, foi sepultado no Mausoléu de Mahmud I, em Divanyolu; a sua morte coincidiu com um ano de guerra em que a ordem que fundara já fora há muito liquidada.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["O Tratado de Brest-Litovsk: a recuperação de Kars, Ardahan e Batum", "da82636f"], "d": ["O tratado assinado entre a Rússia, que se retirara da guerra após a revolução bolchevique, e as potências da Aliança, encerrou a frente oriental e devolveu ao Estado Otomano Kars, Ardahan e Batum (Elviye-i Selâse), que perdera pelo Tratado de Berlim de 1878. Foi o único ganho territorial obtido na história otomana depois de quarenta anos. Mas, depois do Armistício de Mudros, a região voltaria a perder-se, e a solução definitiva viria com o Tratado de Kars de 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["As tropas otomanas entraram em Artvin", "ca7d1778"], "d": ["As tropas otomanas, que a 25 de março transpuseram a fronteira de 1914, marcharam sobre o Elviye-i Selâse, cuja fronteira anterior a 1878 Brest-Litovsk restituíra, e entraram em Artvin a 28 de março de 1918. Artvin fora cedida à Rússia em 1878 como parte do sanjaco de Batum; o artigo Artvin da TDV escreve o regresso apenas como 'março de 1918', e o dia é dado por Sarı.", "224ac850"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahan caiu nas mãos do exército turco", "7fd9e3db"], "d": ["Na operação do Elviye-i Selâse, o exército otomano tomou Ardahan a 3 de abril de 1918, depois de Artvin; Ardahan caíra em 1877, na Guerra de Noventa e Três, e fora cedida à Rússia em 1878. Kars seria tomada um mês depois, a 25 de abril.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["A recuperação de Batum", "d37a1a0d"], "d": ["O exército otomano que avançou para leste depois da retirada da Rússia da guerra, pelo Tratado de Brest-Litovsk, recuperou quarenta anos depois o porto de Batum, perdido em 1878. Este porto, no extremo oriental do mar Negro, era a saída marítima do petróleo de Baku. O ganho durou apenas sete meses; depois do Armistício de Mudros, a região seria evacuada.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selâse: Kars entrou na administração otomana", "02cbf0b3"], "d": ["Em Brest-Litovsk fora decidida a devolução dos três sanjacos perdidos pelo Tratado de Berlim de 1878 — Kars, Ardahan e Batum; o exército otomano entrou em Ardahan a 3 de abril, em Batum a 14 de abril e em Kars a 25 de abril de 1918, e a administração foi estabelecida de facto. Estas terras, conhecidas pelo nome de 'Elviye-i Selâse', foram consideradas a compensação da perda que durava desde a Guerra de Noventa e Três. Seriam perdidas de novo depois do armistício e só ficariam definitivamente ligadas à Turquia pelo Tratado de Kars de 1921.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Iğdır foi tomada — o avanço no vale do Aras", "87ebf4d3"], "d": ["No quadro da ofensiva iniciada em fevereiro de 1918, as tropas turcas derrotaram as unidades arménias em Sardarabad, a norte do Aras, e tomaram Iğdır a 20 de maio de 1918. Iğdır não estava incluída no Elviye-i Selâse, mas era o distrito de Sürmeli da província de Erevan; cerca de 180 anos depois, estabeleceu-se na região a primeira administração otomana.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["A morte de Mehmed V Reşad e a entronização de Mehmed VI Vahdeddin", "d302ba07"], "d": ["Mehmed V Reşad, cujo reinado de nove anos decorreu entre as guerras da Trípoli de Barbaria, dos Balcãs e Mundial, faleceu no período mais crítico da guerra e em seu lugar subiu ao trono o irmão Vahdeddin, com o nome de Mehmed VI. O novo sultão procurou libertar-se da tutela do quadro unionista; quatro meses depois, quando se assinou o armistício, teria de conduzir a liquidação do império. Foi o trigésimo sexto e último sultão da dinastia otomana.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["A chegada da frota da Entente diante de Istambul e a ocupação de facto da cidade", "d10cb14d"], "d": ["Depois do Armistício de Mudros, uma frota aliada de mais de sessenta unidades, composta por navios ingleses, franceses, italianos e gregos, fundeou diante de Dolmabahçe e Istambul passou de facto à ocupação. Quatrocentos e sessenta e cinco anos depois, a capital passava pela primeira vez ao controlo de soldados estrangeiros. A frase 'Assim como vieram, irão embora', que se diz ter sido pronunciada no mesmo dia por Mustafa Kemal Paxá ao desembarcar em Haydarpaşa e ver o panorama, seria uma das frases emblemáticas da Luta Nacional.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["A retirada na região do Aras: Iğdır foi evacuada", "57572ab4"], "d": ["Em conformidade com a disposição do Armistício de Mudros sobre a retirada para trás da fronteira de 1914, Yakup Şevki Paxá, por ordem de 21 de novembro, mandou recolher até 4 de dezembro as unidades que estavam fora da fronteira de Brest-Litovsk; Iğdır e os arredores foram por completo evacuados nesta data. Em seguida, o Governo Turco do Aras foi derrubado pelos arménios no final de dezembro de 1918.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Os ingleses instalaram-se em Artvin", "e2cb3153"], "d": ["Como o Armistício de Mudros, de 30 de outubro de 1918, estipulava a retirada do exército otomano para trás da fronteira de 1914, Artvin foi evacuada e, a 17 de dezembro de 1918, ocupada pelos ingleses. Segundo o artigo Artvin da TDV, a ocupação inglesa durou até abril de 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["A administração britânica em Batum depois de Mudros", "9dd768fc"], "d": ["Em virtude do Armistício de Mudros de 30 de outubro de 1918, o Estado Otomano foi obrigado a retirar-se de Batum; a cidade foi ocupada por unidades britânicas a 24 de dezembro de 1918. Batum, feita em abril de 1918 centro de sanjaco autónomo, permaneceu desta data até julho de 1920 sob controlo inglês.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ardahan passou ao domínio georgiano", "97cf47f6"], "d": ["Ardahan, evacuada após Mudros, foi ocupada pelas forças georgianas a 20 de abril de 1919, nos dias em que o Governo do Sudoeste do Cáucaso foi dissolvido pelos ingleses. O domínio georgiano duraria até 23 de fevereiro de 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Preston entregou a administração de Kars ao governador arménio", "efa81cb0"], "d": ["O comandante inglês Preston, que a 12-13 de abril de 1919 dissolvera o Governo do Sudoeste do Cáucaso, aboliu a 30 de abril de 1919 o governo provisório de conselho e entregou a administração da cidade ao arménio Karganof, feito governador de Kars; começou em Kars o período da administração arménia, que durou até à vitória de Kâzım Karabekir a 30 de outubro de 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["O Congresso de Erzurum: a decisão de resistência nacional das províncias orientais", "41ef0457"], "d": ["O congresso convocado pela Sociedade para a Defesa dos Direitos da Anatólia Oriental, depois de adiado por pressão inglesa, abriu com cinquenta e seis delegados e para a sua presidência foi eleito Mustafa Kemal Paxá, que se demitira do exército. O congresso proclamou que, dentro das fronteiras nacionais, a pátria é um todo, que mandato e protetorado são inaceitáveis e que, no caso de dissolução do governo, a nação tomaria nas mãos o seu próprio destino. Estas decisões formariam, seis meses depois, o núcleo do texto do Pacto Nacional.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["O Congresso de Sivas: a união da resistência nacional sob um só teto", "0e9ad36b"], "d": ["O congresso, que iniciou os trabalhos a 4 de setembro de 1919 na Sivas Sultânîsi, reuniu as sociedades de defesa de direitos de todos os cantos do país sob o nome de Sociedade para a Defesa dos Direitos da Anatólia e da Rumélia e elegeu uma Comissão Representativa. A proposta de mandato americano foi rejeitada depois de longas discussões. Com a declaração publicada a 11 de setembro, a Luta Nacional converteu-se num movimento político legítimo de centro único e começou uma luta de poder aberta com o governo de Istambul.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["O Protocolo de Amasya: as conversações entre o governo de Istambul e a Comissão Representativa", "40e6a6ab"], "d": ["Depois da queda de Damat Ferid e da formação do governo de Ali Rızâ Paxá, o ministro da Marinha Salih Paxá foi enviado a Amasya para conversar com a Comissão Representativa. Pelos protocolos alcançados, o governo de Istambul reconheceu de facto a existência do movimento da Anatólia; aceitaram-se a reunião da Assembleia dos Deputados, a realização livre das eleições e a preservação das fronteiras nacionais. Este foi o primeiro ganho político oficial obtido pela Luta Nacional diante de Istambul.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["A aprovação do Pacto Nacional na última Assembleia Otomana", "6322865e"], "d": ["O texto do Pacto Nacional, assinado por 121 deputados na última Assembleia dos Deputados otomana, estipulava a integridade indivisível das terras que ficavam dentro da linha de Mudros e onde vivia uma maioria muçulmano-turca, o plebiscito nas províncias árabes e na Trácia Ocidental, a abolição das capitulações e a plena independência política e financeira. O texto foi aprovado por unanimidade a 17 de fevereiro de 1920 e proclamado ao mundo. Esta declaração foi tanto o programa político da Luta Nacional como o mapa das fronteiras que seriam defendidas em Lausana; foi a causa direta de as potências da Entente ocuparem oficialmente Istambul a 16 de março.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Quando os ingleses se retiraram, Artvin ficou na Geórgia", "6d086b06"], "d": ["Segundo o artigo Artvin da TDV, a ocupação inglesa durou até abril de 1920; ao retirarem-se, os ingleses deixaram a cidade à Geórgia. Artvin ficou nas mãos da Geórgia até ao ultimato da TBMM de 23 de fevereiro de 1921.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Batum foi entregue à administração georgiana", "6523d095"], "d": ["A entrega oficial de Batum aos georgianos pelos ingleses realizou-se a 7 de julho de 1920 (o artigo Batum da TDV diz apenas 'julho de 1920'). O governo de Ancara protestou a 25 de julho contra a entrega, chamando-lhe 'ocupação'.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["O Tratado de Gümrü: o primeiro tratado internacional do governo da Grande Assembleia Nacional da Turquia", "9232c690"], "d": ["Quando o exército da frente oriental comandado por Kâzım Karabekir retomou Sarıkamış e Kars, a Arménia pediu a paz e, pelo tratado assinado em Gümrü, aceitou que não reconhecia Sèvres e renunciou às reivindicações territoriais a leste. Este primeiro tratado assinado pelo governo de Ancara foi o primeiro documento internacional a rejeitar de facto Sèvres e abriu à TBMM o caminho do reconhecimento jurídico. Assim, a fronteira oriental ficou garantida e tornou-se possível deslocar forças para a frente ocidental.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["A Primeira Batalha de İnönü: a primeira vitória do exército regular", "4add3719"], "d": ["O exército regular recém-formado deteve nas posições de İnönü as forças gregas que avançavam na direção de Bursa e obrigou-as a recuar. Este êxito, de escala militar limitada, foi enorme nas suas consequências políticas: o governo de Ancara foi convidado à Conferência de Londres, abriu-se o caminho ao Tratado de Moscovo com a Rússia Soviética e foi aprovada a Lei da Organização Fundamental. A confiança da opinião pública interna no exército regular consolidou-se também com esta vitória.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["A Segunda Batalha de İnönü: a segunda rutura da ofensiva grega", "a974521c"], "d": ["O exército grego, que não obtivera resultados na Conferência de Londres, passou a uma nova ofensiva a partir de Bursa e de Uşak, mas foi de novo detido nas cristas de İnönü e obrigado a recuar. O telegrama de Mustafa Kemal Paxá a İsmet Paxá 'Vós aí não vencestes apenas o inimigo, mas também o infortúnio da nação' foi escrito depois desta vitória. A batalha elevou o prestígio internacional da Luta Nacional e acelerou o processo de retirada da Itália da Anatólia.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["O Acordo de Ancara: paz com a França e o encerramento da frente sul", "35fc32db"], "d": ["Com o acordo assinado em Ancara com a França depois da vitória do Sakarya, terminou a guerra na frente sul; as forças francesas evacuaram Çukurova e o Sudeste, incluindo Adana, Antep, Maraş e Urfa, e recuaram para a fronteira da Síria. Uma das potências da Entente reconheceu assim de facto o governo de Ancara e abriu-se a primeira fenda na frente de Sèvres. As armas recebidas das regiões evacuadas e as unidades que ficaram livres tiveram um papel crítico na preparação da Grande Ofensiva.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["O Armistício de Mudanya: a cedência de Istambul e dos Estreitos sem guerra", "ac0d9baf"], "d": ["Quando, depois da Grande Ofensiva, o exército turco se viu frente a frente com as forças inglesas em Çanakkale e İzmit, a conferência reunida em Mudanya resultou, após onze dias de regateio duro, num armistício. Aceitou-se que a Trácia Oriental, até ao Maritsa, fosse evacuada pela Grécia em quinze dias e entregue à administração turca, e que Istambul e os Estreitos fossem entregues pelo tratado de paz. Assim, a fase armada da Luta Nacional terminou com uma vitória diplomática ganha sem se disparar um único tiro, e abriu-se a porta de Lausana.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["A partida de Mehmed VI Vahdeddin de Istambul e a eleição de Abdülmecid Efendi como califa", "8ab0e847"], "d": ["Mehmed VI Vahdeddin, o último sultão, cuja posição se tornou discutível depois da abolição do sultanato, partiu de Istambul na manhã de sexta-feira, 17 de novembro de 1922, no couraçado inglês Malaya, e foi para Malta. A TBMM, dois dias depois, a 19 de novembro, elegeu Abdülmecid Efendi como califa sem poderes políticos. O reinado dinástico otomano de seiscentos e vinte e três anos terminou assim de facto; o califado continuaria, de forma simbólica, por mais quinze meses. Vahdeddin, que passou a Malta e depois a Itália, instalou-se na Villa Nobel em San Remo; sem obter resultado nos pedidos que fez para ser acolhido num país muçulmano, morreu ali a 16 de maio de 1926, reiterando que nunca renunciara aos direitos de sultanato e califado.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["A morte do último sultão Mehmed VI Vahdeddin em San Remo", "7149ed0e"], "d": ["Mehmed Vahdeddin, último sultão otomano, que se instalara em San Remo, em Itália, depois de deixar Istambul, morreu a 16 de maio de 1926, sem ter recebido a notícia da reunião do congresso do califado (13 de maio de 1926), ao qual comunicara que nunca renunciara aos direitos de sultanato e califado. Estava em grande aperto de dinheiro; devia 60.000 liras aos comerciantes de San Remo e os credores, ao saberem da sua morte, mandaram penhorar os bens da sua casa.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["A conquista da região de Bolu por Konuralp — Mudurnu, Konurapa e Bolu", "e245cd27"], "d": ["Konuralp, um dos comandantes de Orhan Gazi, dirigiu-se à região montanhosa a leste do Sakarya e ligou à administração otomana a região de Mudurnu, Konurapa e Bolu; a localidade na planície de Düzce ficou conhecida pelo seu nome. A data exata da conquista não é conhecida; a narrativa assenta na tradição de Âşıkpaşazâde. A região era então uma zona fronteiriça que mudava de mãos entre os Candaroğulları e Bizâncio; a conquista aproximou pela primeira vez os otomanos da costa ocidental do mar Negro. Depois da Batalha de Ancara, a região passaria de novo aos Candaroğulları, mas seria definitivamente recuperada no tempo do Conquistador.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["A tomada das vilas bizantinas a sul do Mármara — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["Depois de tomadas Niceia e İzmit, as vilas que restavam a Bizâncio a oeste da planície de Bursa foram passando uma a uma para a administração otomana. Gölyazı, em torno do lago Uluabat, Kirmasti e Mihaliç, ao longo do rio Susurluk, completaram o corredor que liga a costa sul do Mármara às terras de Karesi. Estas vilas renderam-se, durante muito tempo sem sofrer cerco, quando o seu entorno foi cortado; a presença bizantina na região ficou assim comprimida no golfo de Gemlik.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Gördüs (Corinto) passou ao Despotado da Moreia", "392495eb"], "d": ["Corinto, que desde 1358 era timar da família florentina Acciaiuoli dependente do principado de Acaia, passou em 1395 para as mãos de Teodoro, déspota bizantino da Moreia. A cidade permaneceu a partir daí sob a administração do despotado até à conquista otomana.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["A anexação do Beylik dos Hacıemîroğulları — Ordu e Ünye", "c064f07f"], "d": ["O beylik turcomano que Bayram Bey fundara em torno de Ordu e que o filho Hacı Emîr alargou na década de 1350, com centro na atual Eskipazar, era um pequeno mas estratégico Estado costeiro: era a única zona de domínio independente entre Samsun e Trebizonda. Emîr Süleyman manifestara a sua obediência em 1398 na operação de Bajazeto I em Canik, e depois da Batalha de Ancara o beylik voltara a ficar livre. No tempo de Murad II, nos mesmos anos da liquidação dos Tâceddinoğulları, as terras do beylik foram ligadas diretamente à administração otomana e a costa do mar Negro uniu-se numa só mão, de Samsun a Giresun.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["A conquista de Gördüs (Corinto)", "87a2bc59"], "d": ["Na campanha da Moreia do Conquistador, a fortaleza de Acrocorinto foi cercada durante três meses e foi finalmente recebida por via pacífica. O istmo de Corinto, considerado a porta da Moreia, passou assim aos otomanos.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["A ligação de Montenegro à administração otomana — Cetinje", "7fdb7cc8"], "d": ["Quando a dinastia Crnojević, que governava Zeta, abandonou o domínio em 1496, a região montanhosa de Montenegro, que era o quintal de Shkodër, foi posta sob administração otomana direta e organizada primeiro como sanjaco separado e, depois, como parte do sanjaco de Shkodër. O mosteiro de Cetinje foi deixado no lugar como centro religioso da região. Devido à aspereza da geografia, a administração aqui nunca funcionou tão apertada como nas planícies; dois séculos depois, o governo dos vladikas, nascido do mesmo mosteiro, seria o núcleo da independência de facto.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["A aceitação do domínio otomano pela fortaleza de Bayezid na Campanha dos Dois Iraques", "f29e2e17"], "d": ["Quando o grão-vizir Ibrahim Paxá chegou, na Campanha dos Dois Iraques, aos arredores de Bingöl, as fortalezas de Van, Toprakkale, Avnik e Bayezid, juntamente com muitas tribos curdas da região, concordaram em entrar no domínio otomano. Bayezid aderira aos otomanos em 1514, na campanha de Yavuz, mas, quando o exército voltou, os safávidas tinham retomado a região.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Tabriz voltou a passar para os safávidas — o regresso dos Dois Iraques", "80b8b761"], "d": ["Na Campanha dos Dois Iraques, o exército entrara em Tabriz, mas, como o verdadeiro objetivo era Bagdade, não se deixara na cidade uma guarnição permanente. Quando o exército, que passara o inverno em Bagdade, voltava para oeste, o xá Tahmasb entrou de novo no Azerbaijão, evacuado, e retomou Tabriz. Este foi o padrão repetido das guerras otomano-safávidas: Tabriz foi tomada cinco vezes e nas cinco não pôde ser conservada; a cidade só receberia uma guarnição otomana duradoura em 1585.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["A queda de Van e Erciş nas mãos de Tahmasb (a posição otomana terminou em 1534-35)", "cb93d561"], "d": ["Na região que dera Van ao domínio otomano em 1534, Ulama Paxá resistiu no Castelo de Van ao cerco safávida; a fortaleza passou para as mãos dos safávidas, e as forças safávidas que cercavam Erciş tinham recuado com a ajuda otomana. Quando o Legislador chegou a Ahlat (23 de setembro de 1535), Van já estava nas mãos de Tahmasb. Van ficou safávida até 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["A passagem do sanjaco de Bayezid para o domínio safávida (Van e Erciş já eram safávidas em 1535)", "806a2cf1"], "d": ["O sanjaco de Bayezid, no meio da fronteira otomano-safávida, voltou a cair nas mãos do Irão (Kaya 2017 refere-o 'juntamente com Van e Erciş'; mas Van e Erciş, segundo Karataş 2025 e a TDV, tinham voltado aos safávidas a 22 de setembro de 1535 — ver o item anterior); nesta mudança de mãos, alguns lugares do sanjaco ficaram arruinados. O sanjaco mudou de mãos várias vezes entre os dois Estados até ao último quartel do século XVI.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["A passagem do sanjaco de Bayezid de novo para os otomanos durante a Campanha de Nakhichevan", "cf0171fa"], "d": ["Durante a terceira campanha da Pérsia (Nakhichevan) do Legislador, o sanjaco de Bayezid foi de novo posto sob administração otomana. Na campanha de 1554, Bayazıt foi uma base importante para o exército; o sanjaco entrou definitivamente na soberania otomana em 1578.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["A perda de Erevan para o xá Abbas", "34413cf2"], "d": ["Quando a frente oriental ficou indefesa nos anos em que as revoltas celalis bloqueavam a Anatólia, o xá Abbas, que reorganizara o exército à europeia, passou à ofensiva. A fortaleza de Revan, que Ferhad Paxá mandara construir em 1583, rendeu-se depois de sete meses de cerco. O primeiro elo da linha do Cáucaso ganha pelo Tratado de Ferhad Paxá estava quebrado e, nos três anos seguintes, todo o Cáucaso Meridional se perderia.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["A perda de Tbilisi e Gence", "3fb51753"], "d": ["Depois da queda de Revan, o exército safávida avançou ao longo do vale do Kura; Gence, centro de Karabakh, e Tbilisi, capital da Geórgia, perderam-se uma após outra. O Estado Otomano conduzia ao mesmo tempo a longa guerra de treze anos na frente austríaca e lidava com os celalis na Anatólia; não havia forças para enviar para leste. Assim, a ordem das vastas províncias do Cáucaso, estabelecida pelo Tratado de Ferhad Paxá de 1590, terminou de facto.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["A perda de Şirvan — Şamahı, Baku e Derbent", "81beab11"], "d": ["A província de Şirvan, na costa do Cáspio, ganha pelas campanhas de 1578-1585 de Özdemiroğlu Osman Paxá, dera às finanças otomanas um rendimento importante como principal fonte do comércio da seda. A operação do xá Abbas para norte liquidou esta província tomando sucessivamente Şamahı, Baku e Derbent. A perda não foi apenas territorial: a rota da seda persa que afluía à Europa através dos otomanos saiu também do controlo, e o Estado safávida passou a comercializar a seda pelo oceano Índico.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["A perda de Taiz", "65f20d53"], "d": ["Os otomanos abandonaram em 1038 (1629) Taiz, juntamente com o domínio do Iémen deixado ao governo kāsımî de Sana — o primeiro grande passo do processo em que os imames zaiditas retomaram o Iémen interior.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["A perda do Iémen — o domínio dos imames Kāsımî", "49e83e3c"], "d": ["O Iêmen era província otomana desde 1538; porém, a resistência dos imãs zaiditas nunca cessou. A revolta iniciada pelo imã al-Qasim espalhou-se por todo o país sob seu filho al-Mu'ayyad Muhammad, e as guarnições otomanas foram sitiadas uma após outra. Nos anos em que Murad IV se concentrava em Bagdá e Erevan, não foi possível enviar reforços; Taiz fora perdida em 1629, enquanto Moca foi evacuada em 22 de outubro de 1635, na fase final do mesmo colapso. Em 1635, as últimas tropas em Sanaa e Zabid também evacuaram o Iêmen. Assim, a costa oriental do mar Vermelho permaneceu fora do império por duzentos e trinta e sete anos, só sendo recuperada em 1872. Segundo a TDV İslâm Ansiklopedisi, Lahij (al-Hawta) esteve em mãos otomanas até 1635; a partir dessa data, os imãs zaiditas tornaram-se influentes.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["A evacuação de Moca", "c6b3061a"], "d": ["Mustafa Bey evacuou Moca a 10 de Cemâziyelevvel de 1045 (22 de outubro de 1635) com a força e as armas que restavam; em seguida, Hasan b. Kāsım, filho do imame Kāsım, nomeou os seus próprios homens para Zabid e Moca e estabeleceu também na costa de Tihâme o controlo Kāsımî.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["A perda de Lahsa para o Emirado de Banu Khalid", "a9b6131a"], "d": ["Lahsa era uma província criada em 1550 para fechar a Portugal a costa ocidental do golfo de Bassorá; mas estava muito longe de Istambul, na ponta de uma única rota do deserto. Nos anos em que o cerco de Creta esgotava os recursos, a tribo Banu Khalid da região, sob a liderança de Berrâk b. Gureyr, expulsou a guarnição otomana e fundou o seu próprio emirado. A costa ocidental do golfo ficou durante século e meio nos emirados tribais; passaria em 1795 aos sauditas e em 1871 de novo aos otomanos.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["A perda de Preveza e Vonitsa para Veneza — a abertura da costa do Epiro", "1201204c"], "d": ["Veneza, que aderira à Santa Aliança, antes de iniciar a campanha da Moreia tomou as duas fortalezas que guardam a entrada do golfo de Ambrácia: Preveza e, na margem oposta, Vonitsa. No mesmo verão caíra também Ayamavra (Lefkada). Estas três posições permitiram à frota penetrar com segurança do mar Jónico para o interior da Grécia e tornaram-se a base da operação da Moreia, que começaria no ano seguinte. Preveza e Vonitsa foram também deixadas a Veneza em Požarevac; só voltariam à administração otomana em 1798.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["A perda de Szolnok — a dissolução da linha do Tisza", "51c2c8ef"], "d": ["Depois da queda de Uyvar em agosto, o exército habsburgo voltou-se para sul e tomou Szolnok, cabeça de ponte sobre o rio Tisza. A cidade era a única passagem segura entre Buda e a Transilvânia; a sua perda significava o corte entre si das fortalezas otomanas da metade oriental da Hungria. No cerco de Buda, no ano seguinte, o facto de se ter cortado a via de abastecimento foi decisivo.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["A perda de Modon para Veneza", "114c9cc0"], "d": ["Modon, no extremo sudoeste da península da Moreia, era o porto que Veneza perdera três séculos antes e a que chamava 'um dos dois olhos do Estado'. A fortaleza, cercada depois da queda de Koron, foi tomada batida ao mesmo tempo por terra e por mar. A operação da Moreia de Morosini apoderou-se assim de toda a costa ocidental da península e abriu-se o caminho para o interior.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["A perda de Peçuy", "99d54cf4"], "d": ["Depois da queda de Buda em setembro, as forças habsburgas desceram para sul a oeste do Danúbio e tomaram Peçuy, otomana desde o tempo do Legislador. A cidade, conhecida pela Mesquita de Gazi Kâsım Paxá, era um dos mais desenvolvidos centros de sanjaco da província de Buda. A sua perda significava a abertura do caminho que desce para a planície de Mohács; no ano seguinte, o Segundo Desastre de Mohács seria vivido precisamente ali.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["A perda de Szeged", "9fbee1b2"], "d": ["Szeged, no ponto onde se juntam os rios Tisza e Maros, era a porta sul da planície húngara e guardava o caminho para a província de Timișoara. A fortaleza, cercada depois de Buda e Peçuy terem caído no mesmo outono, rendeu-se em pouco tempo. A perda de três fortalezas numa só estação era o sinal de que a estrutura administrativa otomana na Hungria, estabelecida desde 1541, começava a ruir.", "63dea9ab"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["A perda de Balyabadra (Patras) — a porta norte da Moreia", "b9cff63c"], "d": ["Balyabadra, na entrada do golfo de Corinto, era o porto que controlava a passagem entre a Moreia e a Rumélia. Depois de o exército veneziano tomar a cidade, caíram também uma após outra as fortalezas das duas margens do golfo e a península ficou totalmente isolada por terra. No fim desta operação, toda a Moreia passou a Veneza; a região seria governada até 1715 com o nome de 'Regno di Morea'.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["A cedência de Gördüs (Corinto) a Veneza", "9a25b6b9"], "d": ["Depois da queda de Balyabadra, Corinto foi deixada aos venezianos por via pacífica e a população muçulmana abandonou a cidade. Em agosto de 1687, o exército de Morosini reunia-se em Corinto para a campanha de Atenas.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["A perda de Eger", "983391aa"], "d": ["Eger fora tomada em 1596 pela campanha em que Mehmed III participou pessoalmente e tornara-se centro de uma província com o seu nome. Esta última grande fortaleza otomana da Hungria do Norte, depois do Segundo Desastre de Mohács, resistiu um ano completamente cercada e rendeu-se por fome. Com a sua perda, o flanco norte do Estado Otomano na Hungria foi totalmente liquidado.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["A perda de Székesfehérvár — a cidade da coroação dos reis húngaros", "c6147255"], "d": ["A cidade onde os reis húngaros foram coroados e sepultados durante séculos fora tomada em 1543 pelo Legislador e tornara-se um dos mais importantes centros de sanjaco da província de Buda. Cerca de dois anos depois da queda de Buda, a fortaleza, completamente cortada em redor, rendeu-se. Com esta perda, a presença otomana a oeste do Danúbio ficou comprimida em torno de Sirmia e Osijek.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["A perda de Szigetvár", "834910a7"], "d": ["Szigetvár era a fortaleza em que o sultão Solimão, o Legislador, morreu em 1566, durante o cerco, na sua décima terceira e última campanha; por isso tinha um lugar simbólico na memória otomana. Cento e vinte e três anos depois, quando caíram todas as fortalezas em seu redor, rendeu-se também a fortaleza protegida por pântanos. O mausoléu onde estavam sepultadas as entranhas do Legislador e a vila em seu redor foram destruídos depois de passarem para a administração habsburga.", "54f30d14"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["A perda de Várad", "6cce360d"], "d": ["Várad era a fortaleza-chave que se abre para a Transilvânia, tomada em 1660 por Köprülü Mehmed Paxá, que fez dela centro de uma província com o seu nome. A fortaleza, que ficou completamente só depois do desastre de Slankamen, rendeu-se por fome depois de um bloqueio de quase dois anos. Com a sua perda, a influência otomana sobre a Transilvânia terminou de facto e o domínio habsburgo estabeleceu-se a leste do Tisza.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["A perda de Yanova — o encerramento do caminho da Transilvânia", "4b5e30d8"], "d": ["Yanova era uma fortaleza tomada em 1658 que guardava a ligação entre Várad e Timișoara. Quando foi cortada em redor logo depois da queda de Várad, perdeu-se também. Assim, a província de Timișoara ficou totalmente isolada a norte e continuou a existir, até Karlowitz, como único território da Hungria que permanecia nas mãos dos otomanos.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["O estabelecimento do governo dos vladikas em Montenegro — a separação de facto de Cetinje", "a924b778"], "d": ["Nos anos em que a Guerra da Santa Aliança afrouxou o controlo otomano nos Balcãs, a metrópole à frente do mosteiro de Cetinje tornou-se um cargo que passava de pai para filho na família Petrović, e a região ganhou de facto uma administração separada. Graças à inacessibilidade das montanhas, este vladikado manteve-se durante dois séculos numa posição nem plenamente independente nem plenamente dependente; a sua independência jurídica só seria reconhecida pelo Tratado de Berlim de 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["A reconquista de Gördüs (Corinto)", "26f53e3a"], "d": ["A primeira grande paragem da campanha da Moreia de Damad Ali Paxá foi Corinto; os otomanos retomaram a cidade aos venezianos em junho de 1715 e daí avançaram para o resto da península.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["A ofensiva de Nâdir: a perda de Tabriz, Nakhichevan, Hemedan, Kirmanxá, Merâga e Kasr-ı Şîrîn", "d95efd59"], "d": ["As cidades do Irão Ocidental tomadas entre 1723 e 1727, aproveitando o colapso do Estado safávida, foram-se perdendo uma a uma com a ofensiva de Nâdir Han, que tomara de facto o poder no Irão. No Azerbaijão, Erdebil e Halhal caíram também nas mãos de Nâdir. A perda de Hemedan, Kirmanxá e Kasr-ı Şîrîn teve pesado eco em Istambul; o facto de o exército não ter saído em campanha, ficando à espera em Üsküdar, e de se ter procurado encobrir a perda foi uma das causas diretas da Revolta de Patrona Halil, que rebentaria seis semanas depois.", "3affcf18"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["O desastre de Baghavard (Arpaçay) — a perda do Cáucaso para Nâdir Han", "4262f54c"], "d": ["As províncias do Cáucaso tomadas em 1723-1725, aproveitando o colapso do Estado safávida, puderam ser conservadas durante dez anos. Nâdir Han, que tomara de facto o poder no Irão, infligiu ao exército otomano uma pesada derrota em Baghavard, perto de Revan; o serdar Abdullah Köprülü Paxá perdeu a vida no campo de batalha. Depois do desastre, Revan, Tbilisi, Gence e Şirvan foram evacuadas em meses. A fronteira oriental voltou à linha de Kasr-ı Şîrîn de 1639, que seria confirmada em 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["A perda de Bender para os russos", "0daca453"], "d": ["Depois do desastre da planície de Kartal, o exército otomano recuara para sul do Danúbio, e as fortalezas entre a Moldávia e Özi tinham ficado sozinhas. Bender, que guarda o ponto de passagem do rio Turla, foi tomada de assalto depois de um cerco de dois meses; a cidade foi saqueada. A perda da fortaleza quebrou o elo central da linha de defesa do mar Negro setentrional, e a seguir caíram também Akkirman e Kili. Em Küçük Kaynarca, Bender seria devolvida, mas voltaria a perder-se em 1806.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["A entrada do emirado de Sabah no Kuwait sob proteção otomana", "3584dba0"], "d": ["Segundo o artigo Kuwait da TDV, o porto fora fundado no início do século XVIII pela tribo Utub vinda de Najd, e a família Sabah assumira a administração para o fim do século. Nos mesmos anos em que Lahsa passou para as mãos dos sauditas, o emirado, que perante a pressão wahhabita não tinha outra opção senão apoiar-se em Bassorá, entrou sob proteção otomana. O vínculo seria oficializado em 1871 pela organização de Bassorá de Midhat Paxá, e o Kuwait seria contado como um dos três kazas do sanjaco de Bassorá; a posterior reivindicação territorial do Iraque assenta também neste registo.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["A perda de Meca para os wahhabitas", "2da23acd"], "d": ["O movimento wahhabita, nascido em Najd, voltou-se para o Hejaz no tempo de Suûd b. Abdülazîz; depois de Taif e Medina, Meca foi recebida também pela segunda vez — o emir de Meca, o xarife Gālib, entregou a cidade aos wahhabitas com a condição de permanecer no emirado. Os mausoléus foram derrubados e cortou-se o caminho das caravanas de peregrinos vindas de Damasco e do Cairo; o surre que o sultão enviava todos os anos aos Haremeyn foi também interrompido nestes anos — a única exceção a esta dotação ininterrupta até 1915 é o período do domínio wahhabita. Como o título de protetor dos Haremeyn era um dos fundamentos da legitimidade do sultão, esta perda foi, além de uma perda de território, um pesado golpe político; a sua recuperação levaria sete anos e só seria possível com o exército de Mehmed Ali Paxá de Cavala.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["O fim da República de Ragusa — a ocupação francesa", "f8e27bf1"], "d": ["Os franceses, que se tinham instalado na costa da Dalmácia pelo Tratado de Campo Formio (1797), tomaram Dubrovnik a 27 de maio de 1806 e puseram fim à pequena república mercantil. Assim terminou o estatuto de súbdita de três séculos e meio de Dubrovnik, que desde 1458 pagava tributo aos otomanos e preservava a sua autonomia e os seus privilégios comerciais; a cidade e a ilha de Mljet da república passam no mapa para a administração francesa direta.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["A perda de Sukhumi para os russos — a abertura da costa oriental do mar Negro", "adc96bd4"], "d": ["Na guerra otomano-russa de 1806-1812, a frota russa dirigiu-se à costa oriental do mar Negro e tomou Sohumkale, em que se apoiava o domínio otomano na Abecásia. A fortaleza era o centro da ligação com as tribos do Cáucaso e do comércio costeiro. Com a sua perda, a Rússia instalou-se pela primeira vez de forma duradoura na costa oriental do mar Negro; a influência otomana no Cáucaso ficou comprimida em torno de Anapa e Poti.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["A cedência de Parga à administração otomana", "66e0cc5d"], "d": ["Parga estava nas mãos de Veneza desde 1401 e nunca entrara na administração otomana; depois da queda de Veneza, passou sucessivamente à França e à Inglaterra. O artigo Tepedelenli Ali Paxá da TDV resume a situação assim: a cidade rendeu-se aos ingleses e só foi cedida à administração de Ali Paxá em 1819. A cedência resultou na emigração da maior parte da sua população para as ilhas Jónicas. Assim, o último do trio Preveza-Parga-Vonitsa, deixado a Veneza em Požarevac, foi também incorporado no império; Parga seria otomana durante noventa e quatro anos.", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["A passagem de Gördüs (Corinto) para os insurretos gregos", "892dcdc6"], "d": ["Durante a guerra de independência grega, Acrocorinto passou para as mãos dos insurretos e o comandante da fortaleza, Kâmil Bey, foi feito prisioneiro.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["A perda de Anabolu (Náuplia) para os insurretos", "1a67fa50"], "d": ["Anabolu, o porto da Moreia com as fortificações mais fortes, rendeu-se por fome depois de um bloqueio de mais de um ano. A fortaleza era, desde o início da insurreição, o último grande apoio do controlo otomano na península; com a sua perda, toda a Moreia passou para as mãos dos insurretos. A cidade seria pouco depois a primeira capital do novo Estado grego.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["A passagem de Lepanto para a administração grega", "c9d19d4b"], "d": ["Lepanto, na costa norte do golfo de Corinto, que permanecera nas mãos dos otomanos até à insurreição grega, perdeu-se em abril de 1829 e entrou na administração grega; o nome da vila foi mudado para o da antiguidade, Naupactos. A população muçulmana e judaica da cidade desapareceu por completo e o lugar converteu-se numa pequena vila.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["A ocupação francesa de Argel — o fim da milícia (ocak) de trezentos anos", "0be8f568"], "d": ["Tomando por pretexto o incidente do leque, nascido de uma disputa de créditos, a França manteve a costa argelina sob bloqueio durante três anos e depois desembarcou tropas em Sidi Ferruch. No fim de uma operação de três semanas, Hüseyin Dei rendeu-se e a milícia otomana de Argel, que durava desde 1516, chegou ao fim. A ocupação não ficou limitada à capital; também Tlemcen, Cherchell e Medea, no interior, se perderam no mesmo verão. A passagem de toda a costa para o controlo francês ainda demoraria vinte e quatro anos.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["A entrega de Negroponte à Grécia — juntamente com a ilha (Karystos, Oreoi)", "7b524aa4"], "d": ["Negroponte, que foi palco de intensos combates durante a guerra de independência grega mas permaneceu nas mãos dos otomanos, foi entregue aos gregos em 1831, depois de entrado em vigor o tratado de paz. A população muçulmana da cidade, que era importante base naval desde 1470, vendeu todos os seus bens a preços baixíssimos e emigrou em massa para as terras otomanas; a cidade ficou vazia durante muito tempo e o viajante alemão Fallmerayer descreveu-a em 1842 como uma cidade fantasma.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["A ocupação francesa de Orão", "a8415d66"], "d": ["Orão, que a Espanha cedera sem guerra em 1792, era o maior porto do oeste da Argélia. Seis meses depois da queda da capital, tropas francesas entraram na cidade. A operação a oeste, que daqui partiu, depressa se depararia com a resistência de quinze anos do emir Abdelkader.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["A ocupação de Annaba (Bône)", "21f37fb1"], "d": ["Annaba, porto da Argélia oriental junto à fronteira da Tunísia, foi tomada pelas forças francesas e transformada em base da marcha sobre Constantina. A cidade era ao mesmo tempo o porto africano mais próximo em frente à ilha da Sardenha.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["A cedência de Atenas ao novo Estado grego", "98af5572"], "d": ["Atenas, otomana desde 1456, mudara de mãos várias vezes durante a guerra de independência grega, e a guarnição da Acrópole passara de novo ao controlo otomano em 1827. Por ficar a norte da fronteira traçada pelo Protocolo de Londres, a cidade foi cedida ao novo reino e a guarnição evacuou a Acrópole. No ano seguinte, Atenas foi declarada capital da Grécia, em lugar de Anabolu.", "6fca14a0"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["A ocupação de Bugia", "a8927e00"], "d": ["O porto de Bugia, onde as montanhas da Cabília se abrem para o mar, era o último elo independente da linha costeira entre Argel e Annaba. Foi tomado com o apoio da artilharia naval; mas o interior montanhoso atrás dele ainda demoraria trinta anos a entrar no controlo francês. Estas ocupações ao longo da costa constituem a erosão, ano após ano, da Argélia otomana no mapa.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["A ocupação de Sétif", "2073731a"], "d": ["Depois da queda de Constantina no ano anterior, as forças francesas subiram ao planalto e, tomando a antiga cidade romana de Sétif, estabeleceram aí uma guarnição permanente. Sétif era o ponto de cruzamento das rotas de caravanas entre a costa e o Saara; a sua ocupação mostrou que a França começava a controlar já não apenas os portos, mas também a rede comercial do interior.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["A ocupação de Biskra — a perda da porta do Saara", "d895cad0"], "d": ["Biskra era, no sopé sul das montanhas do Atlas, a porta que se abre para o Saara e o centro dos oásis de tamareiras. A sua tomada, nos anos em que a resistência do emir Abdelkader começava a quebrar-se, fez o controlo francês chegar pela primeira vez à costa norte do deserto. O que se seguiria seria já uma operação do deserto avançando oásis a oásis.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["A ocupação de Touggourt — a perda de toda a Argélia", "33c056e2"], "d": ["Com a tomada de Touggourt, cidade-oásis a norte do Saara, a ocupação iniciada em 1830 ficou completa na metade norte da atual Argélia. O Estado Otomano combatia nestes anos na Guerra da Crimeia ao lado da França; embora nunca tenha renunciado oficialmente à sua pretensão jurídica sobre a Argélia, não pôde dar de facto um único passo. O único território que lhe restava no Norte de África era Trípoli de Barbaria.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["A queda de El Obeid — a passagem do Cordofão para as forças do Mahdi", "58299f62"], "d": ["O movimento iniciado por Muhammed Ahmed, que se proclamara mahdi, propagou-se depressa contra a administração egípcia no Sudão. El Obeid, centro do Cordofão, caiu depois de um cerco de quatro meses e tornou-se capital da insurreição; o tesouro e os depósitos de armas da cidade permitiram ao movimento constituir-se em exército. O Sudão era juridicamente ainda território do quediva do Egito, dependente dos otomanos, pelo que a perda cai no mapa do corpo do império.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["A queda de Cartum — a perda de todo o Sudão", "d4b98464"], "d": ["Depois de um cerco de dez meses, as forças do Mahdi entraram em Cartum, no ponto de confluência do Nilo Azul e do Nilo Branco; o governador da cidade, Gordon, foi morto, e a coluna inglesa enviada em socorro chegou dois dias tarde. A partir desta data, todo o Sudão, incluindo Sennar, Dongola e o Cordofão, permaneceu durante catorze anos sob a administração do Estado Mahdista. A região só entraria em 1899 na administração conjunta anglo-egípcia, com o vínculo otomano totalmente cortado.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["A ocupação italiana de Maçuá — a perda da costa ocidental do mar Vermelho", "c333b95b"], "d": ["O porto de Maçuá, centro da província da Abissínia, foi ocupado pela Itália, que aproveitou a confusão em que a insurreição do Mahdi cobria o Sudão; isto formou o núcleo da Eritreia italiana. Suakin, a norte, e o arquipélago de Dahlak, ao largo, perderam-se no mesmo processo. Assim terminou o domínio otomano na costa ocidental do mar Vermelho, que durava desde o tempo do sultão Selim Yavuz, e o mar tornou-se uma água estrangeira em ambas as margens.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["A ocupação italiana de Rodes", "e08662c5"], "d": ["A Itália, que na Guerra de Trípoli de Barbaria queria levar o Estado Otomano à mesa de negociações, levando a guerra ao Mediterrâneo desembarcou tropas em Rodes. A ilha foi tomada em poucos dias. Rodes, que o Legislador tomara em 1522 depois de um longo cerco e que os otomanos mantiveram trezentos e noventa anos, deixou assim de ser a maior base insular do império no Mediterrâneo Oriental; embora no Tratado de Ouchy fosse considerada ocupação provisória, nunca mais foi recuperada.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["A ocupação italiana do Dodecaneso", "200aacf2"], "d": ["Na semana seguinte à tomada de Rodes, a frota italiana ocupou também as ilhas circundantes; a este arquipélago seria dado mais tarde o nome de 'Dodecaneso'. A maior parte das ilhas ficava a poucas milhas da costa da Anatólia e controlava a passagem sudeste do Egeu. A ocupação foi considerada provisória no Tratado de Ouchy em troca da cedência de Trípoli de Barbaria, mas a Itália nunca evacuou as ilhas; seriam cedidas à Grécia em 1947.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["A ocupação de Cós", "ab246c62"], "d": ["Cós, último elo da operação do Dodecaneso, era uma ilha fértil e populosa, mesmo em frente à península de Bodrum. Com a ocupação, todas as ilhas do canto sudeste do Egeu entraram no controlo italiano e a costa sudoeste da Anatólia ficou cingida, de ponta a ponta, por uma cadeia de ilhas estrangeiras.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["A proclamação de independência de Nikarya", "c4452033"], "d": ["Na pequena ilha de Nikarya, entre Samos e Quios, o povo, no ambiente de incerteza criado pelas ocupações italianas, sublevou-se, expulsou da ilha a gendarmaria otomana e proclamou um 'Estado livre', com bandeira, selo e assembleia próprios, que durou cinco meses. Em novembro de 1912 a ilha aderiu à Grécia. Apesar da sua pequenez, este caso é uma demonstração clara de como se dissolvia a administração central no Egeu.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["A saída de Samos da administração otomana", "3a862f2b"], "d": ["Samos era, desde 1832, um principado autónomo que pagava imposto aos otomanos e era governado por um bei nomeado por Istambul. No vazio criado pela Guerra de Trípoli de Barbaria, o movimento unionista da ilha tomou a administração e a ordem do principado autónomo terminou de facto; a ilha declarou, no mesmo ano, a sua adesão à Grécia. Esta ilha, a dois quilómetros da costa da Anatólia, foi um dos primeiros territórios perdidos no Egeu.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["A queda de Ioannina — a perda do Epiro e de Parga", "d42fce18"], "d": ["Ioannina, cercada durante cinco meses na Guerra dos Balcãs, rendeu-se depois da queda das posições de Bizani; com a cidade, todo o Epiro passou à Grécia. Parga, dependente do sanjaco de Ioannina, perdeu-se também nesta data e a administração otomana de noventa e quatro anos terminou. A perda de Ioannina significava o encerramento da última janela do império que se abria para o Adriático.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["A queda de Edirne para os búlgaros", "459d2e56"], "d": ["Depois de um cerco de cinco meses e meio, Edirne, com as munições e os mantimentos esgotados, rendeu-se; Şükrü Paxá foi feito prisioneiro. A queda da cidade, otomana desde 1361 e capital durante noventa e dois anos, foi considerada o golpe mais pesado da Guerra dos Balcãs. Edirne seria retomada quatro meses depois, na Segunda Guerra dos Balcãs, aproveitando o colapso da Bulgária nas outras frentes.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["A perda de Yanbu para as forças do xarife Hussein", "e291c816"], "d": ["A insurreição que o xarife Hussein iniciara em junho propagou-se à costa do mar Vermelho; Yanbu, porto de Medina, passou para as mãos dos insurretos com o apoio da frota inglesa. O porto tornou-se a principal porta do afluxo de armas e dinheiro vindo de fora para a insurreição. Assim, a ligação marítima das forças de Fahreddin Paxá em Medina ficou cortada e a cidade ficou sozinha na ponta da via-férrea do Hejaz.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["A Terceira Batalha de Gaza — a perda de Gaza e Khan Yunis", "c142a069"], "d": ["Depois de duas tentativas falhadas, Allenby, na sua terceira ofensiva, rompeu a frente contornando Beersheba e a linha de Gaza, que se mantivera seis meses, ruiu. Gaza e Khan Yunis, a sul, foram evacuadas no mesmo dia. Esta rutura foi o início da desagregação da frente da Palestina; Jerusalém cairia cinco semanas depois.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["A ocupação de Gümülcine — a perda da Trácia Ocidental", "904d813c"], "d": ["A Trácia Ocidental, que depois de Mudros passou primeiro ao controlo das unidades da Entente, foi deixada à Grécia por decisão da conferência de San Remo e o exército grego entrou em Gümülcine. A região, retomada à Bulgária em 1913, foi o último território que o império perdeu na Rumélia. O estatuto da população turca da região seria regulado, três anos depois, em Lausana, por um regime de minorias.", "e3d0605f"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["A dissolução do Estado Ilkhanida: a morte de Ebû Said Bahadır Han", "0f187469"], "d": ["Segundo o artigo İlhanlılar da Enciclopédia do Islão da TDV, a morte de Ebû Said sem deixar herdeiro levou à fragmentação do Estado İlhanlı, que dominava o Irão havia um século; os emires, aproveitando as lutas pelo trono, fundaram dinastias locais como os Jalayiridas, os Kara Koyunlu, os Muzafáridas, os Serbedárides do Khorasan e os Eretnaoğulları. Esta dissolução dividiu a região num mosaico de beyliks que duraria um século; por fim, seria de novo unificada pelas campanhas de Timur.", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["A sujeição de grande parte do Irão por Timur", "1cee2b82"], "d": ["Segundo o artigo Timur da Enciclopédia do Islão da TDV, Timur, que desde o início da década de 1380 liquidou uma a uma as dinastias locais posteriores aos Ilcânidas, como os Serbedárides, os Kert e os Muzafáridas, submeteu de facto grande parte do Irão durante a 'campanha de três anos' de 1386-1388; o fim definitivo da dinastia dos Muzafáridas seria dado em 1393. A região foi assim de novo ligada a uma única autoridade central, depois de um século de fragmentação.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["A vitória do Aras: Kara Yûsuf derrotou o timúrida Ebû Bekir Mirza", "4b61a75a"], "d": ["Kara Yûsuf, bei dos Kara Koyunlu, que regressou do exílio depois da morte de Timur em 1405, tomou Avnik e recuperou as suas terras na Anatólia Oriental, e depois marchou contra Ebû Bekir Mirza, neto de Timur e considerado senhor do Azerbaijão e dos dois Iraques, derrotando-o na margem do Aras. Esta vitória não deu Tabriz aos Kara Koyunlu: a TDV `tebriz` escreve que a cidade estava em 1408 nas mãos de Ebû Bekir Mirza; a batalha que deu o Azerbaijão é a de Serdrûd, de 13 de abril de 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["A vitória de Serdrûd: Tabriz e o Azerbaijão passaram aos Kara Koyunlu", "1f0a429d"], "d": ["Kara Yûsuf derrotou o timúrida Ebû Bekir Mirza pela segunda vez depois do Aras, em Serdrûd, perto de Tabriz; esta vitória deu o Azerbaijão aos Kara Koyunlu. Kara Yûsuf encarregou em seguida Bistam Bey da conquista do Irâk-ı Acem;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["A epidemia de peste em Istambul e a transferência do palácio para Edirne", "70c7a163"], "d": ["Segundo o artigo Istambul da Enciclopédia do Islão da TDV, o povoamento rápido e denso da cidade preparou o terreno para a propagação, de tempos a tempos, de doenças epidémicas; durante a epidemia de peste do ano de 1466, o palácio e os dignitários do Estado retiraram-se provisoriamente para Edirne. A população da cidade sofreu perdas sérias em epidemias deste tipo.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["O fim do Estado Kara Koyunlu por Uzun Hasan", "ef68399e"], "d": ["Segundo o artigo Uzun Hasan da Enciclopédia do Islão da TDV, o soberano Ak Koyunlu Uzun Hasan derrotou e matou o soberano Kara Koyunlu Cihan Xá na região de Bingöl-Sancak a 12 de Rebîülâhir de 872 / 10 de novembro de 1467; o filho de Cihan Xá, Hasan Ali, foi derrotado em Merend em setembro de 1468 e morto diante de Hemedan em abril-maio de 1469, e o Estado Kara Koyunlu foi definitivamente extinto. As terras passaram ao domínio Ak Koyunlu; o Estado alargar-se-ia, na década seguinte, até ao interior do Irão.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["A abertura ao ensino das madraças de Sahn-ı Semân", "021f2a83"], "d": ["Segundo o artigo Sahn-ı Semân da Enciclopédia do Islão da TDV, estas oito madraças, fundadas no âmbito do Complexo de Fatih, foram concebidas como a instituição de ensino de mais alto nível da época e constituíram o topo da hierarquia científico-religiosa otomana. O cargo de professor e a graduação aqui foram considerados, nos séculos seguintes, o degrau mais prestigioso na carreira de cádi e de professor.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["A conclusão do Palácio de Topkapı (Saray-ı Cedîd)", "d2db6323"], "d": ["Segundo o artigo Palácio de Topkapı da Enciclopédia do Islão da TDV, as fontes da época divergem nas datas de início e de fim da construção; segundo a data de 883 (1478) da inscrição da Bâb-ı Hümâyun, a construção, iniciada provavelmente em 1465 por ordem do Conquistador, estava em grande parte concluída neste ano, e o palácio substituiu o centro do Estado no antigo palácio. Assim, o sultão mudou-se para a nova residência que seria, durante três séculos, o coração administrativo e cerimonial do Estado.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["A entronização de Bajazeto II em Istambul", "9b686d04"], "d": ["Segundo o artigo Bayezid II da Enciclopédia do Islão da TDV, o príncipe Bajazeto, sanjakbeyi de Amasya, ao receber a notícia da morte do pai veio depressa a Istambul e subiu ao trono; deixou para trás, com o apoio dos janízaros, a saída do irmão Cem de Konya. Durante a entronização foi distribuída aos janízaros a gratificação de entronização, que era costume. Esta mudança de trono acendeu também o pavio da luta entre os dois irmãos.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["O sultão Cem proclama-se sultão em Bursa", "b355168a"], "d": ["Segundo o artigo Cem Sultan da Enciclopédia do Islão da TDV, Cem, que chegou a Bursa por Karaman, tomou a cidade, proclamou-se sultão e mandou ler a hutbe. Este sultanato de curta duração terminou quando as forças enviadas pelo irmão mais velho, Bajazeto II, derrotaram Cem em Yenişehir. Com a derrota, Cem foi obrigado a fugir na direção do Egito.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["A execução de Gedik Ahmed Paxá", "6d75a58c"], "d": ["Segundo o artigo Gedik Ahmed Paxá da Enciclopédia do Islão da TDV, o paxá, conhecido pela campanha de Otranto e pelo grão-vizirado, foi executado em Edirne por ordem de Bajazeto II, devido à sua atitude na questão do sultão Cem e à preocupação com a sua influência. A morte de um dos mais experientes comandantes do tempo do Conquistador suscitou grande eco no palácio.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["A fundação da primeira tipografia em Istambul", "04475930"], "d": ["Segundo o artigo Tipografia da Enciclopédia do Islão da TDV, os irmãos David e Samuel ibn Nahmias, emigrantes judeus vindos da Espanha, fundaram em Istambul a primeira tipografia, que imprimia em caracteres hebraicos. Ficou registada como a primeira iniciativa tipográfica a funcionar em terras otomanas; a impressão em turco, em caracteres árabes, só seria possível muito mais tarde, no século XVIII.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["A tomada de Tabriz pelo xá Ismail: a fundação do Estado Safávida", "014d81e6"], "d": ["Segundo os artigos Safevîler e Akkoyunlular da Enciclopédia do Islão da TDV, İsmail, jovem xeique do tekke de Ardabil, com o exército que formou com os discípulos Kızılbaş da Anatólia infligiu uma pesada derrota ao sultão Ak Koyunlu Elvend na região de Nakhichevan; Elvend fugiu para Diyarbekir, İsmail entrou em Tabriz e sentou-se no trono e proclamou o xiismo dos doze imames como confissão oficial. Assim terminaram tanto o domínio Ak Koyunlu como o período dos beyliks posteriores aos Ilcânidas na região; foi fundado o Estado Safávida, que duraria três séculos.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["O sismo do 'Pequeno Juízo Final' em Istambul", "53e3b1d6"], "d": ["Segundo o artigo Istambul da Enciclopédia do Islão da TDV, o violento sismo que atingiu a cidade ficou conhecido entre o povo como o 'Pequeno Juízo Final'; houve graves danos nas muralhas, nas mesquitas e em muitos edifícios e numerosas perdas de vidas. Por ordem de Bajazeto II, foi iniciada na cidade uma vasta mobilização de reparação e de construção.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["O início da revolta de Şahkulu", "3d9a4a90"], "d": ["Segundo o artigo Şahkulu Baba Tekeli da Enciclopédia do Islão da TDV, Şahkulu, alimentado pela propaganda safávida, reuniu à sua volta uma vasta massa turcomana na região de Teke e iniciou uma grande revolta de caráter religioso e social. A revolta, uma das mais sérias crises de segurança interna da época, abalou profundamente a autoridade central do Estado.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["A morte de Bajazeto II no caminho de Dimotika", "c46e98c9"], "d": ["O antigo sultão, que depois de abdicar deixou Istambul para ir a Dimotika, a cidade onde nascera, avançava na sua liteira, que só lhe permitia percorrer 5-6 km por dia, quando se sentiu mal na aldeia de Abalar, perto de Çorlu, e faleceu a 25 de Rebîülevvel de 918 (10 de junho de 1512). A Enciclopédia do Islão da TDV considera a causa da morte muito suspeita; segundo algumas fontes nacionais e estrangeiras, insiste-se na possibilidade de ter sido envenenado. Depois de um reinado de trinta e um anos, perdeu assim a vida o oitavo sultão da linhagem de Osman Gazi.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["A execução do príncipe Ahmed por ordem de Selim Yavuz", "65abb2f2"], "d": ["Segundo o artigo Selim I da Enciclopédia do Islão da TDV, o príncipe Ahmed, favorito do pai Bajazeto II e verdadeiro rival ao trono, foi derrotado na planície de Yenişehir na luta que travou depois da subida ao trono do irmão Selim e foi apanhado e morto ao fugir do campo de batalha. Com este caso, Selim pôs em grande parte termo à rivalidade pelo trono entre os seus irmãos e sobrinhos.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["İbrahim Paxá foi nomeado grão-vizir", "9c94c1e3"], "d": ["Segundo o artigo İbrâhîm Paşa, Makbul da Enciclopédia do Islão da TDV, İbrahim Paxá, elevado de chefe dos pajens a beylerbeyi da Rumélia e, no mesmo dia, a grão-vizir, tornou-se grão-vizir a 13 de Şâban de 929 (27 de junho de 1523). Foi uma nomeação sem precedentes, em que se passou do serviço do palácio diretamente ao grão-vizirado, e mostrava a extraordinária proximidade de İbrahim Paxá junto do Legislador.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Barbarossa Hayreddin Paxá foi nomeado kapudan paxá", "a0ff6bab"], "d": ["Segundo o artigo Barbaros Hayreddin Paşa da Enciclopédia do Islão da TDV, Hayreddin Paxá, conhecido pelos seus êxitos em Argel, foi chamado a Istambul a 6 de abril de 1534 e posto à frente do kapudan paxalato (kaptan-ı deryalık) e do beylerbeylik do Arquipélago (Cezâyir-i Bahr-i Sefîd). Esta nomeação é considerada o início da reestruturação da marinha otomana e da institucionalização do poder naval no Mediterrâneo.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rüstem Paxá tornou-se grão-vizir pela primeira vez", "ddfcc014"], "d": ["Segundo o artigo Rüstem Paşa da Enciclopédia do Islão da TDV, depois da destituição de Hadım Süleyman Paşa, por uma desavença com um vizir, Rüstem Paxá foi nomeado grão-vizir a 17 de Ramazan de 951 (2 de dezembro de 1544). Rüstem Paxá, cuja proximidade do palácio aumentara graças ao casamento com Mihrimah Sultan, tornou-se com este cargo um dos estadistas mais influentes do tempo do Legislador.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebüssuûd Efendi tornou-se xeique do Islão", "11ed04f8"], "d": ["Segundo o artigo Ebüssuûd Efendi da Enciclopédia do Islão da TDV, Ebüssuûd Efendi, que durante oito anos fora cádi-askar da Rumélia, foi posto à frente do şeyhülislamlık em Şâban de 952 (outubro de 1545) e permaneceu neste cargo vinte e oito anos e onze meses. Conhecido pelas fetvas com que pôs em harmonia com o direito xariático os códigos (kanunnâme) do Legislador, Ebüssuûd Efendi teve um papel decisivo na formação das instituições jurídicas e de ensino da sua época.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Barbarossa Hayreddin Paxá morreu", "3378a0bf"], "d": ["Segundo o artigo Barbaros Hayreddin Paşa da Enciclopédia do Islão da TDV, depois de uma curta doença, faleceu em Istambul a 6 de Cemâziyelevvel de 953 (5 de julho de 1546). A morte de Barbarossa, sepultado no mausoléu contíguo à madraça que mandara construir em Beşiktaş, foi vista como o encerramento de uma época na supremacia mediterrânica que a marinha otomana estabelecera.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Começou a construção da Mesquita e do complexo de Süleymaniye", "101ec36f"], "d": ["Segundo o artigo Mesquita e Complexo de Süleymaniye da Enciclopédia do Islão da TDV, o complexo, cujos alicerces foram lançados em 1550 sob a direção do arquiteto-chefe Mimar Sinan, foi concebido como um grande complexo social composto, além da mesquita, por madraças, hospital, cozinha pública e biblioteca. A construção foi um dos maiores programas de edificação, simbolizando o poder do reinado do Legislador e o desenvolvimento urbano de Istambul.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["Começou uma nova vaga de peste em Istambul e arredores", "547d6bf6"], "d": ["Segundo o artigo Tâun da Enciclopédia do Islão da TDV, uma das epidemias do século XVI que afetaram o mundo islâmico decorreu entre 1552 e 1566 e fez-se sentir sobretudo em Istambul, na Anatólia, na Rumélia, no Egito e no Norte de África. A expansão das rotas comerciais e o aumento da mobilidade da população contam-se entre os fatores que facilitaram a propagação de doenças epidémicas no período de maior força do império.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Kara Ahmed Paxá foi nomeado grão-vizir", "a7d7748e"], "d": ["Segundo o artigo Kara Ahmed Paşa da Enciclopédia do Islão da TDV, Kara Ahmed Paxá, que servia como segundo vizir, foi elevado a grão-vizir a 27 de Şevval de 960 (5 de outubro de 1553), depois de o grão-vizir em funções ter sido de repente destituído. Esta mudança aponta para uma época em que os equilíbrios de poder dentro do palácio mudavam depressa de mãos, coincidindo com os dias da execução do príncipe Mustafa.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["O kapudan paxá Pîrî Reis foi executado", "3b2ad7a0"], "d": ["Segundo o artigo Pîrî Reis da Enciclopédia do Islão da TDV, quando chegaram ao Egito as acusações de que, ao levantar o cerco de Ormuz, saqueara em troca de suborno os bens dos muçulmanos e abandonara o seu exército no campo de batalha, o célebre navegador e cartógrafo foi executado no Cairo no fim do ano de 960 (fim de 1553). A morte de Pîrî Reis, cujos bens foram confiscados, é considerada consequência da rivalidade entre paxás na política naval de Bassorá e do oceano Índico da época.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Kara Ahmed Paxá foi executado, Rüstem Paxá voltou a ser grão-vizir", "9a85076a"], "d": ["Segundo os artigos Rüstem Paşa e Kara Ahmed Paşa da Enciclopédia do Islão da TDV, em lugar de Kara Ahmed Paxá, executado de repente durante a reunião do divã a 13 de Zilkade de 962 (29 de setembro de 1555), Rüstem Paxá foi posto no mesmo dia, pela segunda vez, no grão-vizirado, com o apoio das sultanas Hürrem e Mihrimah. Os bastidores do caso ficaram em aberto nas fontes, avaliando-se que foi consequência de intrigas dentro do palácio.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Hürrem Sultan morreu", "1ae998b5"], "d": ["Segundo o artigo Hürrem Sultan da Enciclopédia do Islão da TDV, Hürrem Sultan, que durante anos tivera grande influência dentro do palácio como haseki sultan do Legislador, faleceu em Istambul a 26 de Cemâziyelâhir de 965 (15 de abril de 1558) e foi sepultada no seu mausoléu no complexo da Mesquita de Süleymaniye. A morte de Hürrem Sultan, que consolidara a sua autoridade sobre o harém depois da morte da valide sultan Hafsa em 1534, eliminou também o efeito de equilíbrio que travava a rivalidade pelo trono entre os seus filhos Bajazeto e Selim.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Sokullu Mehmed Paxá ascendeu ao grão-vizirado", "896391a2"], "d": ["Segundo o artigo Sokullu Mehmed Paşa da Enciclopédia do Islão da TDV, Sokullu Mehmed Paxá, que ascendeu ao grão-vizirado com a morte de Semiz Ali Paxá a 30 de Zilkade de 972 (29 de junho de 1565), foi o último grão-vizir do Legislador e continuou neste cargo depois dele, nos reinados de Selim II e Murad III, tornando-se um dos grão-vizires que por mais tempo serviram na história otomana.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Selim II chegou a Istambul e foi entronizado", "0289ef97"], "d": ["Depois da morte de Solimão, o Legislador, em Szigetvár, a notícia foi mantida em segredo durante semanas por Sokullu Mehmed Paxá, para não perturbar a ordem. Segundo a Enciclopédia do Islão da TDV, Selânikî dá como data da chegada de Selim a Istambul 15 de Rebîülevvel de 974 (30 de setembro de 1566), ao passo que a maioria dos historiadores contemporâneos considera correto 9 de Rebîülevvel (24 de setembro). A morte do Legislador só foi oficialmente proclamada em Belgrado a 24-25 de outubro de 1566.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["A frota refeita por Kılıç Ali Paxá fez-se ao mar", "d0fc9f48"], "d": ["Depois da pesada derrota de Lepanto (7 de outubro de 1571), construíram-se navios nos estaleiros durante todo o inverno. Segundo a Enciclopédia do Islão da TDV, a 1 de Safer de 980 (13 de junho de 1572), a nova frota, composta por 250 galés e cerca de 300 barcas de reises voluntários, foi lançada ao mar numa demonstração de força.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Sokullu Mehmed Paxá foi vítima de atentado e morto", "6ffa8dec"], "d": ["Sokullu Mehmed Paxá, que durante catorze anos foi grão-vizir em três reinados, foi apunhalado e morto a 20 de Şâban de 987 (12 de outubro de 1579) por um dervixe que se aproximou, como se fosse entregar uma petição, do divã da tarde na sua mansão. Segundo a Enciclopédia do Islão da TDV, discute-se se o atentado poderá ter relação com a vingança do xeique hamzavi executado, Hamza Bâlî.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["O primeiro ahidnâme comercial com a Inglaterra — foram dadas capitulações aos ingleses", "59c8e3ee"], "d": ["William Harborne, representante inglês enviado a Istambul em outubro de 1578, com o apoio de Sokullu Mehmed Paxá e de Hoca Sâdeddin Efendi, obteve de Murad III um ahidnâme de 1580. Com este ahidnâme, os comerciantes ingleses ganharam o direito de usufruir, no mesmo grau, dos privilégios comerciais (capitulações) antes concedidos aos franceses e aos venezianos. Entre a rainha Isabel I e Murad III trocaram-se cartas e estabeleceu-se também uma relação oficial entre os dois Estados. Logo a seguir a estes privilégios, em 1581 foi fundada em Londres a Levant Company; os ingleses conduziram o seu comércio na região por meio desta companhia até 1825.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["O Observatório de Istambul foi demolido por hatt-ı hümâyun", "3bc0c78c"], "d": ["Sob a influência da fetva segundo a qual os observatórios trazem infortúnio aos países e da oposição dentro do palácio, o Observatório de Istambul foi demolido, com todos os seus instrumentos, por um hatt-ı hümâyun de 4 de Zilhicce de 987 (22 de janeiro de 1580). Segundo a Enciclopédia do Islão da TDV, foi o fim de curta vida da instituição fundada por Takıyyüddin er-Râsıd.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Começou a festa de circuncisão do príncipe Mehmed no Atmeydanı", "c2926d5d"], "d": ["O príncipe Mehmed, filho de Murad III, foi circuncidado com magníficas cerimónias que começaram a 6 de Cemâziyelevvel de 990 (29 de maio de 1582) e duraram cinquenta e seis a cinquenta e sete dias. Segundo a Enciclopédia do Islão da TDV, as festas organizadas no Atmeydanı foram uma das mais esplêndidas celebrações de palácio da sua época.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["A valide sultan Nurbânû faleceu", "77d0a577"], "d": ["Nurbânû Sultan, mãe de Murad III, faleceu a 22 de Zilkade de 991 (7 de dezembro de 1583). Segundo a Enciclopédia do Islão da TDV, como valide sultan manteve correspondência com as cortes de Veneza e da França, e o senado veneziano aceitara nesse mesmo ano enviar-lhe, pelos seus serviços, um presente no valor de 2000 ducados de ouro venezianos.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Rebentou o Incidente de Beylerbeyi por causa do akçe adulterado", "db2f2e61"], "d": ["Quando o Estado passou a pagar reduzindo a proporção de prata do akçe, os sipahis e os janízaros cercaram o palácio e provocaram uma sangrenta revolta que ficou na história com o nome de Incidente de Beylerbeyi. Segundo o artigo Abdülkadir Şeyhî Efendi da Enciclopédia do Islão da TDV, o xeique do Islão foi destituído por causa deste caso.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Mehmed III subiu ao trono, dezanove príncipes foram estrangulados", "2cd9a8c5"], "d": ["Mehmed III, com a morte do pai Murad III, chegou a Istambul na sexta-feira, 16 de Cemâziyelevvel de 1003 (27 de janeiro de 1595), e subiu ao trono. Segundo a Enciclopédia do Islão da TDV, na mesma noite foram estrangulados dezanove príncipes, dos quais quatro adultos (Mustafa, Bayezid, Osman e Abdullah); foi o fratricídio mais numeroso da história otomana.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safiye Sultan ganhou influência como valide sultan", "000bec21"], "d": ["Safiye Sultan, esposa de Murad III e mãe de Mehmed III, com a entronização do filho elevou-se, na qualidade de valide sultan, a uma posição determinante na política do palácio. Segundo a Enciclopédia do Islão da TDV, neste período a influência com origem no harém chegou à dimensão de intervenção direta nos assuntos do Estado.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Mehmed III partiu em campanha pessoalmente, por pressão dos janízaros", "d3c50656"], "d": ["Apesar da oposição do grão-vizir Damad İbrahim Paxá, por pressão dos janízaros Mehmed III, como primeiro sultão a pôr-se pessoalmente à frente do exército depois de Solimão, o Legislador, partiu de Istambul em campanha a 20 de junho de 1596. Segundo a Enciclopédia do Islão da TDV, isto significava a reanimação da antiga tradição da gazâ.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["A epidemia de peste iniciada na década de 1570 continuava a afetar Istambul", "eb4ca37a"], "d": ["Segundo o artigo sobre a peste da Enciclopédia do Islão da TDV, a epidemia iniciada na década de 1570 manteve o seu efeito até ao início do século XVII e atingiu a Anatólia, os Balcãs, o Egito e o Norte de África, a começar por Istambul. Os períodos epidémicos constituíam uma ameaça crónica que interrompia com frequência a vida do palácio e da cidade.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Karayazıcı Abdülhalim morreu, o movimento de revolta enfraqueceu", "876ca7a6"], "d": ["Karayazıcı Abdülhalim, que se retirara ferido depois da pesada derrota sofrida a 12 de agosto de 1601 em Sepetli, perto de Elbistan, morreu no ano de 1010 (1602). Segundo a Enciclopédia do Islão da TDV, a notícia da morte chegou a Istambul no Ramadão do ano de 1010 (fevereiro-março de 1602); as fontes indicam que é discutido se a sua morte resultou do ferimento ou foi obra dos seus próprios homens.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["O fim de facto da tradição do fratricídio", "9046c607"], "d": ["Na sua entronização, Ahmed I, ao contrário dos sultões anteriores, não mandou matar o irmão, o príncipe Mustafa, e poupou-lhe a vida; esta decisão é considerada o início da adoção de facto, no sistema sucessório otomano, do princípio do mais velho e mais apto. O artigo \"Mustafa I\" da Enciclopédia do Islão da TDV refere que Mustafa, depois desta data, levou no palácio uma vida de reclusão. A prática pôs um fim de facto aos assassinatos de entronização que se repetiam havia séculos.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Foram lançados os alicerces da Mesquita do Sultão Ahmed", "1683262f"], "d": ["Por ordem de Ahmed I, foram lançados com cerimónia, no Atmeydanı, os alicerces da mesquita que seria construída pelo arquiteto Sedefkâr Mehmed Ağa. Segundo o artigo \"Sultan Ahmed Camii ve Külliyesi\" da Enciclopédia do Islão da TDV, o edifício foi também alvo das críticas da época por ser a primeira grande mesquita imperial construída diretamente com fundos do tesouro, sem uma vitória de conquista. O complexo foi concebido de modo a incluir, juntamente com a mesquita, uma madraça, uma cozinha pública e um mausoléu.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["O assassinato de Osman, o Jovem, pelos janízaros (Hâile-i Osmâniye)", "324f6582"], "d": ["Os janízaros e os sipahis, que se sublevaram com os rumores de que ele planeava sair de Istambul a pretexto da peregrinação e dissolver o corpo dos janízaros, depuseram Osman II e mandaram estrangulá-lo nas masmorras de Yedikule. Segundo o artigo \"Osman II\" da Enciclopédia do Islão da TDV, este caso é, na história otomana, o primeiro em que um sultão foi abertamente morto por uma revolta militar e criou uma rutura profunda na relação entre dinastia e exército. As suas últimas horas decorreram assim: como a tentativa de se refugiar na mansão do aga dos janízaros Ali Ağa não deu resultado, o sultão foi, nas palavras da TDV, 'de forma lamentável, de cabeça descoberta, em desalinho', montado num cavalo e conduzido, sob graves insultos, primeiro à Mesquita Orta, onde estava Mustafa I, e à tarde do mesmo dia a Yedikule; segundo alguns historiadores, para provar a sua morte cortaram-lhe a orelha e o nariz e mostraram-nos à mãe de Mustafa I. Depois do caso, Mustafa I foi entronizado pela segunda vez. O caso, conhecido por 'Hâile-i Osmâniye' (a tragédia de Osman), perturbou de modo duradouro o equilíbrio palácio-corpo e iniciou as polémicas sobre legitimidade que durariam um século.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["A segunda entronização de Mustafa I", "34a0b29a"], "d": ["Depois do assassinato de Osman, o Jovem, pelos janízaros, como não havia outro membro masculino adulto na dinastia, Mustafa I foi entronizado pela segunda vez. Segundo o artigo \"Mustafa I\" da Enciclopédia do Islão da TDV, também este segundo sultanato decorreu, tal como o anterior, sem que ele pudesse de facto conduzir os assuntos do Estado, e a governação ficou nas mãos dos vizires e da valide sultan. Este período, que durou catorze meses, terminou em 1623 com a entronização de Murad IV.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["O Incêndio de Cibali", "3e42fb08"], "d": ["O incêndio que rebentou em Cibali e, com o efeito do vento, se propagou depressa reduziu a cinzas grande parte de Istambul; segundo o artigo \"İstanbul\" da Enciclopédia do Islão da TDV, as fontes da época referem que arderam milhares de casas. O facto de o incêndio ter sido associado ao tecido de casas de madeira e ao fumo do tabaco foi a justificação direta da dura proibição do tabaco e dos cafés que Murad IV proclamaria pouco depois. A catástrofe foi apenas um dos grandes incêndios repetidos da Istambul da época.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["A proibição do tabaco e dos cafés por Murad IV", "5dd71297"], "d": ["Depois do Incêndio de Cibali, por preocupação com o fogo e a ordem pública, Murad IV proibiu o fumo do tabaco e os cafés; aos infratores aplicaram-se penas graves, incluindo a pena de morte. Segundo o artigo \"Murad IV\" da Enciclopédia do Islão da TDV, o sultão seguiu uma política de disciplina interna tão rigorosa que percorria pessoalmente, disfarçado, as ruas da cidade para fiscalizar a proibição. Estas duras medidas são consideradas parte do esforço de Murad IV para restabelecer a autoridade central.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["A epidemia de peste em Istambul", "f33f58c5"], "d": ["No tempo de Murad IV, Istambul foi abalada por uma grave epidemia de peste que atingiu uma parte importante da população; o comércio urbano e a vida quotidiana foram perturbados durante meses. O artigo \"İstanbul\" da Enciclopédia do Islão da TDV regista que as epidemias repetidas no século XVII afetaram seriamente o equilíbrio demográfico da cidade. Durante a epidemia, o palácio e a elite mudaram-se por algum tempo para jardins e quiosques fora da cidade.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["O voo com asas de Hezarfen Ahmed Çelebi (tradição)", "df474c04"], "d": ["Segundo a tradição transmitida por Evliya Çelebi, Hezarfen Ahmed Çelebi conseguiu, com asas feitas por ele próprio, saltar da Torre de Gálata e planar até Üsküdar; embora a sua certeza histórica seja discutida, tornou-se símbolo da imaginação técnica. O sultão, que a princípio recompensara Hezarfen, desterrou-o depois para Argel, devido ao eco que o caso causou.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["A ascensão da influência de Cinci Hoca Hüseyin Efendi no palácio", "41d21572"], "d": ["Hüseyin Efendi, curandeiro chamado ao palácio para tratar as perturbações psíquicas do sultão Ibrahim, ganhou em pouco tempo a confiança do sultão e subiu até cádi-askar da Anatólia. Segundo o artigo \"Hüseyin Efendi, Cinci Hoca\" da Enciclopédia do Islão da TDV, usou esta influência para acumular fortuna e interferir nos acontecimentos políticos da época. Depois da morte de Ibrahim foi destituído de todos os cargos e executado em 1648.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["A execução de Kemankeş Mustafa Paxá", "0ecc8030"], "d": ["Kemankeş Mustafa Paxá, grão-vizir desde o tempo de Murad IV e que, com as suas reformas financeiras, dera ao tesouro um excedente importante, foi estrangulado e executado depois de os seus rivais dentro do palácio terem influenciado Ibrahim e de ter sido acusado de provocar uma revolta de janízaros. Segundo o artigo \"Kemankeş Mustafa Paşa\" da Enciclopédia do Islão da TDV, a execução ocorreu a 21 de Zilkade de 1053 / 31 de janeiro de 1644: Kemankeş Kara Mustafa Paxá foi estrangulado no Bazar de Hocapaşa pelo carrasco Kara Ali e sepultado no seu próprio mausoléu em Çarşıkapı. A sua morte é recordada como exemplo impressionante da instabilidade do cargo de grão-vizir na época e pôs fim a um breve período de reforma rigorosa.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["A decisão da Campanha de Creta no divã e a partida da frota", "9076827e"], "d": ["A abertura de uma grande campanha contra a ilha de Creta, pertencente a Veneza, foi decidida no Divan-ı Hümayun, e a frota otomana, sob o comando do kapudan paxá, partiu de Istambul para Creta. Segundo o artigo \"Girit\" da Enciclopédia do Islão da TDV, esta decisão constituiu o início político de um longo período de cerco e guerra que duraria cerca de vinte e cinco anos. A abertura da campanha, como maior iniciativa de política externa do reinado de Ibrahim, suscitara amplas discussões entre os dignitários do Estado.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["A entronização de Mehmed IV aos sete anos", "a197a3bc"], "d": ["Logo a seguir à deposição de Ibrahim, o seu filho Mehmed, de apenas sete anos, foi elevado ao trono e tornou-se sultão com o título de Mehmed IV. Segundo o artigo \"Mehmed IV\" da Enciclopédia do Islão da TDV, a subida ao trono em tão tenra idade acirrou a luta de influência dentro do palácio entre a avó Kösem Sultan e a mãe Turhan Sultan. Esta luta pelo poder resultaria, em 1651, no assassinato de Kösem Sultan.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["A reforma do orçamento equilibrado de Tarhuncu Ahmed Paxá", "376fc7f2"], "d": ["O grão-vizir Tarhuncu Ahmed Paxá, para superar a crise financeira causada pelos longos anos de guerra, aplicou um duro programa de poupança que abrangia também as despesas do palácio e preparou o primeiro orçamento equilibrado conhecido da história otomana (o projeto de Tarhuncu, tarhuncu lâyihası). Segundo o artigo \"Tarhuncu Ahmed Paşa\" da Enciclopédia do Islão da TDV, esta reforma deu ao tesouro um excedente importante, mas criou um amplo descontentamento nos círculos do palácio e na alta burocracia. Este descontentamento resultaria, um ano depois, na sua execução.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["O Incidente do Plátano (Vak'a-i Vakvakiye)", "4c6ed90f"], "d": ["Segundo o artigo Çınar Vak'ası da Enciclopédia do Islão da TDV, os janízaros e sipahis que regressaram sem soldo da campanha de Creta sublevaram-se em Istambul e exigiram a execução de dignitários do Estado que acusavam de corrupção. A proposta de confisco e exílio do grão-vizir Zurnazen Mustafa Paxá não foi aceite; primeiro três funcionários e depois cerca de trinta dignitários foram executados e os seus cadáveres foram pendurados nos plátanos da Praça do Sultão Ahmed. Por isso, o caso ficou conhecido como Incidente do Plátano.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["A nomeação de Köprülü Mehmed Paxá como grão-vizir, com aceitação condicionada", "3a6b7f8f"], "d": ["Segundo o artigo Köprülü Mehmed Paşa da Enciclopédia do Islão da TDV, Köprülü Mehmed Paxá, de perto de oitenta anos, só recebeu o selo depois de fazer aceitar à valide Turhan Sultan e a Mehmed IV condições pesadas — que não se interferisse nas suas nomeações e que não se acreditasse no que se dissesse contra ele. Assumiu funções a 26 de Zilkade de 1066, em lugar de Boynueğri Mehmed Paxá, e empenhou-se em restabelecer com dureza a disciplina do Estado.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["A repressão do movimento dos Kadızadelis por Köprülü Mehmed Paxá", "5ec3ce84"], "d": ["Segundo o artigo Kadızâdeliler da Enciclopédia do Islão da TDV, logo que assumiu funções, Köprülü Mehmed Paxá tratou do conflito religioso entre o círculo de Kadızâde Mehmed Efendi e os adeptos das confrarias. Depois de consultar os ulemás, emitiu um firmão de execução para os dirigentes do movimento Üstüvânî Mehmed Efendi, Türk Ahmed e Divâne Mustafa, mas esta pena foi comutada em exílio e os três foram enviados para Chipre; assim terminou a segunda fase do movimento.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["O grande incêndio de Istambul: a destruição de Ağakapısı", "b9253b66"], "d": ["Segundo o artigo Ağakapısı da Enciclopédia do Islão da TDV, no grande incêndio que rebentou em julho de 1660, no tempo de Mehmed IV, a Ağakapısı, quartel-general oficial do aga dos janízaros, ardeu por completo e foi em seguida reconstruída. Este incêndio foi um dos grandes incêndios urbanos que atingiram repetidamente a Istambul da época.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["A nomeação de Köprülüzâde Fâzıl Ahmed Paxá como grão-vizir", "c1999b5c"], "d": ["Segundo o artigo Köprülüzâde Fâzıl Ahmed Paşa da Enciclopédia do Islão da TDV, com a morte do pai, Köprülü Mehmed Paxá, foi posto no grão-vizirado a 8 de Rebîülevvel de 1072 (1 de novembro de 1661). Ao contrário do pai, conhecido como de temperamento suave, devoto e protetor de sábios e artistas, Fâzıl Ahmed Paxá, durante o seu grão-vizirado de mais de quinze anos, mandou fundar bibliotecas e instituições de caridade em Istambul e nos territórios conquistados.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["A nomeação de Vânî Mehmed Efendi como pregador da Yeni Cami e preceptor do sultão", "7ea6aaae"], "d": ["Segundo o artigo Mehmed Efendi, Vânî da Enciclopédia do Islão da TDV, Vânî Mehmed Efendi, chamado a Istambul com a ascensão de Köprülüzâde Fâzıl Ahmed Paxá e apresentado a Mehmed IV, ganhou em pouco tempo o estreito interesse do sultão. Em 1665 foi posto como pregador da Yeni Cami e preceptor do sultão e tornou-se um dos homens de religião mais influentes do palácio.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["A nomeação de Merzifonlu Kara Mustafa Paxá como grão-vizir", "3d1e836c"], "d": ["Segundo o artigo Merzifonlu Kara Mustafa Paşa da Enciclopédia do Islão da TDV, com a morte de Fâzıl Ahmed Paxá foi posto no grão-vizirado a 28 de Şâban de 1087 (5 de novembro de 1676). Genro e discípulo da família Köprülü, com longa experiência na governação do Estado, Merzifonlu tornou-se um dos grão-vizires mais fortes e influentes de Mehmed IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["A morte de Vânî Mehmed Efendi no exílio", "cda714aa"], "d": ["Segundo o artigo Mehmed Efendi, Vânî da Enciclopédia do Islão da TDV, Vânî Mehmed Efendi, considerado um dos principais nomes que fizeram o sultão aceitar a campanha de Viena, foi, depois de a campanha terminar em desastre, caído em desgraça por pressão da opinião pública e exilado para a vila de Kestel, em Bursa. Faleceu aí a 14 de Zilkade de 1096 (12 de outubro de 1685) e foi sepultado à entrada da mesquita que mandara construir.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["A nomeação de Köprülüzâde Fâzıl Mustafa Paxá como grão-vizir e as suas reformas financeiras", "b048570e"], "d": ["Segundo o artigo Köprülüzâde Fâzıl Mustafa Paşa da Enciclopédia do Islão da TDV, Fâzıl Mustafa Paxá, posto no grão-vizirado a 11 de Muharrem de 1101 (25 de outubro de 1689), reorganizou o processo de cobrança da cizye segundo princípios xariáticos, combateu a inflação do mangır e reforçou o tesouro transferindo recursos das instituições do palácio. Além disso, reforçou a administração provincial com funcionários de confiança e mandou criar conselhos locais semelhantes ao divã central.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["A entrada em vigor do sistema malikâne", "316b8426"], "d": ["Segundo o artigo Mâlikâne da Enciclopédia do Islão da TDV, no último quartel do século XVII o aumento das despesas de guerra e a diminuição das receitas por perdas de território lançaram o tesouro numa grave crise financeira. No sistema malikâne, que entrou em vigor no ano de 1106 (1695), concedeu-se aos arrendatários o direito vitalício a um imposto fixo, introduzindo-se um incentivo à preservação da produção em vez da exploração a curto prazo.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["A entronização de Mustafa II", "b53656c7"], "d": ["Segundo o artigo Mustafa II da Enciclopédia do Islão da TDV, Mustafa II, que subiu ao trono aos trinta e um anos, proclamou o seu sultanato sem esperar a aprovação do grão-vizir e do xeique do Islão (şeyhülislam); a cerimónia de cingir a espada realizou-se alguns dias depois na Eski Cami. O sultão, que subiu ao trono num período em que prosseguiam as guerras em várias frentes depois do desastre de Viena, foi o último sultão otomano a sair pessoalmente em campanha.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["A nomeação de Feyzullah Efendi, pela segunda vez, como xeique do Islão (şeyhülislam)", "1cf14cff"], "d": ["Segundo o artigo Feyzullah Efendi, Seyyid da Enciclopédia do Islão da TDV, depois da entronização de Mustafa II foi posto pela segunda vez no şeyhülislamlık a 11 de Şevval de 1106 (25 de maio de 1695). A sua influência sobre o sultão foi crescendo durante este período no cargo, que durou mais de oito anos.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["A colocação dos filhos de Feyzullah Efendi em altos cargos e a reação acumulada", "a6398280"], "d": ["Segundo o artigo Feyzullah Efendi, Seyyid da Enciclopédia do Islão da TDV, o xeique do Islão (şeyhülislam) obteve de Mustafa II um firmão sem precedentes segundo o qual o seu filho Fethullah Efendi seria xeique do Islão depois dele e colocou os seus parentes, em tenra idade, em altos cargos. Estas práticas criaram um amplo descontentamento entre a classe científico-religiosa, o exército e o povo de Istambul; juntando-se aos rumores de que a capital seria transferida para Edirne, prepararam o terreno ao Incidente de Edirne de 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["O início do Incidente de Edirne", "5a106458"], "d": ["Segundo o artigo \"Edirne Vak'ası\" da TDV, o movimento, iniciado com a revolta de soldados que não recebiam os soldos, converteu-se em pouco tempo numa vasta insurreição em que participaram janízaros, estudantes de madraça, artesãos e povo. O alvo principal da revolta era o xeique do Islão (şeyhülislam) Feyzullah Efendi, de quem se dizia que interferia excessivamente nos assuntos do Estado. Uma multidão de cerca de 60.000 pessoas marchou de Istambul para Edirne.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["O grão-vizirado de Nevşehirli Damad İbrahim Paxá", "8d627a6f"], "d": ["Segundo o artigo \"Damad İbrâhim Paşa, Nevşehirli\" da TDV, durante as negociações de paz em curso com a Áustria, foi posto no cargo de grão-vizir a 8 de Cemâziyelâhir de 1130 (9 de maio de 1718) e, logo que nomeado, orientou-se para as negociações que poriam fim à guerra; dois meses depois foi assinado o Tratado de Požarevac (21 de julho de 1718). Nas palavras da TDV, 'queria ocupar-se de questões sociais e financeiras, aspirava a um período de paz que fizesse esquecer as guerras que, havia muitos anos, terminavam em derrota'. Fez reformas nas finanças, reduziu os soldos dos soldados e formou um excedente importante no tesouro do Estado. O seu grão-vizirado, que duraria doze anos, constituiu o quadro político do período que leva o seu nome (Período das Tulipas, Lâle Devri).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["A fundação do Corpo dos Bombeiros", "f58b0d97"], "d": ["Segundo o artigo \"Tulumbacı\" da TDV, tendo Gerçek Dâvud, regressado da campanha da Moreia de 1715, mostrado êxito com a bomba nos incêndios de Istambul, o grão-vizir Nevşehirli Damad İbrahim Paxá encarregou-o de fundar um corpo oficial de bombeiros. O corpo, fundado no Quartel dos Acemi Oğlanları com seis oficiais e cinquenta soldados, chegou a 150 em 1724 e a 461 em 1755. Dâvud permaneceu à frente do corpo até à sua morte, em 1733.", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["A receção de Mehmed Efendi por Luís XV", "0ff5b174"], "d": ["Segundo o artigo \"Yirmisekiz Çelebi Mehmed Efendi\" da TDV, o embaixador foi recebido oficialmente no Palácio das Tulherias pelo rei de França Luís XV e apresentou os presentes e a carta de Ahmed III. Durante a visita, visitou os palácios de Versalhes, Trianon e Marly, hospitais, observatórios e manufaturas; registou o que viu em desenhos.", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["O regresso de Mehmed Efendi a Istambul", "a09a8bba"], "d": ["Segundo o artigo \"Yirmisekiz Çelebi Mehmed Efendi\" da TDV, as observações do embaixador, de regresso da embaixada de um ano em Paris, influenciaram o gosto arquitetónico do Período das Tulipas. O facto de o filho ter trabalhado depois com İbrahim Müteferrika preparou o terreno à fundação da primeira tipografia turca, a herança mais duradoura da embaixada.", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["A construção do Palácio de Sâdâbâd", "aec9c65e"], "d": ["Segundo o artigo \"Sâdâbâd\" da TDV, na margem do ribeiro de Kağıthane foi construído um vasto complexo de recreio e de passeio, formado por palácios, canais, fontes e quiosques inspirados na arquitetura palaciana francesa. Sâdâbâd, que se tornou o lugar de diversão mais apreciado da época, ficou imortalizado nos poemas do poeta Nedîm. O complexo foi em grande parte destruído durante a Revolta de Patrona Halil de 1730.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["A tomada de Derbent pelas forças russas: a campanha do Cáspio de Pedro I", "c2b269f9"], "d": ["Quando o Estado Safávida foi arrastado para a confusão interna pela invasão afegã, o czar russo Pedro I partiu em campanha com o fim de tomar as terras persas da costa do Cáspio; a cidade costeira de Derbent rendeu-se às forças russas sem resistência digna de nota. Segundo o artigo Derbend da Enciclopédia do Islão da TDV, esta ocupação foi o início de um domínio russo provisório que duraria treze anos; o Estado Otomano, aproveitando a mesma confusão, voltou-se para a parte ocidental do Cáucaso. O exército desembarcara de Astracã, por via marítima, no golfo de Agrakhan e daí marchara por terra ao longo da costa, por Tarku; o şamhal de Tarku, depois de acolher Pedro, passou à sujeição russa.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["A abolição do şamhalado de Tarku: administração russa direta", "b0f029c6"], "d": ["O şamhal de Tarku Adil-Girey, que em 1722 acolhera Pedro e passara à sujeição russa, revoltou-se em 1725; Yeropkin destruiu Tarku no outono de 1725, o şamhal foi preso e exilado em meados de maio de 1726 e o şamhalado foi abolido. Tarku e os arredores permaneceram sob administração russa direta até ao Tratado de Gence de 1735.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["A licença a İbrahim Müteferrika para fundar uma tipografia", "0659dd0a"], "d": ["Segundo o artigo \"İbrâhim Müteferrika\" da TDV, por firmão de Ahmed III e por fetva do xeique do Islão (şeyhülislam) Yenişehirli Abdullah Efendi, foi permitida a fundação da primeira tipografia turca. A tipografia entrou em funcionamento no bairro de Yavuzselim, em Istambul. Müteferrika imprimiu, até à sua morte em 1747, dezassete obras em vinte e três volumes.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["A conclusão do primeiro livro impresso, o Dicionário de Vankulu", "684700e8"], "d": ["Segundo o artigo \"İbrâhim Müteferrika\" da TDV, a tradução turca do Sıhâhu'l-Cevherî (Vankulu Lügati), primeira obra da tipografia, ficou concluída no início de 1729. Foi o primeiro livro impresso em caracteres árabes em terras otomanas e é considerado o início da história da tipografia turca.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["A execução de Nevşehirli Damad İbrahim Paxá", "50c64341"], "d": ["Segundo o artigo \"Damad İbrâhim Paşa, Nevşehirli\" da TDV, o cadáver do grão-vizir, morto no palácio durante a Revolta de Patrona Halil, foi arrastado pelas ruas de Istambul e abandonado junto à Fonte de Ahmed III, na Praça do Sultão Ahmed. O grão-vizirado de doze anos e o Período das Tulipas terminaram assim de forma sangrenta.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["A abdicação de Ahmed III, a entronização de Mahmud I", "a43f5d40"], "d": ["Segundo o artigo \"Mahmud I\" da TDV, perante a pressão dos insurretos, Ahmed III abdicou depois de obter garantias para si e para os filhos e foi ele próprio a elevar ao trono o sobrinho, o príncipe Mahmud. Mahmud I, que se sentou no trono com o conselho do tio \"toma nas tuas mãos os assuntos do Estado, não confies em ninguém\", procurou, como primeira medida, quebrar a influência do grupo de insurretos que o pusera no trono.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["A reforma do corpo de artilharia por Humbaracı Ahmed Paxá", "ea3a7c64"], "d": ["Segundo o artigo \"Humbaracı\" da TDV, o oficial de origem francesa Ahmed Paxá, convertido ao Islão, empenhou-se, no tempo do grão-vizir Hekimoğlu Ali Paxá, na reforma à europeia da organização assalariada dos bombardeiros. Criou uma nova estrutura de 601 pessoas, dependente diretamente do grão-vizir, com 300 assalariados e 301 timarlis. Mandou produzir, com a tecnologia da época, 100 morteiros e 50.000 balas.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["A fundação da Hendesehâne (o primeiro exemplo de escola de engenharia)", "a77ed1f3"], "d": ["Segundo o artigo \"Mahmud I\" da TDV, Humbaracı Ahmed Paxá, ao fundar em Üsküdar a Hendesehâne, também chamada Humbarahâne, deu uma instrução militar assente na matemática e na geometria aos alunos escolhidos entre os servidores do palácio e os bostancıs. Esta instituição é considerada o primeiro exemplo das escolas de engenharia que se desenvolveriam mais tarde.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["O Tratado de Gence: a devolução de Derbent e Baku ao Irão", "ff19d531"], "d": ["A Rússia, que buscava aliança com o Irão contra a ameaça otomana, devolveu, pelo Tratado de Gence, ao Irão comandado por Nadir Han (que ainda não tomara o título de xá) as cidades da costa do Cáspio que detinha havia treze anos. Segundo o artigo Derbend da Enciclopédia do Islão da TDV, esta retirada foi consequência de a Rússia não querer lutar em duas frentes ao mesmo tempo no sul (otomana e persa) e consolidou o prestígio militar de Nadir, que abriu o caminho à sua subida ao trono poucos anos depois. Tarki (Tarku), sob administração russa, voltou também com esta retirada para o lado persa (no mapa usa-se o dia de Gence).", "94b6c31b"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["A subida de Nadir Xá ao trono na planície de Mugan: o fim de facto da dinastia safávida", "4f640979"], "d": ["Segundo o artigo Nadir Şah da Enciclopédia do Islão da TDV, o kurultai de cerca de vinte mil pessoas reunido na planície de Mugan pediu com insistência que ele se pusesse à frente do Irão; Nadir aceitou esta proposta com a condição de que se abandonasse a concepção xiita extremada que causara as guerras entre safávidas e otomanos e se adotasse a escola moderada jafarita, e subiu ao trono com o título de Nâdir Şah a 24 de Şevval de 1148 (8 de março de 1736). Isto significava o fim de facto da dinastia safávida de dois séculos e a fundação da dinastia dos Afsharidas.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["O início da epidemia de peste em Istambul", "9fa82b56"], "d": ["Segundo o artigo \"Tâun\" da TDV, a epidemia de peste que atuou na geografia islâmica entre 1739 e 1743 atingiu também Istambul nesta época. O artigo indica que as epidemias do século XVIII decorreram de forma relativamente mais leve do que as dos séculos anteriores. Entre os períodos epidémicos contam-se também os anos de 1713, 1719, 1728-1729 e 1759-1765.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["O incêndio de Hocapaşa", "321c7d0d"], "d": ["Segundo o artigo \"Fatma Sultan Camii\" da TDV, o incêndio de Hocapaşa, que rebentou de noite, devastou a Sublime Porta e os arredores; supõe-se que a Mesquita de Fatma Sultan, na região, sofreu também danos neste incêndio. Esta catástrofe, um dos grandes incêndios que atingiram Istambul no tempo de Osman III, causou graves destruições no centro comercial e administrativo da cidade.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["O grão-vizirado de Koca Ragıp Mehmed Paxá", "a1846910"], "d": ["Ragıp Paxá, conhecido como poeta e diplomata, foi posto por Osman III no cargo de grão-vizir (em outubro de 1757, com a morte de Osman III, continuou em funções e recebeu o novo selo de Mustafa III). Enquanto prosseguiam as Guerras dos Sete Anos, seguiu uma política externa equilibrada que manteve o Estado Otomano fora dos conflitos na Europa. Durante o seu grão-vizirado, que duraria seis anos, deu também importância a atividades culturais, como a fundação de bibliotecas.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["A morte de Ragıp Paxá", "6bc19323"], "d": ["Ragıp Paxá faleceu depois de um grão-vizirado de seis anos. Com a sua morte terminou o grão-vizirado mais duradouro e equilibrado do tempo de Mustafa III.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["O grande sismo de Istambul e a ruína da Mesquita de Fatih", "2475b4dc"], "d": ["Segundo o artigo \"Fâtih Camii ve Külliyesi\" da TDV, no grande sismo de 1766 a cúpula principal da mesquita ruiu por completo e as paredes sofreram danos que não podiam ser reparados. A reconstrução, iniciada em 1767 por ordem de Mustafa III sob a direção dos arquitetos Sarım İbrahim Efendi e İzzet Mehmed Bey, foi concluída em 1771, com um novo projeto diferente do antigo plano.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["A tentativa de escola de artilharia de curta vida sob a liderança do barão de Tott", "4192260c"], "d": ["Segundo o artigo \"Mühendishâne-i Bahrî-i Hümâyun\" da TDV, os fracassos da guerra otomano-russa de 1768 puseram em evidência a necessidade de instrução militar técnica; a escola de artilharia de curta vida, aberta com a contribuição do oficial francês barão de Tott, entrou em funcionamento em outubro de 1772, mas foi ineficaz. Esta tentativa é considerada precursora da Mühendishâne-i Bahrî-i Hümâyun, que seria fundada em 1775.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Selim III subiu ao trono", "00d046d9"], "d": ["Com a morte de Abdülhamid I, o sobrinho Selim III passou ao trono. Segundo o artigo Selim III da Enciclopédia do Islão da TDV, o novo sultão, que desde a sua condição de príncipe se interessava pela reforma dos exércitos europeus, pouco depois da entronização começou a mandar preparar um programa de renovação radical. Este programa seria conhecido, em poucos anos, pelo nome de Nizâm-ı Cedîd.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Começou a preparação do programa de reformas do Nizâm-ı Cedîd", "eff78a68"], "d": ["Selim III mandou preparar um programa de renovação abrangente, segundo os projetos que pedira aos dignitários do Estado e a peritos estrangeiros. Segundo o artigo Nizâm-ı Cedîd da Enciclopédia do Islão da TDV, este programa não se limitou a criar um novo exército; converteu-se num vasto movimento de reforma que abrangia também as finanças, a administração provincial e a diplomacia. O programa encontraria, nos quinze anos seguintes, tanto apoiantes como opositores.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["Foram criadas embaixadas permanentes nas capitais europeias", "2e9dc8a1"], "d": ["Selim III enviou pela primeira vez na história do Estado Otomano embaixadores permanentes, que desempenhariam funções contínuas, aos grandes centros europeus. Segundo o artigo Elçi da Enciclopédia do Islão da TDV, este passo dotou de uma organização duradoura a diplomacia otomana, que até então se conduzira apenas com missões temporárias e isoladas. A principal tarefa das novas embaixadas era comunicar regularmente a Istambul os desenvolvimentos políticos e militares da Europa.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["Foi criado o tesouro İrad-ı Cedîd", "ae5c8ce2"], "d": ["Foi criado um tesouro separado para cobrir as despesas do exército do Nizâm-ı Cedîd e do programa de reformas. Segundo o artigo Esham da Enciclopédia do Islão da TDV, entre as receitas do novo tesouro contavam-se a exploração direta, pelo Estado, de algumas mukataas e o controlo das vendas de esham. Esta disposição foi uma tentativa de criar uma nova fonte fora do sistema financeiro tradicional.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Começou a revolta de Kabakçı Mustafa", "b98eee17"], "d": ["O descontentamento acumulado contra o Nizâm-ı Cedîd rebentou com a sublevação dos soldados yamak sob a liderança de Kabakçı Mustafa. Segundo o artigo Kabakçı İsyanı da Enciclopédia do Islão da TDV, os rebeldes tomaram em pouco tempo o controlo de Istambul e exigiram as cabeças dos dignitários favoráveis ao Nizâm-ı Cedîd. A sublevação resultou, em poucos dias, na deposição de Selim III.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Selim III foi deposto", "ff2c30ec"], "d": ["Sob a pressão da revolta de Kabakçı Mustafa, Selim III foi deposto por uma fetva obtida do xeique do Islão (şeyhülislam). Segundo o artigo Selim III da Enciclopédia do Islão da TDV, esta decisão foi o momento em que terminou de facto o período de reformas de dezoito anos; o exército do Nizâm-ı Cedîd foi também dissolvido em pouco tempo. Selim passou a ser mantido sob vigilância no Palácio de Topkapı.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Mustafa IV subiu ao trono", "8f1ac86c"], "d": ["Logo a seguir à deposição de Selim III, o sobrinho Mustafa IV foi proclamado sultão. Segundo o artigo Mustafa IV da Enciclopédia do Islão da TDV, o novo sultão iniciou o sultanato sob a influência dos meios contrários ao Nizâm-ı Cedîd que tinham apoiado a revolta. Este período, de curta duração, foi uma fase de instabilidade em que a autoridade central se enfraqueceu por completo.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Alemdar Mustafa Paxá entrou em Istambul com o seu exército", "0cad3dea"], "d": ["O âyan de Ruse, Alemdar Mustafa Paxá, chegou diante de Istambul com o seu exército com o fim de repor Selim III no trono. Segundo o artigo Alemdar Mustafa Paşa da Enciclopédia do Islão da TDV, a sua entrada na cidade foi recebida pessoalmente por Mustafa IV; mas, em poucos dias, o equilíbrio de poder dentro do palácio mudaria por completo. Esta entrada iniciou a cadeia de acontecimentos que resultou tanto na morte de Selim como numa nova entronização.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["Selim III foi morto", "e452f5f6"], "d": ["No dia em que Alemdar Mustafa Paxá tomou a Sublime Porta, Selim III foi morto no palácio por ordem de Mustafa IV. Segundo o artigo Selim III da Enciclopédia do Islão da TDV, foi uma decisão tomada para evitar a tentativa de repor no trono um sultão deposto. A morte de Selim resultou, no mesmo dia, na entronização de Mahmud.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["Mahmud II subiu ao trono", "661c1974"], "d": ["Depois do assassinato de Selim III, Mahmud, único membro masculino que restava da dinastia, subiu ao trono com o apoio de Alemdar Mustafa Paxá. Segundo o artigo Mahmud II da Enciclopédia do Islão da TDV, o novo sultão passou os primeiros meses do seu sultanato sob a tutela de Alemdar, que o pusera no trono, e no esforço de restabelecer o equilíbrio entre os âyans e o centro. Este período foi o início do processo de reforma radical dos vinte anos seguintes.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["Foi criado o exército Sekbân-ı Cedîd", "6f9eb5e4"], "d": ["Alemdar Mustafa Paxá mandou criar, em lugar do dissolvido Nizâm-ı Cedîd, um novo exército equipado à europeia. Segundo o artigo Sekbân-ı Cedîd da Enciclopédia do Islão da TDV, esta força, formada por três regimentos, foi vista pelos janízaros como uma ameaça direta e foi eliminada, apenas alguns meses após a sua criação, numa revolta de janízaros.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["A queda de Ibraila — a primeira grande brecha na linha do Danúbio", "ee519321"], "d": ["Na guerra com a Rússia iniciada em 1806, a fortaleza de Ibraila, na margem norte do Danúbio, foi cercada e bombardeada pelas forças russas comandadas pelo conde Kamenski. No interior havia 4100 infantes, 1100 cavaleiros e 260 canhões; a fortaleza rendeu-se ao general Essen por falta de víveres. A extremidade norte da linha de defesa do Danúbio ficou assim aberta.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["A rendição de Ruse — a margem sul do Danúbio também se perde", "084062e8"], "d": ["Ruse resistiu ao longo e sangrento cerco do exército russo comandado pelo conde Kamenski; rendeu-se com a condição de que a guarnição e a população civil abandonassem a cidade em segurança. A queda da mais forte cidade-fortaleza da margem sul do Danúbio inverteu o curso da guerra a favor da Rússia.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["Foi criado o Corpo Eşkinci", "67c56759"], "d": ["Mahmud II mandou criar uma nova unidade, a receber instrução à europeia, com soldados escolhidos de entre o corpo dos janízaros. Segundo o artigo Eşkinci Ocağı da Enciclopédia do Islão da TDV, a unidade começou a instrução a 12 de junho de 1826, mas os janízaros viram nisso o fim do seu próprio corpo. A revolta que rebentou três dias depois pôs termo também à curta vida do Corpo Eşkinci.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["Foi criado o Asâkir-i Mansûre-i Muhammediyye", "14b84a7e"], "d": ["Logo a seguir à abolição do Corpo dos Janízaros, Mahmud II mandou criar, em seu lugar, um novo exército regular e com instrução à europeia. Segundo o artigo Asâkir-i Mansûre-i Muhammediyye da Enciclopédia do Islão da TDV, este exército, com a sua ordem de postos, o seu programa de instrução e o seu sistema de soldos, converteu-se, ao contrário das tentativas anteriores, numa instituição duradoura. O exército transformar-se-ia, nos anos seguintes, no exército Nizâmiye da época do Tanzimat.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["A confraria Bektashi foi encerrada", "f7d9a367"], "d": ["Em simultâneo com a abolição do Corpo dos Janízaros, foi também proibida a confraria Bektashi, conhecida pelos laços religiosos com o corpo. Segundo o artigo Bektaşîlik da Enciclopédia do Islão da TDV, enquanto alguns xeiques de pequenos tekke foram executados, o xeique da dergâh de Hacı Bektaş foi exilado para Amasya e os tekke foram entregues à administração Nakşibendî. A confraria, apesar deste duro golpe, manteve a sua organização de forma secreta.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["O incidente do leque — o pretexto da ocupação", "e949001e"], "d": ["Numa reunião tornada tensa pelo não pagamento da antiga dívida de cereais da França à Argélia, o dei Hüseyin bateu com o leque que tinha na mão no cônsul francês Deval. Este incidente, nascido de uma disputa de créditos, foi feito o pretexto oficial da ocupação que começaria três anos depois.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["O bloqueio francês da costa de Argel — o cerco de três anos", "d0ba97a5"], "d": ["Depois do incidente do leque, a França bloqueou a costa argelina. O bloqueio durou três anos; o comércio marítimo e as fontes de receita da milícia (ocak) secaram e a sua capacidade de resistência foi corroída antes de começar a ocupação.", "79d27be2"]},
"OLAYLAR_EK7:1828-02-22:0":{"b": ["O Tratado de Turkmenchay: a passagem de Erevan e Talysh para a Rússia", "abffcfdb"], "d": ["Quando a guerra russo-persa de 1826-1828 terminou com uma pesada derrota do Irão, pelo tratado assinado em Turkmenchay os canatos de Revan e Nakhichevan e a região de Talysh (Lenkoran, Astara), na costa do Cáspio, foram cedidos à Rússia; foi imposta também uma pesada indemnização de guerra. Segundo o artigo Revan da Enciclopédia do Islão da TDV, esta perda é o momento em que foi traçada a fronteira russo-persa no Cáucaso, de modo a manter-se em grande parte válida até hoje, e desencadeou também a emigração da população arménia para Revan.", "f6438d89"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["A segunda queda de Ibraila — o czar Nicolau diante da fortaleza", "eb6a8741"], "d": ["Ibraila, devolvida aos otomanos em 1812 e novamente fortificada em 1817-1818, foi cercada em abril, tendo no interior 4000 guardas e 278 canhões. O seu guarda Ebûbekir Paxá estabeleceu uma nova linha de defesa; o czar Nicolau I chegou pessoalmente diante da fortaleza no fim de maio. A cidade sofreu a ocupação russa, mas seria devolvida pelo Tratado de Edirne e deixada ao principado da Valáquia.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["A proclamação do fez como chapéu oficial", "f55be4eb"], "d": ["Mahmud II, fazendo uma mudança radical no vestuário dos funcionários e dos soldados, proclamou o fez como cobertura de cabeça oficial, em lugar do turbante. Segundo o artigo Fes da Enciclopédia do Islão da TDV, esta decisão foi anunciada por um hatt-ı hümâyun e posta em prática juntamente com as reformas de estilo ocidental do Asâkir-i Mansûre-i Muhammediyye. A mudança significava também o fim da hierarquia tradicional do vestuário.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["A cedência de Ahıska à Rússia — o centro da província de Çıldır perde-se", "e2e00b2a"], "d": ["Ahıska, que estava sob administração otomana desde a Batalha de Çıldır de 1578 e fora centro da província de Çıldır, foi cedida à Rússia pelo Tratado de Edirne, assinado no fim da guerra de 1828-1829. A perda da cidade criou profunda tristeza entre o povo e foi tema de muitas elegias.", "9ad8078a"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["O desembarque de Sidi Ferruch — o exército francês em solo argelino", "33327553"], "d": ["Depois do bloqueio de três anos, o exército francês de desembarque comandado pelo conde de Bourmont desembarcou tropas na baía de Sidi Ferruch, a oeste de Argel. As forças que avançavam para a cidade romperam em três semanas a linha de defesa; a 4 de julho caiu o Forte do Imperador, que domina a cidade, e no dia seguinte o dei Hüseyin rendeu-se.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["O exílio do dei Hüseyin — o fim de facto da milícia (ocak) de Argel", "e122403b"], "d": ["Em virtude das condições de rendição, o último dei de Argel, Hüseyin, foi retirado da cidade com a família e o tesouro e enviado para Nápoles. A administração da milícia (ocak), que se ligara a Selim II em 1519 e fora durante trezentos anos a mais forte base naval otomana no Mediterrâneo, terminou assim.", "54846340"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["A retirada do exército russo da Valáquia e da Moldávia — o fim da ocupação de seis anos", "efdb0275"], "d": ["Na guerra otomano-russa de 1828-1829, os russos tinham ocupado a Valáquia e a Moldávia e, depois do Tratado de Edirne, não se tinham retirado até que a indemnização de guerra fosse paga. Em janeiro de 1834, quando a indemnização foi reduzida a cinco milhões, as forças russas evacuaram os Principados e foram nomeados novos voivodas para os dois principados. A suserania otomana voltou no papel, mas a Rússia manteve a influência que estabelecera com o Règlement Organique.", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["Foi criada a organização Redif-i Asâkir-i Mansûre", "15947493"], "d": ["A organização Redif, como força de reserva que apoiaria o Asâkir-i Mansûre-i Muhammediyye, foi criada pelo regulamento de 8 de julho de 1834. Segundo o artigo Redif da Enciclopédia do Islão da TDV, sob a direção do serasquer Koca Hüsrev Paxá, formaram-se nos distritos provinciais batalhões de cerca de mil e quatrocentos homens cada. A organização foi concebida para apoiar também a segurança local sem ser posta em serviço permanente.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["Foi criado o Ministério dos Negócios Estrangeiros", "750c6c7d"], "d": ["Mahmud II, abolindo o cargo de Reisülküttâb, que conduzia os negócios estrangeiros, criou em seu lugar o Hariciye Nezareti. Segundo o artigo Hariciye Nezâreti da Enciclopédia do Islão da TDV, para o primeiro ministério do novo nezaret foi posto Mehmed Âkif Paxá e a organização começou a funcionar na mansão do embaixador em Viena, Rıfat Bey. Esta disposição foi o início da condução da política externa otomana segundo o princípio do ministério moderno.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["Foi criado o Meclis-i Vâlâ-yı Ahkâm-ı Adliyye", "69db056e"], "d": ["Mahmud II mandou criar o Meclis-i Vâlâ-yı Ahkâm-ı Adliyye como conselho de alto nível em que se discutiriam as leis e os regulamentos a preparar. Segundo o artigo Meclis-i Vâlâ-yı Ahkâm-ı Adliyye da Enciclopédia do Islão da TDV, o conselho começou de facto a funcionar a 31 de março de 1838 e quase todas as reformas posteriores do Tanzimat foram preparadas e fiscalizadas através deste órgão. A instituição converteu-se num dos mais importantes centros da burocracia otomana moderna.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["O Assalto a Sinope", "5947e93f"], "d": ["A frota russa do mar Negro, sob o comando do almirante Nakhimov, atacou sem declaração de guerra a frota otomana fundeada no porto de Sinope; afundaram-se doze navios, mais de dois mil soldados caíram como mártires e o comandante da frota, Osman Paxá, foi feito prisioneiro. Segundo o artigo Sinop da Enciclopédia do Islão da TDV, no assalto arderam também na cidade sete mescides, duas escolas, 247 casas e 170 lojas, e perderam a vida civis, cinco muçulmanos e dezasseis cristãos. O caso, que ecoou na opinião pública europeia como o 'desastre de Sinope', foi o desencadeador direto da entrada da Inglaterra e da França na guerra, ao lado dos otomanos, em poucos meses.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["Foi publicado o Tasvir-i Efkâr", "506c98e2"], "d": ["O Tasvir-i Efkâr, publicado por Şinasi, começou a sair como o quarto jornal turco, depois de Takvîm-i Vekāyi', Cerîde-i Havâdis e Tercüman-ı Ahvâl. Segundo o artigo \"Tasvîr-i Efkâr\" da TDV, o jornal tornou-se, no tempo de Nâmık Kemal, que viria a assumir a chefia de redação, o porta-voz do movimento dos Novos Otomanos.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["Foi fundada a Sociedade dos Novos Otomanos", "335fb02d"], "d": ["Os intelectuais otomanos que fugiram para a Europa, sob a liderança de Mustafa Fâzıl Paxá, organizaram-se com um regulamento de treze artigos sob o nome de Jovem Turquia. Segundo o artigo \"Yeni Osmanlılar Cemiyeti\" da TDV, o grupo difundiu a exigência de governo constitucional publicando em Paris, Londres e Genebra jornais como Muhbir e Hürriyet.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["Foi criado o Şûrâ-yı Devlet", "b863b306"], "d": ["O Meclis-i Ahkâm-ı Adliyye foi dividido em dois, criando-se o Şûrâ-yı Devlet, que tratava dos assuntos administrativos, e o Dîvân-ı Ahkâm-ı Adliyye, que cuidava dos assuntos judiciais. Segundo o artigo \"Şûrâ-yı Devlet\" da TDV, para a primeira presidência da instituição, que tomou por modelo o Conseil d'État francês, foi posto Midhat Paxá; o objetivo era a separação do legislativo, do executivo e do judicial.", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["Saiu a ordem de fundação do Darülfünun", "513704bf"], "d": ["Com a ordem preparada pelo grão-vizir Âli Paxá e pelo ministro da Instrução Saffet Paxá, o Darülfünun foi oficialmente fundado; as primeiras aulas já tinham começado em 1863. Segundo o artigo \"Darülfünun\" da TDV, a instituição passou de facto ao ensino em fevereiro de 1870, sob a direção de Hoca Tahsin Efendi, com os ramos de filosofia-letras, ciências e direito.", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["Começaram os trabalhos da Mecelle-i Ahkâm-ı Adliyye", "8abdcbee"], "d": ["A Sociedade da Mecelle, formada sob a presidência de Ahmed Cevdet Paxá, presidente do Dîvân-ı Ahkâm-ı Adliyye, empenhou-se na preparação de um código civil baseado no direito hanafita. Segundo o artigo \"Mecelle-i Ahkâm-ı Adliyye\" da TDV, o último fascículo da obra, composta por dezasseis livros e 1851 artigos, foi concluído e entrou em vigor a 15 de setembro de 1876; é considerada a primeira forma codificada do direito islâmico.", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["Foi representada \"Pátria ou Silistria\", Nâmık Kemal foi enviado para o exílio", "3861284c"], "d": ["Quando a peça de tema patriótico de Nâmık Kemal foi representada no Teatro de Gedikpaşa, os espectadores saíram às ruas gritando \"Viva a pátria, viva Kemal\". Segundo o artigo \"Nâmık Kemal\" da TDV, o governo, assustado com esta manifestação, encerrou o jornal İbret e a 6 de abril de 1873 enviou Nâmık Kemal, sem julgamento, para o exílio em Chipre (Famagusta).", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["Abdülaziz morreu em circunstâncias suspeitas", "85816692"], "d": ["Abdülaziz, que depois de deposto fora, por sua própria vontade, transferido para o Palácio de Feriye (1 de junho de 1876), foi encontrado a 4 de junho no seu quarto com as veias dos pulsos cortadas. Uma junta de dezanove médicos, em que figuravam também médicos das embaixadas, preparou um relatório de redação ambígua; a morte foi anunciada nos jornais a 6 de junho como suicídio. O inquérito mandado abrir por Abdülhamid II chegou, em contrapartida, à convicção de que a morte não fora suicídio, mas assassinato, e os acusados foram julgados em 1881 no Tribunal de Yıldız; a questão é ainda hoje discutida na historiografia.", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["A destituição e o exílio de Midhat Paxá do grão-vizirado", "b5247b06"], "d": ["O grão-vizir Midhat Paxá, arquiteto do Kanun-i Esasi, foi destituído por Abdülhamid II seis semanas depois da sua proclamação e enviado para o exílio no estrangeiro numa só noite. Segundo o artigo Midhat Paşa da Enciclopédia do Islão da TDV, a destituição é associada ao desagrado do sultão com as disposições da constituição que limitavam os seus poderes. O paxá foi primeiro a Nápoles e depois a várias cidades da Europa.", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["A recuperação de Riade aos Reşîdîs por Abdülazîz b. Suûd", "75eb8830"], "d": ["O jovem Abdülazîz, da dinastia Saud, que dez anos antes fora para o exílio no Kuwait, com um pequeno destacamento atacou de surpresa Riade, matou o vice-governador do Âl-i Reşîd (Shammar) e tomou a cidade. Segundo o artigo Riyad da Enciclopédia do Islão da TDV, o enfraquecimento progressivo dos Reşîdîs e o facto de não poderem enviar reforços à cidade facilitaram o êxito do ataque; o caso é considerado o momento da fundação do Segundo Estado Saudita, que nos trinta anos seguintes formaria o núcleo da atual Arábia Saudita.", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["A entrada do Exército de Ação em Istambul", "41c8304c"], "d": ["O Exército de Ação, que partiu de Salónica e era formado em maioria por unidades ligadas ao Comité de União e Progresso, entrou em Istambul para reprimir a revolta de 31 de Março. Segundo o artigo Hareket Ordusu da Enciclopédia do Islão da TDV, o comando foi assumido por Mahmud Şevket Paxá e a chefia do estado-maior foi exercida pelo capitão Mustafa Kemal. Depois de breves combates, a ordem foi restabelecida na cidade.", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["A dissolução da última Assembleia dos Deputados Otomana", "2b709269"], "d": ["Depois de Istambul ter sido oficialmente ocupada pelas forças da Entente e de muitos deputados terem sido presos, a Assembleia dos Deputados ficou impossibilitada de trabalhar e foi oficialmente dissolvida pela vontade de Mehmed VI. Segundo o artigo Meclis-i Mebusan da Enciclopédia do Islão da TDV, esta dissolução simbolizou o fim de facto da tradição parlamentar constitucional otomana. O encerramento reforçou a necessidade de reunir em Ancara uma nova assembleia nacional.", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["A abertura da Grande Assembleia Nacional da Turquia", "6eab539d"], "d": ["Depois da dissolução da Assembleia dos Deputados em Istambul, os deputados reuniram-se em Ancara e abriram a Grande Assembleia Nacional da Turquia, e Mustafa Kemal Paxá foi eleito presidente da assembleia. Segundo o artigo Türkiye Büyük Millet Meclisi da Enciclopédia do Islão da TDV, a assembleia teve um caráter extraordinário, reunindo em si poderes legislativos e executivos. Esta abertura foi o ponto de viragem em que o centro político e institucional da luta nacional se deslocou para Ancara.", "805871d7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["A conquista da fortaleza de Zvornik", "657c465a"], "d": ["A fortaleza de Zvornik, na margem do Drina, foi conquistada pelos otomanos em 1460. Segundo a Enciclopédia do Islão da TDV, devido à sua posição favorável do ponto de vista administrativo e militar, foi feita primeiro centro de kaza, em 1480 transformada em centro do sanjaco com o mesmo nome e, em 1491, fortificada com muralhas de pedra e convertida, com as suas seis mesquitas, oito tekke e banhos, num importante centro administrativo-comercial.", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["A morte de Kâsım Han, a subida ao trono de Danyal Han (Canato de Kasım)", "522fd0fd"], "d": ["Com a morte do fundador do canato, Kâsım Han, em 873/1468, sucedeu-lhe o filho Danyal; Danyal reinou até 1486.", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["A Batalha Naval de Diu — a supremacia de Portugal no oceano Índico", "1778d347"], "d": ["A frota de Melik Ayaz, que governava a região em nome do Sultanato do Guzerate, apoiada pelos mamelucos, sofreu uma pesada derrota ao largo de Diu perante a esquadra do governador-geral português Francisco de Almeida, que procurava estabelecer bases de abastecimento nestas costas. Esta derrota deu a Portugal uma supremacia naval duradoura no oceano Índico e quebrou o poder naval mameluco-guzerate; é considerada o início do desequilíbrio de forças que forma o pano de fundo da luta no mar Vermelho e no oceano Índico que os otomanos herdaram depois de 1517 (a defesa de Jidá, o cerco de Diu de 1538).", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["A revolta de Kalender Xá", "f60f6ca4"], "d": ["Com as dificuldades financeiras na Anatólia, o descontentamento com as novas disposições administrativas e o efeito da propaganda safávida, grandes tribos turcomanas como as Çiçekli, Akça Koyunlu, Masadlı e Bozoklu, juntamente com grupos que restavam da anterior revolta de Baba Zünnûn, reuniram-se à volta de Kalender Xá e atingiram uma força de cerca de trinta mil pessoas. Os rebeldes derrotaram primeiro o beylerbeyi de Rum; com o grão-vizir Makbul İbrâhim Paxá a reunir soldados e a prometer-lhes direitos, o apoio a Kalender dissolveu-se e a revolta foi reprimida na região de Elbistan; Kalender Xá e Veli Dündar foram mortos em junho de 1527.", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["A conquista de Şehrizor — a tomada da fortaleza de Zalm", "4320d9b8"], "d": ["Durante a campanha de Nakhichevan do Legislador, o beylerbeyi de Bagdade Osman Paxá fora encarregado de tomar a região de Şehrizor; Baltacı Mehmed Paxá, que se tornou beylerbeyi de Bagdade com a morte dele, cercou Zalm, a fortaleza central da região, e tomou-a a 22 de agosto de 1554 (23 de Ramazan de 961). Assim, a bacia de Şehrizor, na vertente ocidental do Zagros, entrou na administração otomana e a ligação entre Bagdade e o Curdistão ficou assegurada; a região foi primeiro feita sanjaco e dada a Murad Bey. Em 1563, o beylerbeyi Muzaffer Paxá construiu como novo centro de província a fortaleza de Gülanber; a fortaleza seria demolida em 1623 por ordem do xá Abbas e reconstruída em 1638, no tempo de Hüsrev Paxá.", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["A conversão ao cristianismo do soberano do Canato de Kasım e a sua remoção do canato", "a1a8eeb9"], "d": ["O soberano à frente do canato tomou o nome de 'Semen (Simeão)' e fez-se cristão; os russos, tendo em conta a reação dos súbditos muçulmanos, retiraram-no do canato. Esta pessoa foi pouco depois proclamada por Ivan, o Terrível, soberano nominal em Moscovo com o título de 'grão-príncipe do czar e da Rússia' (1575) — o cruzamento mais impressionante entre o Canato de Kasım e o trono de Moscovo.", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["A ligação do sanjaco de Fezzan a Trípoli de Barbaria — Murzuk e a encruzilhada de caravanas do Saara", "2e6554a4"], "d": ["Em resultado da pressão do beylerbeylik de Trípoli de Barbaria, Fezzan, encruzilhada de caravanas do Saara, aceitou a sujeição otomana, com centro em Murzuk. Segundo o artigo Fizan da Enciclopédia do Islão da TDV, a dinastia Evlâd-ı Muhammed, que governava a região, foi deixada livre nos seus assuntos internos com a condição de pagar um imposto regular; Fezzan foi organizado como sanjaco dependente da província de Trípoli, tomada em 1551. Assim, o comércio de escravos, ouro e camelos na linha Trípoli-Murzuk-Bornu entrou sob controlo otomano. Esta administração indireta passaria em 1711 para as mãos dos Karamanlı e, em 1842, para a organização direta de kaza.", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["A entrada de Nakhichevan e Ordubad na administração otomana", "24d939b3"], "d": ["Depois da tomada de Revan em 1583 e de ser feita centro de beylerbeylik, as forças que desceram para sudeste ao longo do vale do Aras ligaram Nakhichevan e Ordubad à administração otomana; as duas cidades tornaram-se sanjacos da recém-criada província de Revan. Segundo o artigo Nahcıvan da Enciclopédia do Islão da TDV, a primeira administração otomana duradoura na cidade foi estabelecida durante esta guerra — na campanha de Nakhichevan de 1553 a cidade fora tomada, mas apenas saqueada e abandonada. Assim, abriu-se a estrada militar entre Revan e Tabriz e foi possível entrar em Tabriz em setembro do mesmo ano. O xá Abbas retomaria Nakhichevan em 1603.", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["A revolta de Deli Hasan Paxá e o seu apaziguamento com o beylerbeylik da Bósnia", "144f3f2d"], "d": ["Deli Hasan, irmão que se pôs à frente do movimento depois da morte, em 1602, do líder celali Karayazıcı Abdülhalim, aproveitando a liberdade de movimentos que as guerras austríacas em curso davam aos grupos celalis, invadiu Kütahya e marchou sobre Afyonkarahisar. Neste período em que o Estado lidava ao mesmo tempo com as frentes austríaca e persa, a questão foi resolvida 'com brandura': dando a Deli Hasan o posto de paxá e o beylerbeylik da Bósnia, o movimento de revolta foi oficialmente encerrado em 1603.", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["A tomada da cidade de Kasım pelas forças russas, Uraz Muhammed Han", "b3f0bd34"], "d": ["Como reflexo do Tempo das Perturbações (Smuta) na Rússia, as forças russas cercaram e tomaram a cidade de Kâsım, passando a fio de espada a maior parte da sua população. Uraz Muhammed, que estava à frente do canato, fora visado por apoiar o Falso Dimitri II; no ano seguinte (1610) foi também morto numa conspiração.", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["A perda da fortaleza de Azak para os cossacos do Don", "ba068b2f"], "d": ["Os cossacos do Don tomaram dois meses depois a fortaleza de Azak, que tinham cercado a 21 de abril de 1637; a fortaleza, porta nordeste do mar Negro e chave do comércio do Don, saiu pela primeira vez das mãos dos otomanos. Segundo o artigo Azak da Enciclopédia do Islão da TDV, os cossacos tomaram a fortaleza em 1637, resistiram em 1641 ao grande cerco de três meses comandado por Deli Hüseyin Paxá e só em 1642, com a chegada do cã da Crimeia Mehmed Giray, evacuaram a fortaleza. O Estado estava então ocupado com a frente de Bagdade; o facto de a fortaleza não ter podido ser mantida por cinco anos é a primeira fissura na qualidade de 'lago otomano' do mar Negro.", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["A reconquista de Lemnos e Samotrácia", "c445553b"], "d": ["Depois da libertação de Tenedos a 31 de agosto de 1657, Köprülü Mehmed Paxá orientou a frota para norte e retomou Lemnos e Samotrácia, que Veneza detinha havia dezasseis meses. Segundo o artigo Limni da Enciclopédia do Islão da TDV, a ilha caíra nas mãos de Veneza em julho de 1656 e foi retomada em novembro de 1657. Assim, o bloqueio veneziano na entrada do estreito de Çanakkale foi totalmente quebrado e a rota dos cereais de Istambul voltou a ficar segura; é o ganho mais concreto do primeiro ano em que o grão-vizir chegou com poderes extraordinários.", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["A perda de Knin para Veneza — caiu a fortaleza de fronteira da Dalmácia, de 166 anos", "252406b7"], "d": ["Na guerra aberta em várias frentes depois do desastre de Viena de 1683, as forças venezianas avançaram para o interior da Dalmácia. Knin, cercada pelo general da Dalmácia Girolamo Cornaro, foi entregue pelo beylerbeyi Mehmed Paxá depois de um cerco de doze dias. Knin era a fortaleza-chave da linha de fronteira da Dalmácia que Gazi Hüsrev Bey conquistara em 1522 e que durante 166 anos esteve nas mãos otomanas; a sua perda abriu em grande parte a região a Veneza.", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["A reconquista de Bassorá à ocupação persa", "5b10c5c1"], "d": ["Bassorá, que Sâdık Han, irmão de Kerim Han Zend, tomara em 1776, foi evacuada quando, depois da morte de Kerim Han a 2 de março de 1779, começou no Irão a luta pelo trono; Sâdık Han voltou ao Irão com a pretensão ao sultanato. A cidade ficou por um breve período nas mãos da tribo dos Müntefik e depois voltou à administração otomana. O antigo mütesellim Süleyman Ağa, regressado de Xiraz, pediu o governo de Bassorá e tornou-se, com o nome de Büyük Süleyman Paxá, governador de Bassorá, Bagdade e Şehrizor. O comércio do golfo voltou ao controlo otomano; nos anos da ocupação, parte do comércio deslocara-se para o Kuwait e, desde 1778, também o correio do deserto saía do Kuwait.", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["A morte de Timur Xá, a entronização de Zaman Xá (Estado Durrani)", "c3effdb2"], "d": ["Com a morte de Timur Xá, que durante mais de vinte anos consolidou o país por dentro, os três irmãos governadores de Kandahar-Herat-Cabul disputaram o trono; Zaman Xá, governador de Cabul, que detinha a capital, tornou-se xá a 20 de maio de 1793. Esta crise sucessória é, de facto, o início do processo de fragmentação da dinastia.", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa — o fim do sistema tradicional kapu no Havai", "0b10e1d8"], "d": ["Seis meses depois da morte de Kamehameha I, o novo rei Liholiho, com o apoio da mãe Kaʻahumanu, violou deliberadamente a proibição de homens e mulheres comerem separados (ʻaikapu). Este ato, conhecido por 'ʻAi Noa' (refeição livre), pôs oficialmente termo ao tradicional sistema religioso-jurídico kapu; os antigos templos (heiau) das ilhas foram em pouco tempo demolidos. É a maior rutura religioso-política anterior à chegada dos missionários ocidentais (1820).", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["O Protocolo de Londres — o reconhecimento da independência da Grécia", "4c7b4b72"], "d": ["O protocolo assinado em Londres pela Inglaterra, França e Rússia, ultrapassando a autonomia prevista pelo Tratado de Edirne, reconheceu a Grécia como Estado INDEPENDENTE. Disposições: a península da Moreia, a Ática e Negroponte, com as ilhas Cíclades, foram deixadas ao novo Estado; a fronteira foi traçada na linha Arta-Volos; decidiu-se o pagamento de uma indemnização ao Estado Otomano; a forma de governo do Estado foi determinada como 'monarquia independente'. Foi o PRIMEIRO Estado independente separado do império e estabeleceu o modelo jurídico das independências balcânicas seguintes.", "e8fc6290"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["Abdullah b. Reşîd tomou o emirado de Hail — a fundação da dinastia Shammar (Reşîdî)", "fb513b8a"], "d": ["Com a queda de Dir'iyye às forças de Mehmed Ali Paxá em 1818, a região de Jabal Shammar saiu do domínio saudita e o emirado ficou nas mãos da família Ibn Ali. Abdullah b. Reşîd, que apoiava o restabelecimento do domínio otomano, ganhou em 1835, com o irmão Ubeyd, a luta que travou contra a família Ibn Ali, tomou o emirado de Hail e estabeleceu o domínio da dinastia Reşîdî.", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["Foi proclamada a primeira constituição escrita do Havai", "401a8a1d"], "d": ["Foi proclamada a primeira constituição inteiramente escrita do reino; este documento, que limitava o poder do rei e instituía uma assembleia representativa, transformou o Havai numa monarquia constitucional.", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["A Constituição da Baioneta — os poderes do rei Kalākaua foram cerceados", "4953363b"], "d": ["Um grupo de milícia armada ameaçou o rei Kalākaua e forçou-o a assinar uma nova constituição que cerceava em grande parte os poderes da monarquia; o documento é conhecido como 'Constituição da Baioneta' (Bayonet Constitution) e pôs o trono de facto sob o controlo da elite colona branca.", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["A morte de George Tupou I, a subida ao trono de George Tupou II (Tonga)", "b56e2b32"], "d": ["Com a morte do rei fundador George Tupou I, passou ao trono o bisneto George Tupou II; a cerimónia de coroação realizou-se a 17 de março de 1893 em Nukuʻalofa.", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["A Nova Zelândia tornou-se o primeiro país autogovernado a conceder o voto às mulheres", "0d277cde"], "d": ["Com a nova Lei Eleitoral assinada pelo governador Lord Glasgow, a Nova Zelândia tornou-se o primeiro país autogovernado do mundo a conceder às mulheres o direito de voto nas eleições parlamentares.", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["Foi proclamada a República do Havai", "4346bd5d"], "d": ["Os conspiradores que em 1893 derrubaram a rainha Liliuokalani converteram o governo provisório numa república formal; Sanford Dole foi proclamado presidente. Este regime intermédio durou até à anexação pelos EUA em 1898.", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["As fronteiras da Nova Zelândia alargaram-se de modo a abranger as ilhas Cook e Niue", "d0370a33"], "d": ["As fronteiras da Nova Zelândia foram alargadas de modo a abranger as ilhas Cook (Rarotonga, Aitutaki e as ilhas do sul, e as ilhas Cook do norte) e Niue; estas ilhas passaram a ser território dependente da Nova Zelândia.", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["A morte de George Tupou II, a subida ao trono de Sālote Tupou III (Tonga)", "a3084f3b"], "d": ["George Tupou II morreu de tuberculose; a filha de 18 anos, Sālote, foi proclamada rainha no dia seguinte e a cerimónia de coroação realizou-se a 11 de outubro de 1918.", "a63672b5"]},
"OLAYLAR_EK8:1920-04-26:0":{"b": ["Foi proclamada a República Popular de Khwarazm", "0a6b79f9"], "d": ["Depois da derrubada do cã de Khiva, a seguir à Revolução de Outubro de 1917, foi proclamada a República Popular de Khwarazm.", "1934b071"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["O Tratado de Sèvres — o texto da partilha do império", "64980d7b"], "d": ["O texto que o governo otomano assinou com as potências da Entente e que liquidava de facto o império. Disposições: a Trácia Oriental e a região de İzmir para a Grécia; na Anatólia Oriental, previram-se uma Arménia independente e um Curdistão autónomo; a Síria foi deixada à França e o Iraque e a Palestina à Inglaterra como mandatos; os Estreitos foram entregues a uma comissão internacional; o exército foi reduzido a 50.700 homens, as capitulações voltaram e as finanças foram postas sob controlo da Entente. A Grande Assembleia Nacional de Ancara NÃO RECONHECEU de todo o tratado e declarou traidores à pátria os seus signatários; o texto não entrou em vigor e, em seu lugar, veio em 1923 Lausana. Esta é a razão de não ter correspondência no mapa — Sèvres nunca foi aplicado juridicamente.", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["O Exército Vermelho entrou na cidade de Bucara — o último emir Âlim Han foi afastado do trono", "f8f5bfcf"], "d": ["O Exército Vermelho entrou na cidade de Bucara a 2 de setembro de 1920 e o último emir mangıt, Âlim Han, foi afastado do trono. O emir recuou para o leste do país, para Düşenbe, e de lá dirigiu durante meio ano a luta contra os soviéticos; o Exército Vermelho tomou Düşenbe a 21 de fevereiro de 1921 e o emir passou mais para leste e dali para o Afeganistão. O canato foi oficialmente abolido a 6 de outubro de 1920 (ver República Popular Soviética de Bucara).", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["Foi proclamada a República Popular Soviética de Bucara", "ef579627"], "d": ["Depois de o Exército Vermelho, a 28-31 de agosto de 1920, ter derrubado o Emirado de Bucara e feito fugir o emir Alim Han para a Bucara Oriental, foi proclamada a República Popular Soviética de Bucara, presidida por Feyzullah Hocayev.", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["A República Popular de Tannu Tuva proclamou a sua independência", "8710ea3d"], "d": ["A independência foi proclamada sob a liderança do Partido Revolucionário Popular de Tuva; o primeiro artigo da primeira constituição estipulava que o Estado atuava 'nas relações internacionais sob a proteção da Rússia Soviética'.", "3c6cec2c"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["Foi aprovada a nova constituição da República Popular Soviética de Bucara", "fb17bf39"], "d": ["Foi aprovada uma nova constituição que, ao contrário da constituição russa de 1918, permitia a propriedade privada da terra e da produção e concedia também o direito de voto aos não proletários (com exceção dos parentes do emir deposto e dos grandes proprietários).", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["A transformação em República Socialista Soviética de Khwarazm", "14a1d26f"], "d": ["O país, mudando de nome e de estatuto, tornou-se a República Socialista Soviética de Khwarazm; a estrutura administrativo-legal foi reorganizada segundo o sistema soviético.", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["O governo de Tannu Tuva entrou de facto em funções", "22ea1516"], "d": ["O governo formado depois da primeira reunião do partido, em fevereiro de 1922, entrou de facto em funções.", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["Reuniu-se o primeiro Grande Khural de Tannu Tuva", "80fe15f2"], "d": ["Reuniu-se o primeiro Grande Khural (Assembleia Popular) do país; é a primeira grande reunião representativa no processo de institucionalização do Estado.", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["O fim da RSS de Khwarazm e da República Popular Soviética de Bucara com a delimitação nacional — a fundação das RSS do Usbequistão e do Turcomenistão", "e8c8ab4f"], "d": ["Pela decisão soviética de 'delimitação nacional' (natsionalno-territorialnoe razmezhevanie), a República Socialista Soviética de Khwarazm e a República Popular Soviética de Bucara foram abolidas; os seus territórios foram repartidos entre as recém-criadas Repúblicas Socialistas Soviéticas do Usbequistão e do Turcomenistão (o leste de Khiva para o Usbequistão, o oeste para o Turcomenistão). O artigo `harizm` da TDV: 'Em 1924, as partes orientais do Canato de Khiva foram deixadas à República Socialista Soviética do Usbequistão e a parte ocidental à República Socialista Soviética do Turcomenistão.' — dá apenas o ano.", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["A venda de Alanya ao sultão mameluco Barsbay", "c8bd35f2"], "d": ["Alanya, tomada em 1293 por Karamanoğlu Mecdüddin Mahmud Bey, tornara-se um beylik separado, governado por um ramo dos Karamanoğulları; Ibn Battuta regista em 1333 que a administração estava com Karamanoğlu Yûsuf Bey. Karaman b. Savcı Bey vendeu em 1427 a cidade ao sultão mameluco Barsbay por cinco mil moedas de ouro e Alanya entrou na administração mameluca. Este porto-chave do Mediterrâneo tornou-se assim um obstáculo, em mãos mamelucas, no caminho dos otomanos para o sul; em 1471, quando Gedik Ahmed Paxá a cercou, o último bei, Kılıcarslan, entregou a cidade.", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["A tomada de Tabarka aos genoveses — o fim da concessão do coral dos Lomellini", "b1f33eb5"], "d": ["Depois do tratado que Carlos V fez em 1544 com o bei de Tunes, a família genovesa Lomellini fixara-se na ilha de Tabarka e durante duzentos anos detivera a concessão do coral; a ilha permanecera, no meio da Tunísia otomana, como um posto comercial cristão. Ali Paxá, da dinastia Husseinita, ao saber da tentativa da família de se desfazer da ilha, enviou forças e tomou a ilha a 12 de junho de 1741; cerca de mil e quinhentos cristãos foram transferidos para Tunes. Tabarka passou, a partir desta data, para a administração da milícia (ocaklık) de Tunes.", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["A Batalha das Pirâmides e a tomada do Cairo pelos franceses", "3ddd6b96"], "d": ["Napoleão marchou de Alexandria para sul ao longo do Nilo e, a 21 de julho de 1798, enfrentou em Embabeh, em frente a Gizé, a cavalaria mameluca de Murad Bey. A infantaria francesa, em formação quadrada, quebrou as cargas de cavalaria; o exército mameluco dispersou-se e o Cairo rendeu-se dois dias depois sem resistência. Murad Bey recuou para o Alto Egito e İbrâhim Bey para a Síria. Os franceses estabeleceram no Cairo um dîvân e procuraram conduzir a administração por meio dos ulemás; em outubro de 1798 e em março de 1800 rebentaram duas grandes revoltas no Cairo.", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["O cerco de Acre por Napoleão — a paragem da campanha da Síria", "d2a947ad"], "d": ["Napoleão, que queria dispersar as forças que os otomanos preparavam para retomar o Egito, marchou para a Síria no início de 1799; tomou Arish a 18 de fevereiro e Jafa em março e, a 18 de março de 1799, cercou Acre. A defesa de Cezzâr Ahmed Paxá e o apoio, por mar, do almirante inglês Sidney Smith quebraram o cerco durante dois meses; como a artilharia de cerco foi capturada no mar, as muralhas não puderam ser transpostas. Napoleão retirou-se em maio e esta derrota foi o ponto extremo da ocupação francesa.", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["A fundação do Estado do emir Abdelkader — a centralização da resistência no oeste da Argélia", "9e482383"], "d": ["A resistência, que se dissolvera depois da queda de Argel, reuniu-se à volta do jovem Abdelkader, filho do xeique Kādirî Muhyiddin; a 22 de novembro de 1832, perto de Mascara, os chefes tribais prestaram-lhe fidelidade com o título de 'emîrü'l-mü'minîn'. A estrutura que fundou não era uma aliança tribal, mas um Estado regular: tinha casa da moeda, oficina de pólvora, ordem fiscal e uma capital em Tagdempt. A França reconheceu oficialmente o seu domínio pelo Tratado de Tafna de 1837. Abdelkader refugiou-se não nos otomanos, mas na suserania do sultão de Marrocos Abderramão; ou seja, estas terras, depois de 1832, não são sujeitas otomanas. Rendeu-se a 23 de dezembro de 1847 e o Estado Otomano declarou no mesmo ano que os seus direitos sobre a Argélia tinham terminado.", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["A queda de Constantina — o fim do beylik da Argélia oriental", "159fed36"], "d": ["Depois da queda de Argel em 1830, o beylerbeylik oriental não se dissolveu: o último bei, Ahmed, continuou em Constantina o seu próprio governo e declarou agir em nome dos otomanos. A primeira expedição dos franceses, em 1836, terminou em desastre; a segunda cercou a cidade a 6 de outubro de 1837, o comandante Damrémont morreu a 12 de outubro com fogo de canhão e a 13 de outubro as muralhas foram transpostas e a cidade foi tomada rua a rua. Ahmed Bey retirou-se para as montanhas e só se rendeu em 1848. Esta data é o fim de facto da administração otomano-turca de trezentos anos no leste da Argélia.", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["A conquista da região de Taka e a fundação de Kassala", "cc3e0631"], "d": ["O governador do Sudão, Ahmed Paxá Ebû Vidân, ligou em 1840 à administração egípcia a região de Taka, entre os rios Atbara e Gash, e fundou a cidade de Kassala como quartel-general militar. A cidade tornou-se um centro de mudîriyet que controlava a rota de caravanas entre Sennâr e Suakin e a faixa fronteiriça da Abissínia.", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["A ocupação francesa de Mascara — a perda da capital de Abdelkader", "bd363c05"], "d": ["Com a chegada de Bugeaud ao governo, em 1841, a estratégia francesa mudou: em vez de se manter na costa, ocupar uma a uma as cidades do interior. As colunas móveis saídas de Orão, Mostaganem e Medea tomaram os centros do Estado regular de Abdelkader; Mascara, verdadeira capital com a sua casa da moeda, a sua oficina de pólvora e os seus celeiros, era a mais importante delas. O emir renunciou depois a estabelecer um centro fixo e transformou o seu exército no acampamento nómada chamado 'smala'.", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["A ocupação do vale do Chelif e de Tenes — a fundação de Orléansville", "e1eeeb68"], "d": ["Para poderem perseguir Abdelkader, os franceses fundaram em abril de 1843, no meio do vale do Chelif, uma nova cidade chamada Orléansville; no mesmo ano foi também ocupado o porto costeiro de Tenes. Assim, o corredor interior entre Argel e Orão entrou no controlo francês e a resistência nas montanhas de Dahra ficou cercada. A 16 de maio do mesmo ano, a 'smala' nómada de Abdelkader foi encontrada por acaso e dispersada.", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["A fundação do campo fortificado de Sidi Bel Abbès", "fb33ec29"], "d": ["Bugeaud deu a 12 de junho de 1843 ao general Bedeau a ordem de estabelecer em Sidi Bel Abbès um campo fortificado com fossos e muralhas; a construção começou a 18 de junho e, em novembro do mesmo ano, um batalhão da Legião Estrangeira instalou-se aí. O campo tornou-se uma base permanente que controlava a planície interior entre Orão e Tlemcen.", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["A passagem de Nédroma e da faixa fronteiriça com Marrocos para o controlo francês", "61d821f3"], "d": ["Depois da retirada de Abdelkader para Marrocos, em 1843, Nédroma e a costa de Trâra, a noroeste de Tlemcen, entraram no controlo francês. A Batalha de Isly, de 14 de agosto de 1844, pôs em debandada o exército marroquino e a fronteira entre os dois países foi traçada pela Convenção de Lalla Maghnia de 18 de março de 1845; Nédroma ficou do lado argelino desta linha.", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["A queda de Laghouat — a abertura da porta do Saara", "b161b32c"], "d": ["O general Pélissier cercou Laghouat a 21 de novembro de 1852 com uma força de seis mil homens e a cidade caiu a 4 de dezembro, num sangrento assalto. Laghouat era a cidade-oásis que guardava a passagem entre o Tell e o Saara; a sua queda abriu o avanço francês às rotas de caravanas do deserto e preparou o caminho para que a confederação do Mzab fosse sujeita a imposto no prazo de um ano.", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["A anexação da região de Bogos ao Egito", "b2ab83ce"], "d": ["Werner Munzinger Paxá, governador da província 'Sudão Oriental e Costa do Mar Vermelho' que o quediva İsmâil fundara na costa ocidental do mar Vermelho, ligou em 1872 ao Egito a região de Bogos, habitada pelo povo Bilen, e o seu centro, Keren. Foi o avanço mais duradouro do Egito na orla do planalto abissínio e iniciou com a Abissínia uma disputa fronteiriça de doze anos.", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["A anexação do Sultanato de Darfur ao Egito — Zübeyr Paxá entrou em El Fasher", "f41268ed"], "d": ["Zübeyr Rahmet Paxá, reforçado pelo comércio de marfim e de escravos, dispersou a 25 de outubro de 1874, em Menevâşî, o exército Fur com as forças que equipara com espingardas Remington; o sultão İbrâhim morreu na batalha. Zübeyr entrou em El Fasher a 2 de novembro sem combate, e o governo da dinastia Keyra, que durava desde 1603, terminou de facto. Darfur foi assim incorporado nas províncias do Sudão do Egito de Cavala; mas a resistência da família Keyra nas montanhas prolongou-se até 1891.", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["A anexação dos oásis do Mzab (Ghardaïa)", "9372959f"], "d": ["As cidades ibaditas do Mzab tinham aceitado em 1852 pagar imposto à França, mas conservaram a sua administração interna; trinta anos depois, em 1882, a região foi diretamente incorporada no território francês e Ghardaïa foi ligada à administração militar. Assim, a última faixa autónoma do norte do Saara terminou também juridicamente.", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["O bombardeamento de Alexandria e o desembarque inglês", "18d57bf8"], "d": ["Quando o movimento de oficiais liderado por Urâbî Paxá pôs o quediva sob controlo, a Inglaterra interveio, a pretexto da segurança da rota do Suez. A esquadra do almirante Seymour bombardeou as baterias costeiras de Alexandria a 11-12 de julho de 1882; depois do incêndio e do saque ocorridos na cidade, tropas inglesas desembarcaram a 15 de julho. O Estado Otomano não pôde impedir esta operação numa província de que era juridicamente soberano e deixou também sem resposta o convite para participar na intervenção. Dava-se assim o primeiro passo da ocupação que duraria trinta e dois anos.", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["A Batalha de Tel el-Kebir — a dispersão do exército de Urâbî", "8e38fecf"], "d": ["Wolseley, desembarcando as suas forças em Ismaília pelo Canal do Suez e fazendo-as marchar pelo deserto, atacou de surpresa, ao amanhecer de 13 de setembro de 1882, as trincheiras egípcias de Tel el-Kebir; a batalha terminou numa hora. Urâbî rendeu-se no dia seguinte e a cavalaria inglesa entrou no Cairo no mesmo dia. A partir desta data, as finanças, o exército e os negócios estrangeiros do Egito passaram de facto ao controlo inglês; a soberania otomana subsistiu juridicamente até 1914.", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["A Convenção de La Marsa — a conclusão do protetorado sobre Tunes", "71338640"], "d": ["O Tratado do Bardo (Kasrüssaîd) de 12 de maio de 1881 deixara à França os negócios estrangeiros de Tunes, mas deixara ao bei a administração interna; dois anos depois, a Convenção de La Marsa, assinada a 8 de junho de 1883, pôs também as reformas financeiras e administrativas sob controlo francês e completou o protetorado. O Estado Otomano manteve a pretensão de soberania sobre Tunes e nunca reconheceu a ocupação, mas não pôde dar nenhum contrapasso efetivo. Assim, Tunes, milícia (ocaklık) otomana desde 1574, passou oficialmente ao protetorado francês.", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["O desastre de Shaykan — a destruição do exército de Hicks Paxá", "a0e08986"], "d": ["Hicks Paxá, oficial inglês reformado que comandava uma força egípcia de cerca de dez mil homens enviada do Cairo, ao avançar sem água e sem guias no deserto do Cordofão foi cercado a 5 de novembro de 1883 em Shaykan pelas forças do Mahdi, e o exército foi quase totalmente aniquilado. Este desastre quebrou a espinha dorsal da administração egípcia no Sudão: em um mês renderam-se Darfur e Bahr el-Ghazal e todo o Cordofão passou para o Mahdi. O caminho para a queda de Cartum começa aqui.", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["A passagem de Darfur para as forças do Mahdi — a rendição de Slatin Paxá", "6d8992d4"], "d": ["O governador-geral de Darfur, Slatin Paxá, desde 1882 lidava com a revolta mahdista da tribo Rizeykāt; julgando que as derrotas dos seus soldados se deviam à sua condição de cristão, fez-se abertamente muçulmano em 1883 e tomou o nome de Abdülkādir. Depois de o exército de Hicks Paxá ter sido destruído no Cordofão em novembro de 1883, a resistência perdeu sentido e a 23 de dezembro de 1883 rendeu-se ao emir Madibbo. Os pequenos postos egípcios em Darfur seguiram em pouco tempo o mesmo caminho; a administração turco-egípcia de dez anos terminou.", "85dcfe97"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["A passagem de Zeila e da costa da Somália para a administração inglesa", "1d649502"], "d": ["Quando a insurreição do Mahdi fez ruir as guarnições egípcias do Sudão e do mar Vermelho, o Cairo foi obrigado a evacuar os seus postos distantes na costa abissínia. A administração inglesa de Áden desembarcou tropas em Zeila e Berbera em 1884; no ano seguinte, assinaram-se tratados de proteção com os chefes tribais somalis e foi fundada a Somalilândia Britânica. Zeila, ligada à província da Abissínia desde 1559, perdeu-se assim.", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["A rendição da guarnição de Fasher aos mahdistas", "68f0760d"], "d": ["Mesmo depois da rendição de Slatin a 23 de dezembro de 1883, a guarnição egípcia da fortaleza de Fasher resistiu. A guarnição, que perdera os poços num cerco de sete dias, rendeu-se a 15 de janeiro de 1884; as armas foram depostas e a fortaleza passou para os mahdistas.", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["O Tratado de Hewett (Adua) — Bogos foi deixada à Abissínia", "0de1b701"], "d": ["Quando a insurreição do Mahdi cercou as guarnições egípcias no Sudão, a Inglaterra assinou a 3 de junho de 1884, em Adua, um tratado com Yohannes IV, para obter a ajuda da Abissínia. O segundo artigo do tratado devolvia Bogos à Abissínia e, em contrapartida, a Abissínia facilitava a evacuação das guarnições cercadas por Maçuá. Keren saiu assim da administração egípcia de doze anos; cinco anos depois, a região seria incorporada na Eritreia italiana.", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["A reconquista de Dongola — o início da campanha ao longo do Nilo", "f63aa14f"], "d": ["Depois da derrota dos italianos em Adua, a Inglaterra fez marchar o exército egípcio para sul, ao longo do Nilo, sob o comando de Kitchener. À medida que a via-férrea avançava pelo deserto, o problema do abastecimento foi resolvido e a província de Dongola foi recuperada a 23 de setembro de 1896. O governo mahdista de onze anos terminou aqui; a campanha prolongar-se-ia por mais dois anos até chegar a Omdurman.", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["A Batalha de Omdurman — a queda do Estado Mahdista", "28dff7b2"], "d": ["O exército anglo-egípcio de Kitchener, equipado com artilharia e metralhadoras, dispersou em poucas horas, a 2 de setembro de 1898, diante de Omdurman, as forças do califa Abdullah et-Teâyişî. No dia seguinte entrou-se em Cartum e hasteou-se a bandeira no palácio onde Gordon fora morto treze anos antes. A capital do Estado Mahdista caiu; o califa foi morto, no fim de 1899, numa operação de perseguição. O domínio de facto muda de mãos nesta data — 19 de janeiro de 1899 é o tratado que estabelece o quadro jurídico da administração.", "ae944d9d"]},
"OLAYLAR_EK9:1899-01-19:0":{"b": ["O Tratado do Condomínio — a administração conjunta anglo-egípcia do Sudão", "8033c688"], "d": ["O tratado assinado no Cairo quatro meses depois de Omdurman pôs o Sudão, sob o nome de 'Sudão Anglo-Egípcio', sob a administração conjunta dos dois Estados: as duas bandeiras seriam hasteadas juntas e o governador-geral seria nomeado pelo quediva com o consentimento da Inglaterra. Na prática, a administração estava inteiramente nas mãos dos ingleses. O Estado Otomano, sustentando que os seus direitos sobre o Sudão lhe pertenciam por intermédio do Egito, não foi parte no tratado e não o reconheceu; mas de facto ficou de fora.", "c642933f"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["O desembarque italiano em Tobruk — a primeira ocupação em Trípoli de Barbaria", "44780018"], "d": ["A Itália declarou guerra a 29 de setembro de 1911 e a sua frota bloqueou a costa a 25-26 de setembro. A primeira operação terrestre foi feita a 8 de outubro em Tobruk: a pequena guarnição otomana recuou para o interior e o porto foi ocupado sem combate. Tobruk era o porto otomano mais próximo da fronteira do Egito; a sua queda abriu o flanco oriental de Barca e facilitou a marcha das forças italianas para oeste ao longo da costa.", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["A rendição da cidade de Trípoli aos italianos", "785091ad"], "d": ["Trípoli rendeu-se a 9 de outubro de 1911, depois de três dias de bombardeamento. As forças otomanas, em vez de defender a cidade, preferiram recuar para Aziziye e Garyan e organizar a resistência no interior; esta resistência, em que participaram Enver e Mustafa Kemal Beys, manteve os italianos confinados à faixa costeira até ao fim da guerra. Ou seja, embora a cidade tenha caído, o interior da província permaneceu sob controlo otomano.", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["A perda de Derna com o desembarque italiano", "f014c741"], "d": ["Depois de Tobruk, chegou a vez de Derna, segundo porto de Barca; a cidade foi ocupada a 16 de outubro de 1911. O planalto em redor de Derna era a região onde a confraria Senûsiyye era mais densa, e os mujahidin reunidos com o apelo à jihad do xeique Ahmed Şerîf mantiveram os italianos cercados em redor do porto. A ocupação ficou limitada à cidade e nunca se estendeu ao interior.", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["O desembarque italiano em Benghazi — a perda do centro do sanjaco de Barca", "f9183c40"], "d": ["Benghazi, centro de Barca, foi ocupada a 21 de outubro de 1911, com o quarto e mais importante desembarque na costa. Assim, três semanas depois da declaração de guerra, a Itália detinha todos os grandes portos da província de Trípoli de Barbaria (Trípoli, Tobruk, Derna, Benghazi); mas não conseguiu penetrar no interior de nenhum deles. O resto do ano de guerra passou-se em investidas infrutíferas destes quatro pontos da costa para o interior.", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["O decreto de anexação unilateral da Itália", "cfe3f9c2"], "d": ["A Itália, durante a guerra, promulgou a 5 de novembro de 1911 um decreto declarando que anexava Trípoli de Barbaria e Barca. O Estado Otomano não o reconheceu e a guerra durou mais um ano; a anexação só ganhou validade jurídica com o Tratado de Ouchy de 18 de outubro de 1912. Por isso, o decreto não muda a cor otomana no mapa — a propriedade jurídica está com os otomanos até 1912, e o controlo italiano é mostrado como ocupação tracejada.", "23668758"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Tomada de Köprühisar e preparação da fundação de Yenişehir", "39abff03"], "d": ["Derrubadas as fortalezas de passagem entre Bursa e İznik, lançou-se a base do quartel avançado que sitiaria as duas cidades.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Fundação de Yenişehir", "d3275837"], "d": ["Foi criado o primeiro povoamento-guarnição otomano regular para dirigir os cercos de Bursa e de İznik; Orhan Gazi nasceu aqui.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Primeiro cerco de İznik e conquista de Marmaracık", "cdca2349"], "d": ["İznik foi sitiada pela primeira vez mas não pôde ser tomada (conquista definitiva em 1331); a fortaleza de Marmaracık, nas suas proximidades, foi tomada nesta altura.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Campanha dos contingentes catalães na Anatólia", "4fd940d5"], "d": ["A companhia catalã contratada por Bizâncio para deter o avanço turco obteve êxitos passageiros mas não foi duradoura; com a sua retirada, o avanço dos beyliks de fronteira acelerou.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal torna-se muçulmano e junta-se aos otomanos", "ca0d86e1"], "d": ["Köse Mihal, tekfur de Harmankaya, converteu-se ao Islão e juntou-se a Osman Gazi com a sua fortaleza e os seus homens; tornou-se o primeiro comandante otomano de origem bizantina.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey assume de facto a administração", "6dadbefc"], "d": ["Devido à velhice e à doença de Osman Gazi, a direção e administração de facto do cerco de Bursa e das campanhas passou para o seu filho Orhan Bey (a subida oficial ao trono é em 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-01-01:0":{"b": ["Bloqueio do porto de Mudanya", "9aa4520c"], "d": ["Cortado o porto que abastecia Bursa pelo mar, abriu-se o último ato do longo cerco.", "97d6f814"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Tomada de Mudanya", "0a623368"], "d": ["Com a tomada de Mudanya, porto de Bursa, a ligação da cidade ao mar foi cortada; o cerco de Bursa entrou na fase de estrangulamento.", "c13020d5"]},
"OLAYLAR_EK:1323-01-01:0":{"b": ["Incorporação de Yalova e Karamürsel", "133cb07a"], "d": ["Para completar o cerco de Bursa, foram tomadas as vilas portuárias da costa sul do golfo.", "6588050d"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Conquista de Akyazı e da Ilha de İmralı", "d041b0c8"], "d": ["Foi tomada Akyazı, a norte do Sakarya; com a captura da Ilha de İmralı, os otomanos tornaram-se pela primeira vez vizinhos da Ilha de Mármara.", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["Conquista de Gemlik (Kios) e Armutlu", "682d3bac"], "d": ["Cortada também a última ligação marítima de Bursa, a cidade ficou preparada para a rendição de 1326.", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca tomou Kandıra e arredores", "341bb97e"], "d": ["Akça Koca, um dos beys de fronteira de Orhan Gazi, enquanto fazia incursões à região de İzmit a partir do seu quartel a oeste do lago Sapanca, apoderou-se por volta de 1326 de Kandıra e dos seus arredores. İzmit estava ainda em mãos bizantinas; a cidade só cairia em 1337.", "ed042ad1"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca tomou Aydos e a fortaleza de Samandıra", "ce4daa8a"], "d": ["Após a tomada de Kandıra, Akça Koca, juntamente com Konuralp e Gazi Abdurrahman, tomou a fortaleza de Aydos, nas imediações de Kartal, e depois a fortaleza de Samandıra, a norte dela; a região de Samandıra foi-lhe dada como propriedade. Akça Koca morreu em 1328 perto de Kandıra; o beylik de fronteira da região foi dado ao príncipe Murad.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Aliança otomano-Aydın-Saruhan", "9df6bb74"], "d": ["Os três beyliks agiram em conjunto contra Bizâncio; a armada do Aydınoğlu Umur Bey desgastou Bizâncio numa segunda frente com incursões às costas da Trácia.", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Casamento de Orhan Gazi com Teodora: aliança bizantina", "9b67a590"], "d": ["Orhan Gazi, que apoiava Cantacuzeno na luta pelo trono bizantino, casou com a filha dele, Teodora; esta aliança permitiu às forças otomanas conhecer de perto a Rumélia.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Tomada de Ancara", "49bf1f6d"], "d": ["Ancara, sob administração ahi, passou à administração otomana; abriu-se o caminho da Anatólia central. Outros lugares incorporados na mesma data: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Avanço na Trácia no tempo de Süleyman Paşa: Malkara, İpsala e Tekirdağ", "fb31cf02"], "d": ["Depois de estabelecida a cabeça de ponte em Galípoli, Süleyman Paşa, subindo da península para norte, tomou passo a passo a planície entre a costa do Mármara e a foz do Maritsa. Malkara, İpsala e Rodosçuk (Tekirdağ) formaram assim um corredor ininterrupto ligando Galípoli ao vale do Maritsa. Sem este corredor não se podia marchar sobre Edirne; o avanço, detido pela morte súbita do príncipe em 1357, seria prosseguido por Lala Şahin e Hacı İlbey.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Rapto do príncipe Halil", "b52ac3d7"], "d": ["Halil, filho mais novo de Orhan Gazi, foi raptado por piratas de Foça; a crise do resgate ocupou durante anos as relações otomano-bizantinas.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Corte das vias de socorro de Edirne: fortalezas de Çorlu, Lüleburgaz, Babaeski e Keşan", "8e8ad485"], "d": ["O príncipe Murad, que retomou as operações de conquista depois do salvamento de Halil, enviou os akıncıs até diante de Constantinopla para isolar Edirne de qualquer auxílio exterior. Foram tomadas as fortalezas de Çorlu, Lüleburgaz e Babaeski, na estrada Constantinopla-Edirne, e Keşan, no entroncamento rodoviário da Trácia meridional. A rendição de Edirne veio depois de completado este anel de cerco.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Tomada de Dimetoka — abertura do vale do Maritsa", "b59aee83"], "d": ["Foi tomada Dimetoka, fortaleza-chave do vale do Maritsa; abriu-se assim o caminho da conquista de Edirne. Sem estar completo o corredor que se estende de Galípoli para norte, não era possível marchar sobre Edirne, e por isso a fortaleza vem, na ordem das conquistas da Rumélia, antes de Edirne. A cidade foi durante algum tempo o quartel-general dos sultões na Rumélia. As forças que tomaram Dimetoka puseram em seguida sob controlo toda a região do Maritsa médio, juntamente com pequenas fortalezas como Kuleli Burgaz (Pythion).", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Perda de Galípoli (cruzada de Saboia)", "00e7e415"], "d": ["A armada de Amadeu de Saboia, primo do imperador bizantino, tomou Galípoli e entregou-a a Bizâncio; a cabeça de ponte otomana na Rumélia foi durante dez anos governada a partir da outra margem do estreito. Outros povoamentos perdidos na mesma data: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Batalha de Çirmen — controlo do vale do Maritsa", "cd738d8d"], "d": ["O exército dos beys sérvios foi dispersado num ataque noturno; os beys locais sérvios/búlgaros da Macedónia e dos Ródope começaram, um a um, a pagar tributo aos otomanos — não uma conquista direta, mas o início de uma vaga de vassalização. Na tradição otomana, esta batalha é ainda narrada com o nome de «Sırpsındığı» e com a data de 1364, como o ataque noturno de Hacı İlbey ao exército cruzado que vinha reconquistar Edirne; o TDV indica que essa data é errada e que as duas narrativas pertencem à mesma batalha.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Conquista de Filibe e Eski Zağra", "e780c9ae"], "d": ["Foram tomadas Filibe, a montante do vale do Maritsa, e Eski Zağra, a norte; o czarado búlgaro foi sujeito a tributo. A rota de Tatarpazarcığı e İhtiman, entre Filibe e Sófia, ficou nas mãos dos beys locais vassalizados depois de Çirmen.", "b8131db8"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Bizâncio vassalo: João V no exército de Murad I (consequência da vitória de Çirmen de 1371)", "13ffe568"], "d": ["Segundo o TDV, depois da vitória de Çirmen (Maritsa) de 26 de setembro de 1371, o Império Bizantino reconhecera a soberania otomana e caíra na condição de Estado vassalo, aceitando pagar tributo e servir no exército otomano. O imperador João V, com esta obrigação, juntou-se em 1373 ao exército de Murad I; o seu filho André IV, que deixara então em Constantinopla, revoltou-se contra o pai juntamente com o príncipe Savcı Bey, em Bursa.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Recuperação de Galípoli", "5f96c0a5"], "d": ["André IV, que obtivera o apoio otomano na luta pelo trono bizantino, restituiu Galípoli em troca; a ponte entre a Rumélia e a Anatólia foi restabelecida. Outros lugares incorporados na mesma data: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Dote de Germiyan: incorporação de Kütahya", "d6a6fe61"], "d": ["No casamento de Devletşah Hatun, filha do Germiyanoğlu Süleyman Şah, com Yıldırım Bayezid, Kütahya, Simav, Tavşanlı e Eğrigöz passaram aos otomanos como dote — exemplo clássico de expansão sem guerra. Outros lugares incorporados na mesma data: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Compra da província de Hamîd: incorporação de Isparta", "4a1b6047"], "d": ["O Hamîdoğlu Hüseyin Bey vendeu a Murad I, a dinheiro, uma parte do seu beylik (Akşehir-Beyşehir-Isparta); o resto da província de Hamîd seria anexado por Yıldırım em 1391.", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Conquista de Serez", "d4d28b60"], "d": ["Foi tomada Serez, chave da Macedónia oriental; Salónica entrou no círculo de cerco. A linha Köstendil-Petriç-Nevrokop-Drama, entre Sófia e Serez, não estava ainda diretamente incorporada nesta data; passou sucessivamente a vassala entre os anos 1370 e 1383 e a administração direta depois de 1383.", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Conquista de Sófia", "96d5f01f"], "d": ["Foram postas sob controlo as passagens ocidentais dos Balcãs; como nesta data Serez estava já em poder desde 1383, os territórios da Trácia e da Macedónia formavam um conjunto ininterrupto.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Conquista de Niš", "77f5d632"], "d": ["Com a tomada de Niš, chave do vale do Morava, o despotado sérvio ficou diretamente ameaçado.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Primeira rendição de Salónica", "96010ee9"], "d": ["Após um longo bloqueio, a cidade rendeu-se (será devolvida a Bizâncio em 1403 e conquistada definitivamente em 1430). Outros lugares incorporados na mesma data: Kavala.", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Ahidnâme otomano-genovês — renovação do tratado de 1352", "be11d17a"], "d": ["Com os enviados genoveses vindos de Pera, foi renovado o acordo comercial de 1352 herdado do tempo de Orhan Gazi; foram de novo fixados os impostos entre os dois Estados, o tratamento dos prisioneiros e o comércio livre. Este é considerado o primeiro ahidnâme oficialmente conhecido de amizade e comércio entre os otomanos e os genoveses — não uma aliança militar, mas um acordo inteiramente comercial.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Campanha de Çandarlı Ali Paşa na Bulgária: tomada de Şumnu e Rusçuk", "2781c3a9"], "d": ["As fortalezas do czarado búlgaro ao longo do Danúbio foram recebidas em rendição numa única campanha; não deve ser confundida com a derrota sofrida no mesmo ano em Bileća, na Bósnia — foi um êxito simultâneo numa frente distinta. Tırnova e Vidin eram ainda os últimos centros búlgaros mantidos.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Derrota de Bileća", "89ba0a64"], "d": ["A força de akıncıs que se dirigia à Bósnia foi apanhada numa emboscada em Bileća e aniquilada; este primeiro grande revés balcânico encorajou a aliança que conduziu ao Kosovo.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Anexação dos beyliks da Anatólia ocidental: Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Três beyliks foram incorporados de uma só vez: Manisa, centro dos Saruhanoğulları; Aydın, centro dos Aydınoğulları (incluindo a cidadela superior de Esmirna, mas o porto/cidadela inferior ainda com os Cavaleiros de São João — até 1402); Muğla-Milas, centro dos Menteşeoğulları, incluindo a faixa costeira Datça-Bodrum-Marmaris-Fethiye. As costas do Egeu foram pela primeira vez reunidas numa só mão. Outros lugares incorporados na mesma data: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1391-10-01:0":{"b": ["Começou o primeiro bloqueio de Constantinopla", "4441a9e7"], "d": ["Yıldırım Bayezid manteve Constantinopla sob bloqueio intermitente durante dez anos; a cidade só se salvou graças à aproximação de Tamerlão.", "504fcb33"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Anexação da província de Teke: incorporação de Antalya", "fdbeee5c"], "d": ["A província de Teke, na costa mediterrânica, foi incorporada no território otomano. Os Tekeoğulları são um ramo separado dos Hamîdoğulları: Feleküddin Dündar Bey deixou Antalya, que conquistara, ao seu irmão Yûnus Bey, e por volta de 1321 nascera um beylik distinto. Por isso, Antalya e os seus arredores são mostrados no mapa depois de 1321 com a cor dos Tekeoğulları e não dos Hamîdoğulları. O beylik foi refundado depois da batalha de Ancara e só foi liquidado definitivamente em 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Conquista de Üsküp", "9e5a1af5"], "d": ["Foi tomado o centro da Macedónia do Vardar; Üsküp tornou-se um dos principais centros de fronteira da Rumélia.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Anexação de Kastamonu", "876330ba"], "d": ["O ramo de Kastamonu dos Candaroğulları foi liquidado; o ramo de Sinope continuou como vassalo. Outros lugares incorporados na mesma data: Bartın, Safranbolu.", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Queda de Tırnova — anexação da Bulgária", "ff666977"], "d": ["A capital do czarado búlgaro caiu; a Bulgária passou à administração otomana direta. Outros lugares incorporados na mesma data: Plevne, Lofça.", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["A fortaleza de Lofça (Lovech) passa aos otomanos", "a55e87a0"], "d": ["Lofça, uma das fortalezas do czar búlgaro Ivan Šišman, foi incorporada no território otomano com as outras províncias de Šišman na campanha de 1393 em que Tırnova caiu. A fonte não é categórica: «supõe-se» que a conquista foi neste ano.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Incorporação da Dobruja", "478e36f2"], "d": ["Foram incorporados os territórios da Dobruja, que se estendem até ao delta do Danúbio. Outros lugares incorporados na mesma data: Silistre, Köstence.", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Descida à Tessália", "8bec60dd"], "d": ["A planície da Tessália, com centro em Yenişehir (Larissa), foi posta sob administração otomana. Outros lugares incorporados na mesma data: Tırhala, İzdin (Lamia).", "d9f2128c"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Conquista de Niğbolu", "b9791717"], "d": ["Após a batalha de Rovine de 1395 contra os valáquios, Yıldırım Bayezid tomou a fortaleza de Niğbolu, nas margens do Danúbio; algumas crónicas búlgaras anónimas indicam que a conquista se deu em 3 de junho de 1395. A data da conquista não é única nas fontes: o artigo Niğbolu Savaşı da TDV İslâm Ansiklopedisi escreve que Bayezid tomou Silistre e Niğbolu numa campanha do Danúbio em 1394. A fortaleza seria sitiada na célebre Cruzada de 1396, mas não cairia. Outros lugares incorporados na mesma data: Ohri.", "bc450a9f"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Batalha de Rovine — campanha da Valáquia", "343ae7a9"], "d": ["Após a batalha sangrenta e de resultado discutido com o voivoda da Valáquia, Mircea, a Valáquia aceitou pagar tributo aos otomanos; estabeleceu-se a ordem de vassalagem a norte do Danúbio.", "dd69200f"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Construção de Anadolu Hisarı", "aa259b00"], "d": ["Para apoiar o bloqueio de Constantinopla, foi construída na margem anatólica do Bósforo a Güzelcehisar (Anadolu Hisarı) — o primeiro passo duradouro do controlo do estreito.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Anexação de Vidin", "ee1ae44b"], "d": ["Após a vitória de Niğbolu, foi também anexado Vidin, o último principado búlgaro.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Primeira anexação de Karaman", "3cf07876"], "d": ["Com a vitória de Akçay, o território dos Karamanoğlu foi pela primeira vez incorporado nos otomanos (será refundado durante o Fetret).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Incorporação das costas de Canik: Samsun", "af9c40fa"], "d": ["No vazio criado pela captura de Kadı Burhâneddin pelo Ak Koyunlu Karayülük Osman Bey, Yıldırım Bayezid pôs primeiro sob administração otomana a região de Canik, na costa do mar Negro. Samsun e os seus arredores tornaram-se assim o primeiro porto do mar Negro da dinastia. A linha interior Sivas-Tokat-Kayseri seria incorporada duas semanas depois, com a dissolução de facto do Estado de Kadı Burhâneddin.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Tomada de Malatya", "7cb6ae16"], "d": ["Foi tomada Malatya, na fronteira mameluca — um dos passos que aumentaram a tensão com Tamerlão.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Tamerlão tomou Malatya e entregou-a a Karayülük Osman — quando Tamerlão se retirou, os Dulkadıroğulları recuperaram-na", "ad2ce7d8"], "d": ["Yıldırım Bayezid tinha regressado a Bursa, deixando Malatya, que tomara em 1399, ao Dulkadıroğlu Nasreddin Mehmed. Tamerlão, que entrou na Anatólia em 1400, tomou primeiro Sivas e Elbistan e depois Malatya; a cidade e os seus arredores foram saqueados e a sua administração foi entregue a Karayülük Osman, que estava ao lado de Tamerlão. Quando Tamerlão deixou a região, os Dulkadıroğulları voltaram a dominar Malatya; o domínio otomano terminou assim antes de Ancara.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Tratado de Süleyman Çelebi com Bizâncio: restituição de Salónica", "cc503cc2"], "d": ["Süleyman Çelebi, que dominava a Rumélia durante o Fetret, chegando a acordo com Bizâncio e os Estados latinos, abandonou a Bizâncio Salónica e as costas do mar Negro até Misivri (TDV fetret-devri: Tratado de Galípoli, fevereiro de 1403) — no mapa, İğneada, Rezve e Ahtapolu passam a Bizâncio; no mapa, Salónica sai dos otomanos nesta data.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Derrota naval de Galípoli (Veneza)", "b71d4d68"], "d": ["A armada veneziana infligiu uma pesada derrota à armada otomana diante de Galípoli; foi um acontecimento que mostrou os limites da marinha otomana primitiva.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Revolta do Falso Mustafa", "0ec43138"], "d": ["Mustafa Çelebi, que afirmava ser filho de Yıldırım, proclamou-se sultão na Rumélia com apoio bizantino; Murad II reprimiu a revolta em 1422 e mandou executar o rival.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Cerco de Constantinopla por Murad II", "4b9d9fba"], "d": ["Em resposta ao apoio de Bizâncio ao Falso Mustafa, Murad II sitiou Constantinopla; o cerco foi levantado quando o seu irmão Küçük Mustafa foi sublevado na Anatólia.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Cedência de Salónica a Veneza", "bfa6c4a0"], "d": ["O governador bizantino, sob pressão otomana, cedeu a cidade a Veneza; começou a disputa otomano-veneziana que duraria sete anos.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Nova anexação dos beyliks da Anatólia ocidental: Menteşe e Aydın", "aca30a48"], "d": ["Os dois beyliks do Egeu, refundados durante o Fetret Devri, foram definitivamente incorporados no território otomano no tempo de Murad II. Segundo o artigo Menteşeoğulları do TDV, Murad II tomou a província de Menteşe em 827 (1424) e mandou prender os dois irmãos que estavam à frente do beylik. Segundo o artigo Aydınoğulları, o beylerbei da Anatólia Hamza Bey mandou capturar Cüneyd Bey, que de novo se recusara a obedecer, e executou-o com a sua família (829/1425-26), e a província de Aydın passou aos otomanos. Os Cavaleiros de São João, que detinham desde 1344 a cidadela portuária de Esmirna, tinham-na perdido para Tamerlão em 1402, e a região voltara ao controlo dos Aydınoğlu; com esta anexação, ela foi também incorporada nos otomanos. A província de Teke (Antalya) não é objeto deste artigo: os Tekeoğulları tinham sido liquidados à parte em 1423. Germiyan seria incorporada por testamento em 1429.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Anexação de Germiyan por testamento", "9eb86b77"], "d": ["O bey de Germiyan, Yakub II, que morreu sem filhos, legou o seu país por testamento aos otomanos — o exemplo de anexação sem guerra que entrou nos manuais. Outros lugares incorporados na mesma data: Karahisâr-ı Sâhib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Conquista definitiva de Salónica", "bc021768"], "d": ["A cidade, sob administração veneziana, foi tomada de assalto; o segundo grande porto da Rumélia tornou-se definitivamente otomano. Outros lugares incorporados na mesma data: Kesendire (Kassandra).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Rendição de Ioannina", "ee45cb52"], "d": ["Ioannina, centro do Épiro, rendeu-se por tratado.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Primeira tomada de Semendire", "c11ca17d"], "d": ["Com um cerco de três meses foi tomada a capital do despotado sérvio e a Sérvia foi anexada pela primeira vez (será restituída com o Tratado de Edirne-Szeged de 1444).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Cerco de Belgrado (malogrado)", "3e05f425"], "d": ["O primeiro grande cerco de Belgrado, de seis meses, não deu resultado; a fortaleza permaneceu durante oitenta anos como fecho do avanço otomano.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Desastre de Zlatica — 'Longa Campanha'", "97df1466"], "d": ["O exército que Hunyadi fez entrar nos Balcãs em pleno inverno passou Niš e Sófia e chegou a Zlatica; a defesa otomana resistiu com dificuldade. Este ar de derrota trouxe à mesa a paz de Edirne-Szeged.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Tratado de Edirne-Szeged", "0aa4e0de"], "d": ["Paz de dez anos: o despotado sérvio foi restituído, o Danúbio foi aceite como fronteira. A rutura do tratado, em poucos meses, por instigação papal, conduziu ao desastre de Varna.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Restituição de Semendire e das fortalezas sérvias à Sérvia", "cda3cf9e"], "d": ["A disposição do Tratado de Edirne-Szeged foi posta em execução: Murad II devolveu a Đurađ Branković, em 15 de agosto de 1444, Semendire com as suas vinte e quatro fortalezas importantes e os outros territórios sérvios ocupados (TDV semendire); também Niš (TDV nis), Alacahisar (TDV alacahisar), Şehirköy (TDV sehirkoy) e Priština (TDV pristine) foram deixadas aos sérvios. Vidin não entrou na restituição por não ser território sérvio — é essa a origem da perda territorial a noroeste que se vê no mapa por volta da vitória de Varna; poucos meses depois, com o desastre de Varna, o tratado ficará de qualquer modo inválido.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Concluída Rumeli Hisarı — 'Boğazkesen'", "480e8a76"], "d": ["Com a fortaleza concluída, segundo as fontes, numa construção extraordinariamente rápida de quatro a cinco meses, o controlo do Bósforo passou inteiramente aos otomanos; fechou-se o caminho de socorro do mar Negro a Constantinopla. É considerado o primeiro passo efetivo do cerco.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Começou o cerco de Constantinopla", "8af50742"], "d": ["O exército instalou-se diante das muralhas; no cerco, que duraria 54 dias, os canhões gigantescos foram pela primeira vez usados de forma sistemática contra as muralhas de uma capital.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Navios descidos por terra ao Corno de Ouro", "4f2ba07c"], "d": ["Cerca de 70 navios da armada, que não podia entrar no Corno de Ouro fechado por uma corrente, foram arrastados sobre calhas untadas pelas colinas de Gálata e descidos numa noite ao Corno de Ouro; a defesa ficou dividida em duas frentes.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Conquista de Atenas", "4f0f1bb2"], "d": ["O Ducado de Atenas chegou ao fim; o estandarte otomano foi hasteado na Acrópole. Outros lugares incorporados na mesma data: İstefe (Tebas), Livadya.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Anexação da Sérvia (queda de Smederevo)", "75fd0a62"], "d": ["Smederevo, capital do despotado sérvio, rendeu-se; a Sérvia tornou-se um sanjaco otomano.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Conquista da Moreia", "7d5a3c18"], "d": ["O despotado da Moreia foi liquidado; a península (exceto as fortalezas venezianas) passou à administração otomana.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Incorporação de Sinope", "e03c2739"], "d": ["O Candaroğlu entregou Sinope sem combate; abriu-se o caminho da campanha de Trebizonda. Outros lugares incorporados na mesma data: Kastamonu, Bartın, Safranbolu.", "4fa22834"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Destruição do Reino da Bósnia — campanha da Bósnia do Conquistador", "5362e3f2"], "d": ["Quando o último rei bósnio, Stjepan Tomašević (1461-1463), confiando no apoio ocidental, recusou pagar o tributo, foi considerado como tendo deixado de ser soberano vassalo, e o exército sob a direção do sultão Maomé II, o Conquistador, liquidou o Reino da Bósnia numa só campanha. O rei foi capturado e executado, o reino desapareceu e na região foi criado o sanjaco da Bósnia. Porém, a destruição do reino não é a mesma coisa que a conquista da Bósnia. A administração otomana existia na planície há já quinze anos — Hodidjed e a planície de Saray tinham sido tomadas em 1448, e o beylik de fronteira de Îsâ Bey fora estabelecido no meio do reino. A conquista não acabou também em 1463: Foča em 1465, Livno em 1469, o Ducado da Herzegovina em 1483, o banado de Srebrenik em 1512, e Jajce e Banja Luka, no norte, só puderam ser tomadas em 1528, depois de Mohács — os húngaros tinham constituído, depois de 1463, um banado que se manteve sessenta e cinco anos no norte da Bósnia. O lugar que mudou diretamente de mãos nesta data é Travnik; Jajce, por seu lado, passou nesta data não aos otomanos, mas à Hungria.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Anexação definitiva de Karaman", "f1dcecaa"], "d": ["Os territórios centrais dos Karamanoğulları foram definitivamente incorporados; as disputas internas prolongaram-se até aos anos 1470. Outros lugares incorporados na mesma data: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Conquista de Negroponte", "5c97daf3"], "d": ["Caiu Negroponte, principal base de Veneza no Egeu.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Anexação de Alanya, Anamur e Silifke (İçel)", "a0b9d461"], "d": ["A faixa costeira de İçel, ligada aos Karamanoğulları (todo o Mediterrâneo entre Antalya e Mersin), foi incorporada pela campanha naval de Gedik Ahmed Paşa; Alanya era importante pelo seu estaleiro estratégico herdado do período seljúcida.", "8302df58"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Tratado de Istambul — Albânia e Shkodër", "b09652f7"], "d": ["Terminou a guerra otomano-veneziana de 16 anos; Shkodër e as costas da Albânia ficaram com os otomanos. Outros lugares incorporados na mesma data: Limni, Sisam, Bozbaba (Ay Strati).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Desembarque em Otranto", "7916b89d"], "d": ["As forças otomanas que desembarcaram na costa da Calábria sitiaram e tomaram a fortaleza de Otranto; como a cidade foi tomada de assalto, parte dos notáveis que resistiram foi executada e parte foi feita prisioneira. A tradição da Igreja recorda os mortos como os cerca de 800 'mártires de Otranto'; o TDV atribui o exagero deste número à propaganda eclesiástica. Apenas a fortaleza na ponta da península de Salento e a sua estreita vizinhança foram mantidas; o resto do território do Reino de Nápoles na linha Taranto-Brindisi-Lecce não se perdeu — esta cabeça de ponte aberta para a Itália duraria um ano.", "f60d286a"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Evacuação de Otranto", "37371bb0"], "d": ["Com a morte de Maomé II, o Conquistador (3 de maio de 1481), a guarnição de Otranto, sem esperança de novos reforços, evacuou a fortaleza por acordo perante o cerco do herdeiro de Nápoles, Afonso; a única cabeça de ponte otomana na Itália perdeu-se assim um ano depois.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Conquista de Modon e Koron", "38b608c4"], "d": ["Foram tomados Modon e Koron, os 'dois olhos' de Veneza na Moreia.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Conquista de Durrës", "1f231b98"], "d": ["Durante a guerra otomano-veneziana de 1499-1503, as forças sob o comando de Mehmed Bey tomaram Durrës, o último grande porto albanês de Veneza no Adriático. Depois de Shkodër (1479) e de Vlorë (1417), com esta conquista a faixa costeira da Albânia passou inteiramente ao controlo otomano.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Incorporação da Anatólia oriental", "e0cb8f8f"], "d": ["Depois de Çaldıran, Diyarbakır e os seus arredores foram incorporados; os beyliks curdos foram ligados aos otomanos por intermédio de İdrîs-i Bitlisî.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Conquista da fortaleza de Varadin (Petrovaradin)", "abf392a5"], "d": ["O exército que partira para a campanha de Mohács passou de Belgrado para o território húngaro; foram tomados primeiro os arrabaldes de Varadin e, após um cerco de catorze dias, caiu também a fortaleza. O Legislador ordenou que as aldeias do caminho não fossem queimadas, porque estas eram já consideradas território otomano.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Rendição de Buda depois de Mohács — dois reis para o trono húngaro", "9d3568a0"], "d": ["As chaves da cidade foram apresentadas ao sultão em 11 de setembro de 1526 ao exército otomano que, depois da vitória de Mohács, marchava sobre Buda; contudo, o Legislador não manteve Buda e retirou o seu exército. Na Hungria, que ficou sem rei, os nobres elegeram dois reis distintos: János Szapolyai em 10 de novembro de 1526 e o Habsburgo Fernando I em 17 de dezembro de 1526. Fernando tomou Buda em agosto de 1527. A instalação de Szapolyai em Buda como rei sob a proteção otomana far-se-á com a campanha de 1529 (ver o item de 1529), e a administração otomana direta será estabelecida em 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai eleito rei da Hungria — os otomanos reconheceram o seu reino sob condição de vassalagem", "32bc6baf"], "d": ["Para o trono húngaro, vago pela morte do rei em Mohács, uma parte da nobreza elegeu o voivoda da Transilvânia, János Szapolyai; Szapolyai foi coroado em Székesfehérvár. Os otomanos, que tinham evacuado Buda, reconheceram o reino de Szapolyai sob condição de que lhes fosse vassalo, para manter a região como zona-tampão. No mapa, os lugares ligados a Szapolyai aparecem, a partir desta data, como vassalos dos otomanos.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Fernando I proclamado rei da Hungria — Hungria ocidental e setentrional para a coroa dos Habsburgos", "b3910a2f"], "d": ["O arquiduque habsburgo Fernando, com base no casamento da sua irmã com Luís II, reivindicou o trono húngaro e foi proclamado rei por uma parte dos nobres. A Hungria ficou assim dividida entre dois reis; as suas partes ocidental e setentrional reconheceram Fernando. Os nobres croatas elegeram-no também no início de 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Disputa dos dois reis: Esztergom sob a proteção dos Habsburgos, Szeged com Szapolyai", "da92dee5"], "d": ["Esztergom, que mudara de mãos entre os dois reis desde 1526, passou à proteção dos Habsburgos depois de o arcebispo ter seguido para o norte com o arquivo e o tesouro. Desde o mesmo ano e até 1541, Szeged ficou sob a soberania de Szapolyai.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["A população de Pécs passou para o lado de Szapolyai", "3fc4e7f2"], "d": ["Pécs, que obtivera privilégios de Fernando em 1528, passou pouco depois para o lado de Szapolyai; o rei János permaneceu algum tempo na cidade em 1533. Com a queda de Buda em 1541, a cidade voltou novamente para o lado de Fernando.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Conquista de Trípoli", "8c659986"], "d": ["Trípoli foi tomada aos cavaleiros de São João; a costa central do Norte de África tornou-se otomana. Outros lugares incorporados na mesma data: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Conquista de Timișoara", "e9fd4995"], "d": ["Foi tomada a região do Banato e criado o Beylerbeylik de Timișoara.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Conquista definitiva de Tunes", "7bbd11bc"], "d": ["Tunes, sob controlo espanhol-hafsida, passou definitivamente à administração otomana; a linha do Norte de África ficou completa. Outros lugares incorporados na mesma data: Kayrevan, Gabes, Sfaks.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Conquista de Kanizsa", "0c7b6aa3"], "d": ["Kanizsa foi tomada na Longa Guerra; no ano seguinte a defesa de Tiryâki Hasan Paşa tornou-se lendária.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Começou a campanha de Uyvar — Fâzıl Ahmed Paşa marchou de Edirne contra a Áustria", "306a86db"], "d": ["Quando a Áustria atacou a Transilvânia e tomou as fortalezas de Székelyhíd e Kolozsvár, Istambul decidiu fazer campanha contra os Habsburgos. O grão-vizir Köprülüzâde Fâzıl Ahmed Paşa partiu de Edirne em 13 de abril de 1663. Em Belgrado chegou o pedido de paz da Áustria, mas em duas conversações em Osijek as condições otomanas foram rejeitadas. Na consulta em Buda, o objetivo foi também fixado em Uyvar.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Conquista de Uyvar", "ce289470"], "d": ["Foi tomada Uyvar, fortaleza-chave da Hungria setentrional; a expressão 'forte como um turco diante de Uyvar' passou às línguas europeias. Depois de Uyvar, também Nitra e Léva se renderam com breve resistência; ambas foram recuperadas por De Souches na primavera de 1664.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Recuperação da Moreia", "9b6460f1"], "d": ["A Moreia, deixada a Veneza em Karlowitz, foi recuperada numa só campanha. Outros lugares incorporados na mesma data: Balyabadra (Patras), İnebahtı.", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Segunda perda de Belgrado — cerco do príncipe Eugénio", "6a194354"], "d": ["Depois do desastre de Varadin e da perda de Timișoara, o príncipe Eugénio sitiou Belgrado; quando o exército de socorro que veio salvar a cidade foi também desbaratado, a fortaleza rendeu-se. A cidade, que fora recuperada em 1690 depois de Karlowitz, perdeu-se assim de novo e a linha de defesa do Danúbio ruiu. Belgrado só poderia ser recuperada vinte e dois anos depois, com o Tratado de Belgrado de 1739. Outros povoamentos perdidos na mesma data: Semendire.", "3bf3f600"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Queda de Özi", "90a67a6c"], "d": ["Özi, fortaleza-chave a norte do mar Negro, passou para as mãos da Rússia num assalto sangrento; a população da cidade foi passada a fio de espada.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Tratado de Bucareste — perda da Bessarábia", "932da4d6"], "d": ["Com o tratado que pôs fim à guerra russa de 1806-1812, o território a leste do Prut (Bessarábia) foi deixado à Rússia. Outros povoamentos perdidos na mesma data: Akkirman, Kili, Hotin, Bender, İsmail.", "a4c3a1fb"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Tratado de Edirne", "b3a8fe4c"], "d": ["No fim da guerra em que o exército russo entrou em Edirne, perdeu-se o delta do Danúbio; a autonomia/independência da Grécia foi reconhecida de facto. Outros povoamentos perdidos na mesma data: İbrail, Anapa, Ahıska. Embora o tratado tenha devolvido território, não pôs imediatamente fim à ocupação: a Valáquia-Moldávia e Silistre permaneceram, como penhor, sob administração russa até ao pagamento da indemnização de guerra — é por isso que estes lugares aparecem no mapa como ocupados também depois de 1829.", "d09a34fb"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Édito de autonomia para a Sérvia — knezado hereditário e condição da guarnição", "6a5d901d"], "d": ["O hatt-ı hümâyun emitido em conformidade com a disposição do Tratado de Edirne relativa à Sérvia reconheceu Miloš Obrenović como knez hereditário e fez da Sérvia um principado autónomo, livre nos assuntos internos e ligado externamente aos otomanos. Disposições: o knezado passaria de pai para filho, o imposto anual seria pago em montante fixo, a assembleia sérvia estabeleceria a sua administração interna, a Igreja seria autónoma; em contrapartida, permaneceriam guarnições otomanas nas fortalezas de Belgrado, Semendire, Šabac, Böğürdelen e Fethülislâm. Esta estrutura dual durou até à retirada das guarnições em 1867. No mapa, a cidade de Belgrado integra-se nesta data na Sérvia autónoma; a fortaleza de Kalemegdan é mostrada com guarnição otomana até 1867.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Chipre deixado à administração inglesa", "423da3ee"], "d": ["Em troca de uma aliança contra a ameaça russa, a administração de Chipre foi transferida para a Inglaterra; juridicamente permaneceu território otomano. Outros povoamentos perdidos na mesma data: Lefkoşa, Magosa.", "04ce99ee"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Cedência da Tessália à Grécia", "ac614d24"], "d": ["Em conformidade com as decisões do Congresso de Berlim, a Tessália e os arredores de Narda foram cedidos à Grécia. Outros povoamentos perdidos na mesma data: Arta, Yenişehir (Larissa), Tırhala, İzdin (Lamia).", "850edaa2"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Incorporação da Rumélia Oriental na Bulgária", "ee43f137"], "d": ["A província autónoma da Rumélia Oriental foi ligada à Bulgária por um golpe; a Sublime Porta aceitou o facto consumado.", "41e57063"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Batalha de Domokos", "9c6f29a5"], "d": ["Na Guerra Otomano-Grega de 1897, o exército alcançou uma vitória decisiva em Domokos; por pressão diplomática, os ganhos territoriais ficaram limitados.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Autonomia de Creta", "2e764881"], "d": ["Apesar de a Guerra Otomano-Grega ter terminado com vitória otomana, a Inglaterra, a Rússia, a França e a Itália proclamaram em 18 de dezembro de 1897 a autonomia de Creta; a ilha seria uma província neutra e autónoma sob soberania otomana. Depois de 6 de novembro de 1898, a bandeira turca deixou de ser hasteada em Candia e em Kissamos; com a entrada em funções, em 22 de dezembro de 1898, do príncipe George, filho do rei grego, como alto-comissário, Creta saiu de facto da administração otomana (separou-se oficialmente em 1913). Outros povoamentos perdidos na mesma data: Kandiye (Girit), Hanya.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Independência da Bulgária e anexação da Bósnia", "393feaa4"], "d": ["Na confusão do período constitucional, a Bulgária declarou a sua independência e a Áustria-Hungria anexou a Bósnia-Herzegovina.", "6b7e2450"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Recuperação de Edirne", "536e5599"], "d": ["Na II Guerra dos Balcãs, o exército atravessou o Maritsa e recuperou Edirne sem combate. Outros lugares incorporados na mesma data: Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Vitória de Kut al-Amara", "98b972bc"], "d": ["A divisão inglesa sitiada em Kut rendeu-se com o seu comandante e 13 mil soldados — uma das maiores vitórias otomanas da Primeira Guerra Mundial.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Perda de Bagdade", "2c18a816"], "d": ["A Bagdade otomana de 383 anos passou ao exército inglês. Outros povoamentos perdidos na mesma data: Kerbelâ.", "4add66da"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Perda de Jerusalém", "94067617"], "d": ["A Jerusalém otomana de 401 anos foi entregue sem poder ser defendida.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Perda de Damasco", "ed177b68"], "d": ["Com o colapso da frente da Palestina, Damasco foi evacuada; o domínio otomano de quatro séculos na Síria terminou. Outros povoamentos perdidos na mesma data: Hama, Humus.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Rendição de Medina", "76b505f6"], "d": ["Setenta e dois dias depois do armistício, a resistência de Fahreddin Paşa, o 'Tigre do Deserto', terminou por vontade do sultão; a última unidade otomana no Hejaz depôs as armas.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Ocupação de Esmirna", "e32e5e77"], "d": ["O exército grego desembarcou em Esmirna; a resistência, iniciada com o primeiro tiro, acendeu o rastilho da Luta Nacional. Aydın foi ocupada em 27 de maio de 1919 (item separado).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Ocupação oficial de Istambul", "a8e98ada"], "d": ["As forças da Entente ocuparam oficialmente Istambul e o Meclis-i Meb'ûsan foi dissolvido; os deputados dirigiram-se a Ancara.", "09ed005b"]},
"OLAYLAR_EK:1921-10-13:0":{"b": ["Tratado de Kars", "bb32d4e0"], "d": ["Entre a TBMM e as repúblicas do Cáucaso foi traçada a fronteira oriental tal como é hoje.", "fe736259"]},
"OLAYLAR_H7_ASAMA:1529-05-10:0":{"b": ["Partida do Legislador para a campanha de Viena — a guerra com os Habsburgos recomeçou", "f7afd2a9"], "d": ["Depois de Mohács, o trono húngaro tinha sido dividido em dois; Fernando tomara Buda em 1527 e expulsara Szapolyai da capital. O sultão partiu em campanha pela quarta vez para apoiar Szapolyai e deter o avanço dos Habsburgos; antes da campanha, deram-se ao grão-vizir İbrâhim Paşa o título de serasker e o beilerbeilique de Rumélia, e todo o planeamento foi feito com ele. Ao longo do caminho, chuvas violentas atrasaram o avanço do exército; a campanha prosseguiu com a tomada de Buda e a sua entrega a Szapolyai e com o cerco de Viena.", "4d80633a"]},
"OLAYLAR_H7_ASAMA:1562-05-05:0":{"b": ["Renovação da paz com os Habsburgos — fim da guerra da Transilvânia e de Timișoara", "97071975"], "d": ["A guerra iniciada em 1551 com a passagem da Transilvânia para Fernando e que prosseguiu com campanhas como a conquista de Timișoara e o cerco de Eğri terminou com a decisão de continuar a paz com os Habsburgos. O acordo renovava reciprocamente os compromissos antigos das duas partes; mas não trouxe solução para os distúrbios nas zonas de fronteira e, depois da morte de Fernando em 1564, os acontecimentos na Transilvânia voltaram a aumentar.", "04cfeca8"]},
"OLAYLAR_H7_ASAMA:1566-05-01:0":{"b": ["A última campanha do Legislador — partida de Istambul com Sigetvar e Eğri como objetivos", "31277d21"], "d": ["Depois da morte de Fernando em 1564 e da subida de Maximiliano II ao trono, os confrontos na fronteira da Transilvânia tinham aumentado. Na campanha que o idoso sultão planeou com Sokullu Mehmed Paşa, os objetivos seriam as fortalezas de Sigetvar e Eğri, e o imperador também seria intimidado. Depois de rezar no Túmulo de Eyüp Sultan, deixou Istambul com grande cerimónia; chegou a Edirne em 15 de maio e, no quinquagésimo dia da sua partida, alcançou Belgrado. Foi a sua última saída da capital, que não voltaria a ver.", "c601608a"]},
"OLAYLAR_H7_ASAMA:1568-02-17:0":{"b": ["Tratado de Edirne — fim do estado de guerra com os Habsburgos", "d08883e3"], "d": ["Na presença de Selim II, que invernava em Edirne depois da campanha de Sigetvar, encontravam-se embaixadores habsburgos, safávidas, polacos, franceses e venezianos. Decidiu-se que a paz com os safávidas continuaria; foi assinado o tratado que pôs fim ao estado de guerra com os Habsburgos. Nestes assuntos foi grande a influência do grão-vizir Sokullu Mehmed Paşa.", "27b65c0e"]},
"OLAYLAR_H7_ASAMA:1578-01-02:0":{"b": ["Decisão da campanha do Irão — dois serdares nomeados contra os safávidas abalados pela morte de Tahmasp", "1f09b186"], "d": ["Com o envenenamento do xá Tahmasp I em 1576, no termo das disputas entre a dinastia e os dignitários do Estado, os safávidas tinham sido arrastados para uma grande confusão; isto determinou a direção da campanha a abrir. Lala Mustafa Paşa foi encarregado de entrar no Irão por Erzurum e Koca Sinan Paşa por Bagdade. Quando a rivalidade entre os dois vizires aumentou, Sokullu interveio: Sinan Paşa foi afastado e Lala Mustafa Paşa foi encarregado da conquista de Şirvan através da Geórgia. Esta decisão é a abertura da guerra otomano-safávida de 1578-1590.", "3157145f"]},
"OLAYLAR_H7_ASAMA:1604-06-15:0":{"b": ["Cigalazâde Sinan Paşa partiu para a campanha do Irão", "1e90763e"], "d": ["Enquanto prosseguia a guerra em duas frentes com o Irão e a Áustria, o xá Abbas tinha sitiado e tomado Revan, entrara em Kars, mas só conseguira ser detido diante de Ahıska. Cigalazâde Sinan Paşa, nomeado serdar do Oriente, partiu de Istambul com atraso e chegou diante de Kars em 8 de novembro. Embora a situação fosse favorável, não marchou contra o xá e invernou em Van; com o ataque do xá, passou a Erzurum; perdeu-se uma estação de campanha.", "d155e6f3"]},
"OLAYLAR_H7_ASAMA:1605-11-06:0":{"b": ["Desastre de Cigalazâde Sinan Paşa perto do lago Urmia (Sûfiyân)", "7438fec4"], "d": ["A situação de Sinan Paşa, que marchava na estação de campanha de 1605 para retomar Tabriz, foi abalada quando o beilerbei de Erzurum, Köse Sefer Paşa, agiu separado do exército principal e foi feito prisioneiro. O ataque súbito do xá Abbas infligiu uma pesada derrota ao exército nas imediações do lago Urmia; Sinan Paşa recuou primeiro para Van e depois para Diyarbekir. O facto de ter mandado executar, por ter chegado tarde ao socorro, o beilerbei de Alepo, Canbolatoğlu Hüseyin Paşa, acendeu na Anatólia uma grande revolta; depois da morte de Sinan Paşa, o xá Abbas tomou Gence, Şirvan e Şamahı.", "8e130829"]},
"OLAYLAR_H7_ASAMA:1610-03-26:0":{"b": ["Campanha de Kuyucu Murad Paşa a Tabriz — não houve confronto em Acıçay", "3c0a0a5d"], "d": ["O grão-vizir Kuyucu Murad Paşa, que reprimira as revoltas celâlîs e assegurara a calma na Anatólia, marchou por Erzurum, Hasankale, Çaldıran e Hoy contra o xá Abbas, que se soubera estar à espera em Tabriz. Os dois exércitos ficaram frente a frente no lugar de Acıçay, a norte de Tabriz, mas não houve combate; a correspondência prosseguiu. Com a aproximação do inverno e a escassez de munições e víveres, o paxá recuou por Ahlat, Van e Bitlis para Diyarbekir e morreu aí, no verão seguinte, quando preparava nova campanha (5 de agosto de 1611).", "289fa3b6"]},
"OLAYLAR_H7_ASAMA:1615-04-23:0":{"b": ["A guerra otomano-safávida recomeçou — o grão-vizir Öküz Mehmed Paşa partiu para a campanha do Oriente", "ef32fa31"], "d": ["Como depois do Tratado de Nasuh Paşa de 1612 não chegavam notícias de İncili Mustafa Çavuş, enviado como embaixador ao Irão, o grão-vizir Mehmed Paşa foi encarregado da campanha do Oriente e, completados os preparativos, passou a Üsküdar. Quando ia partir, chegou a notícia de que İncili Çavuş e o embaixador iraniano Burun Kāsım Han tinham chegado a Van com um acordo e presentes, mas a campanha não foi adiada. O grão-vizir passou o inverno em Alepo.", "5c279a1a"]},
"OLAYLAR_H7_ASAMA:1616-09-12:0":{"b": ["Cerco de Revan — levantado sem resultado ao fim de cinquenta e cinco dias", "64a4ecb6"], "d": ["O grão-vizir, que partira de Alepo em abril de 1616 com um grande exército, chegou diante de Revan pela estrada de Erzurum-Kars. Por se pensar que a fortaleza se renderia facilmente, não tinham sido trazidos canhões pesados; o cerco durou cinquenta e cinco dias sem material. Com a morte em combate do aga dos janízaros Muslu Ağa e de Tekeli Mehmed Paşa, a relutância dos soldados e o avanço da estação, o cerco foi levantado e o exército recuou para Erzurum. Mehmed Paşa foi deposto em novembro de 1616 e Halil Paşa veio no seu lugar.", "823b20af"]},
"OLAYLAR_H7_ASAMA:1618-09-10:0":{"b": ["Desastre de Serav (Pul-i Şikeste) — campanha de Halil Paşa no Irão", "d323ed03"], "d": ["Halil Paşa, que se tornou serdar no lugar de Öküz Mehmed Paşa, marchou de novo contra o Irão em 1618. A batalha travada no lugar de Pul-i Şikeste, entre Tabriz e Erdebil, terminou com a derrota do exército otomano. Depois deste desastre, nas fontes também chamado Batalha de Serav, foi assinado nesse mesmo mês o Tratado de Serav.", "f2c187de"]},
"OLAYLAR_H7_ASAMA:1625-11-13:0":{"b": ["Cerco de Bagdade por Hâfız Ahmed Paşa — durou sete meses e vinte dias, sem resultado", "764acb0a"], "d": ["Os otomanos, que tinham perdido Bagdade em 1623, marcharam para a retomar sob o comando do grão-vizir e serdar Hâfız Ahmed Paşa. Como no conselho reunido em Kerkük a proposta de ocupar primeiro os desfiladeiros não foi aceite, o exército sitiou diretamente Bagdade. O paxá entrava pessoalmente nas trincheiras; embora se tenha entrado na cidade por uma mina rebentada no septuagésimo segundo dia, os soldados foram repelidos. Quando, em março de 1626, o xá Abbas veio em socorro com 30.000 homens, o exército ficou entre dois fogos; no ataque do xá em 7 de junho sofreram-se pesadas perdas. Esgotados os víveres e dizimado o exército pelo calor e pela febre, o cerco foi levantado e o exército recuou para Diyarbekir.", "350e3f52"]},
"OLAYLAR_H7_ASAMA:1630-10-06:0":{"b": ["Cerco de Bagdade por Hüsrev Paşa — levantado ao fim de trinta e nove dias", "18de5581"], "d": ["O grão-vizir Hüsrev Paşa, que depois da vitória de Mihriban (5 de maio de 1630) entrou em Hamadã e a incendiou e destruiu, em vez de marchar sobre Qazvin voltou-se para Bagdade, o objetivo principal, por decisão do conselho de guerra reunido em Dergezîn. O exército, que chegou aos arredores de Bagdade no início de agosto, sitiou a cidade em 6 de outubro. Na surtida da guarnição iraniana em 26 de outubro e no ataque geral de 9 de novembro sofreram-se grandes perdas; também este segundo cerco, depois da perda de Bagdade, foi levantado sem resultado. O exército recuou para Mossul.", "4b3ed1a0"]},
"OLAYLAR_H7_ASAMA:1700-01-01:0":{"b": ["İnebahtı foi devolvida aos otomanos em conformidade com Karlowitz", "9ca4f9dd"], "d": ["İnebahtı, que, depois de longa resistência durante as guerras de 1683-1699, caiu em julho de 1687 em poder de Veneza juntamente com as fortalezas vizinhas, permaneceu nas mãos dos venezianos até um ano depois do Tratado de Karlowitz e depois voltou aos otomanos. A fortaleza, na boca do golfo de Corinto, voltou assim à administração otomana quinze anos antes da Moreia.", "782654b8"]},
"OLAYLAR_H7_ASAMA:1733-07-19:0":{"b": ["Topal Osman Paşa derrotou Nâdir em Dücum — o cerco de Bagdade foi levantado", "7ae1fc9e"], "d": ["Contra Nâdir, que sitiara Bagdade em janeiro de 1733, o exército sob o comando de Topal Osman Paşa, enviado em socorro de Bagdade, derrotou as forças de Nâdir em Dücum, perto de Sâmerrâ; Nâdir, ferido, recuou para Hamadã e o cerco, que durava havia meses, foi levantado. Mas a vitória foi breve: Nâdir voltou a entrar no Iraque no fim do mesmo ano e derrotou as forças otomanas em Akderbend, a norte de Kerkük; Topal Osman Paşa perdeu a vida nestas batalhas e foi sepultado em Kerkük.", "6444aec6"]},
"OLAYLAR_H7_ASAMA:1743-02-25:0":{"b": ["Campanha do Iraque de Nâdir Xá — começou a última guerra otomano-iraniana, Kerkük caiu", "ba014bf5"], "d": ["Nâdir Xá, que permaneceu dezoito meses no Daguestão e na Geórgia, tendo os otomanos rejeitado o seu pedido de reconhecimento do Ja'farismo como quinta escola jurídica, iniciou em 1743 uma nova campanha contra os otomanos e entrou em Kerkük com um grande exército. Não conseguiu o mesmo êxito em Mossul; teve de levantar o cerco. Esta guerra é a última guerra otomano-iraniana, terminada pelo Tratado de Kerden de 1746.", "5515afec"]},
"OLAYLAR_H7_ASAMA:1744-07-29:0":{"b": ["Cerco de Kars por Nâdir Xá — durou dois meses, sem resultado", "a3ea61d9"], "d": ["O príncipe safávida Sâfî Mirza, refugiado entre os otomanos, reclamava direitos ao trono do Irão; segundo o plano, o serasker de Kars levá-lo-ia por Tabriz a Isfahan e entronizá-lo, e os otomanos tinham aberto três frentes contra o Irão. Em resposta, Nâdir Xá marchou sobre Kars e sitiou a fortaleza. Do cerco, que durou dois meses, não obteve resultado.", "42fc48b5"]},
"OLAYLAR_H7_ASAMA:1745-08-21:0":{"b": ["Desastre de Kağaverd — o exército de Yeğen Mehmed Paşa dispersou-se", "7caf6f22"], "d": ["No ano seguinte ao cerco de Kars, Nâdir Xá desbaratou, no lugar de Kağaverd, as forças otomanas sob a direção de Yeğen Mehmed Paşa. Depois regressou a Isfahan. A sua desistência da insistência no reconhecimento do Ja'farismo abriu no ano seguinte o caminho ao Tratado de Kerden.", "3992b8ed"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["A tomada do emirado de Hail pelas forças sauditas-wahhabitas — a administração estava nas mãos da família Ibn Ali, da tribo Abde", "2d29ceb9"], "d": ["Quando as forças do Primeiro Estado Saudita tomaram o emirado de Hail, a administração da cidade estava nas mãos da família Ibn Ali, da tribo Abde, da confederação Shammar. Esta família governou Hail até 1835, quando Abdullah b. Reşîd tomou o emirado; a dinastia Reşîdî só foi fundada nessa data. No atlas, Hail aparecia até hoje sem dono até 1836, quando a fonte dá o nome do emir da cidade em 1820.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["A passagem das ilhas do Quarnaro para o Reino de Itália de Napoleão e das Bocas de Cattaro para a administração russa", "c5e411c8"], "d": ["Depois do Tratado de Pojun, as ilhas do Quarnaro — ao contrário da Dalmácia — foram ligadas não diretamente à França, mas ao Reino de Itália de Napoleão; só entraram nas Províncias Ilíricas em 1809. Nas Bocas de Cattaro, a administração austríaca terminou e entre 1806 e 1807 foi estabelecida a administração russa; as Bocas só passaram à França em 1807. Estas duas distinções não podem ser cobertas por uma única janela 'França' do atlas.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["A passagem da Dalmácia para a administração francesa — a aplicação do Tratado de Pojun (Presburgo)", "00bfe4f6"], "d": ["O Tratado de Pojun (Bratislava/Presburgo) de 26 de dezembro de 1805 forçou a Áustria a renunciar à Ístria, à Dalmácia e a todas as ilhas do Adriático. A França assumiu de facto a administração em fevereiro de 1806; Zadar permaneceu como centro do provedor-geral, e entre 1806 e 1810 este cargo foi exercido pelo veneziano Vicenzo Dandolo. A Dalmácia foi incorporada nas Províncias Ilíricas depois do Tratado de Schönbrunn de 1809. Terminou assim a primeira administração austríaca, que durava desde 1797 — no atlas, este período aparecia até hoje como austríaco ininterrupto.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["A recuperação das Províncias Ilíricas e da Dalmácia pela Áustria — o fim da administração napoleónica", "1b2ac942"], "d": ["No fim de 1813, as tropas habsburgas retomaram a região a sul do Sava e foi restabelecida a antiga organização da fronteira; o exército austríaco entrou na Ístria em outubro de 1813. Karlovac passou, depois dessa data, a fazer parte do Reino Austríaco da Ilíria. O período da administração francesa na Dalmácia encerrou-se também em 1813. A pertença da região à Áustria foi oficialmente confirmada pelas decisões da Paz de Paris de 1814 e do Congresso de Viena de 1815.", "a5c337df"]},
"OLAYLAR_KURULUS_GERI_1021:0630-01-11:0":{"b": ["Meca foi conquistada: a cidade passou para o Estado de Medina", "8435e73c"], "d": ["O Profeta conquistou Meca (20 Ramazan 8 / 11 de janeiro de 630).", "865a73bd"]},
"OLAYLAR_KURULUS_GERI_1021:0632-06-08:0":{"b": ["Morte do Profeta: Meca ficou ligada aos califas Râşidîn", "b65e8cd1"], "d": ["Muhammed faleceu a 13 Rebîülevvel 11 / 8 de junho de 632; Meca passou para o governo dos califas Râşidîn.", "99716bea"]},
"OLAYLAR_KURULUS_GERI_1021:0638-01-01:0":{"b": ["Kûfe foi fundada", "617d0f35"], "d": ["Kûfe foi estabelecida como cidade de guarnição geralmente no ano 17 (638); tornou-se o centro do Califado dos Râşidîn no Iraque (o dia é desconhecido).", "abaf8837"]},
"OLAYLAR_KURULUS_GERI_1021:0661-01-01:0":{"b": ["Ali foi martirizado em Kûfe; Kûfe passou para o domínio omíada", "94fb307d"], "d": ["Ali foi martirizado na Mesquita de Kûfe por İbn Mülcem (661); o período dos Râşidîn encerrou-se, a cidade entrou sob a administração omíada (precisão de ano; o interregno zubayrida de 680-691 não foi registado separadamente).", "a58ed98f"]},
"OLAYLAR_KURULUS_GERI_1021:0661-07-29:0":{"b": ["Muâviye recebeu o juramento de fidelidade: Meca entrou sob o domínio omíada", "d6dcc232"], "d": ["Muâviye recebeu o juramento de fidelidade a 25 Rebîülevvel 41 / 29 de julho de 661; Meca ficou ligada aos governadores omíadas (não há dia específico para Meca, é o dia do Estado).", "16cecb18"]},
"OLAYLAR_KURULUS_GERI_1021:0670-01-01:0":{"b": ["Cairuão foi fundada (Ukbe b. Nâfi‘, omíada)", "7409e9ae"], "d": ["O governador omíada Ukbe b. Nâfi‘ fundou Cairuão em 670 como base da Ifríquia.", "b2240f4e"]},
"OLAYLAR_KURULUS_GERI_1021:0683-11-27:0":{"b": ["İbnüzzübeyr proclamou o seu califado em Meca: Meca saiu do domínio omíada", "9e31ca5c"], "d": ["A notícia da morte de Yezîd chegou a Meca (27 de novembro de 683); Abdullah b. Zübeyr proclamou um califado com centro em Meca (64/683).", "212a96b5"]},
"OLAYLAR_KURULUS_GERI_1021:0692-10-01:0":{"b": ["Haccâc tomou Meca: a cidade voltou a entrar sob o domínio omíada", "48dd6e68"], "d": ["No fim do cerco de Haccâc b. Yûsuf, Meca voltou a entrar sob o domínio omíada a 14 Cemâziyelevvel 73 / 1 de outubro de 692.", "25eedec5"]},
"OLAYLAR_KURULUS_GERI_1021:0745-01-01:0":{"b": ["Abdurrahman b. Habîb revoltou-se: Cairuão saiu da administração omíada", "4c7a0da0"], "d": ["Com a revolta de Abdurrahman b. Habîb em 745, Cairuão saiu do governo omíada; até 761, interregno habibida/carijita (lacuna com proprietário declarado).", "69dac839"]},
"OLAYLAR_KURULUS_GERI_1021:0749-09-02:0":{"b": ["O exército abássida tomou Kûfe", "0191709e"], "d": ["O exército abássida tomou Kûfe a 14 Muharrem 132 (2 de setembro de 749); a cidade passou dos Omíadas para os Abássidas.", "998fc494"]},
"OLAYLAR_KURULUS_GERI_1021:0750-08-05:0":{"b": ["O Estado omíada chegou ao fim: Meca passou para o domínio abássida", "382e4d6e"], "d": ["O último califa omíada, Mervân II, foi morto a 26 Zilhicce 132 / 5 de agosto de 750; Meca entrou no governo abássida dos Haremeyn (não há dia específico para Meca — é o dia do fim do Estado, aproximação declarada).", "710c6ec7"]},
"OLAYLAR_KURULUS_GERI_1021:0761-01-01:0":{"b": ["Muhammed b. Eş‘as, nomeado pelos Abássidas, tomou Cairuão", "71af9f79"], "d": ["Muhammed b. Eş‘as tomou Cairuão em nome dos Abássidas no ano 144 (761).", "a71fe419"]},
"OLAYLAR_KURULUS_GERI_1021:0762-01-01:0":{"b": ["O califa Mansûr iniciou a construção de Bagdade (Medînetüsselâm)", "844a94d5"], "d": ["As obras de construção da cidade, fundada nas margens do Tigre, começaram em 762; tornou-se a capital permanente dos Abássidas (o dia é desconhecido, apenas o ano está confirmado).", "750c6eb1"]},
"OLAYLAR_KURULUS_GERI_1021:0800-01-01:0":{"b": ["İbrâhim b. Ağleb tornou-se governador: os Aglábidas em Cairuão", "f7279ba9"], "d": ["Hârûnürreşîd nomeou İbrâhim b. Ağleb governador da Ifríquia; os Aglábidas (800-909) fizeram de Cairuão a sua capital.", "3b6e9426"]},
"OLAYLAR_KURULUS_GERI_1021:0909-01-01:0":{"b": ["Os Fatímidas tomaram Cairuão; os Aglábidas chegaram ao fim", "021693e0"], "d": ["Em 909, Ziyâdetullah III fugiu para o Egito; Cairuão passou para os Fatímidas.", "a6422efd"]},
"OLAYLAR_KURULUS_GERI_1021:0945-12-19:0":{"b": ["O buída Ahmed (Muizzüddevle) entrou em Bagdade; a cidade passou para o domínio buída", "31accd4a"], "d": ["Ahmed entrou em Bagdade a 11 Cemâziyelevvel 334 (19 de dezembro de 945); o califa Müstekfî nomeou-o emîrü'l-ümerâ, e a cidade passou para o domínio dos Buídas (Kûfe também entrou sob o domínio buída de 945-1055; para Kûfe, o dia foi tomado de Bagdade, a vizinha).", "11f31be7"]},
"OLAYLAR_KURULUS_GERI_1021:0969-01-01:0":{"b": ["Em Meca foi recitado o sermão em nome dos Fatímidas (358/969)", "3f069fea"], "d": ["O emir de Meca, Ca‘fer b. Muhammed, fez recitar o sermão em nome dos Fatímidas (358/969, precisão de ano); os Fatímidas como Estado suserano.", "2256892c"]},
"OLAYLAR_KURULUS_GERI_1021:0972-10-02:0":{"b": ["Os Ziridas em Cairuão (Bulukkîn b. Zîrî, governador da Ifríquia)", "5494e662"], "d": ["Em nome do califa fatímida, Bulukkîn b. Zîrî governou a Ifríquia; os Ziridas (972-1057) dominam Cairuão (o TDV dá o ano, o dia vem do f da ficha).", "ffcba4c5"]},
"OLAYLAR_KURULUS_GERI_1021:1057-01-01:0":{"b": ["Saque hilalida: Mu‘izz b. Bâdîs retirou-se para Mahdia, o domínio zirida em Cairuão chegou ao fim", "4dbbdff5"], "d": ["Por volta de 449 (1057), os Hilalidas saquearam Cairuão; os Ziridas retiraram-se para Mahdia; até 1229, o senhor da cidade não pode ser seguido ano a ano nas fontes (lacuna declarada).", "8bebfdc7"]},
"OLAYLAR_KURULUS_GERI_1021:1085-05-25:0":{"b": ["Afonso VI entrou em Toledo: a cidade passou para o domínio castelhano", "3b72bb5f"], "d": ["Treccani: Afonso VI entrou em Toledo a 25 de maio de 1085; dois anos depois a cidade tornou-se a capital de Castela (o TDV tuleytula dá apenas o ano: 478/1085; na cronologia da cauda, o dia da rendição, 8 de maio de 1085, está registado à parte).", "fa2c9677"]},
"OLAYLAR_MISIR1801:1801-05-14:0":{"b": ["A retoma de Damieta aos franceses — evacuação da fortaleza de Lesbe", "06b1e7b0"], "d": ["Uma força comandada por İbrâhim Paxá, do exército do grão-vizir, foi enviada a Damieta. Na manhã de 14 de maio, quando estava preparado o assalto à fortaleza de Lesbe, que protegia Damieta, verificou-se que a fortaleza fora evacuada pelos franceses e que a guarnição se retirara; tomaram-se também duas pequenas fortalezas ligadas a ela. Damieta foi, depois de Rosetta, que caíra em abril, a segunda cidade da foz do Nilo a sair do controlo francês.", "2eb4936c"]},
"OLAYLAR_MISIR1801:1801-06-27:0":{"b": ["Receção do Cairo aos franceses — a capitulação de Belliard", "7a11bb5e"], "d": ["Durante a operação conjunta das forças otomanas e britânicas contra o Egito, o general Belliard, comandante das forças francesas no Cairo, assinou a capitulação. Com o Cairo, também Suez, que os franceses tinham tomado em novembro de 1798, saiu do controlo francês. O encerramento da ocupação concluiu-se dois meses depois em Alexandria, e a evacuação do país prolongou-se até outubro.", "e8dac3f4"]},
"OLAYLAR_MISIR1801:1801-08-31:0":{"b": ["Receção de Alexandria aos franceses — a capitulação de Menou", "cd50663c"], "d": ["O general Menou, comandante-chefe do Exército do Oriente, foi sitiado em Alexandria a 17 de agosto; a 21 de agosto, os ingleses tomaram o forte Marabout, perto da cidade, e a 31 de agosto Menou assinou a capitulação do exército. O regresso das tropas francesas a França começou a 2 de setembro. Assim, a ocupação, iniciada com o desembarque em Alexandria em junho de 1798, terminou na cidade em que começara.", "22e807c1"]},
"OLAYLAR_OK106:1571-01-01:0":{"b": ["Avanço da Polónia na linha do Dniepre — fundação de Kremenchuk", "1bc86966"], "d": ["A Polónia-Lituânia fundou uma nova vila de fronteira na junção do Dniepre médio, passagem das incursões da Crimeia; vinte e cinco anos depois, acrescentou-se-lhe também uma fortaleza. Assim, a linha de controlo da Polónia desceu até à margem norte da estepe de Zaporozhia e esta passagem do rio ficou ligada, pela primeira vez, à guarnição permanente de um Estado. No século seguinte, a vila passaria à ordem do Hetmanato como centro de regimento cossaco.", "4d022f2b"]},
"OLAYLAR_OK106:1616-01-01:0":{"b": ["Surgimento de Uman na linha de fronteira de Yedisan da Polónia", "2e6551ab"], "d": ["Uman figurou pela primeira vez nos documentos como povoado na extremidade sudeste da região de Bratslav, sob administração polaca. O lugar situava-se nos caminhos de incursão do Canato da Crimeia que se estendiam para norte; o estabelecimento aqui de uma vila permanente mostra que a faixa de estepe vazia entre os dois Estados começava a estreitar-se pelo norte. Nos dois séculos seguintes, a cidade continuaria a ser o maior povoado polaco mais a sul desta linha.", "7a425b4c"]},
"OLAYLAR_OK106:1638-01-01:0":{"b": ["Avanço da linha de defesa da estepe de Moscovo — Chuhuiv", "c68d36d3"], "d": ["O líder cossaco Yakiv Ostrianyn e os seus homens, que se tinham refugiado em Moscovo depois da revolta na Polónia, fundaram um povoado de fronteira nas margens do Donets. Foi um dos primeiros grandes saltos da linha de defesa que Moscovo construiu contra as incursões da Crimeia em direção à estepe; no meio século seguinte, nasceriam sucessivamente na mesma linha vilas como Sumy, Izium e Bakhmut. O povoado durou até 1765 como centro de uma companhia ligada ao regimento de Carcóvia.", "3fdefaaa"]},
"OLAYLAR_OK106:1652-01-01:0":{"b": ["Fundação da Ucrânia Sloboda — Sumy e a faixa de povoamento da estepe", "ab7abf59"], "d": ["Camponeses e cossacos vindos do regimento de Bila Tserkva, na Ucrânia da margem direita, fundaram uma nova vila nas margens do Psel, sob a chefia do coronel Herasym Kondratiev; quatro anos depois, o voivoda de Moscovo fortificou a fortaleza. Esta vaga migratória é o início da ordem da Ucrânia Sloboda, que abriu ao povoamento a estepe vazia na fronteira sul de Moscovo: aos recém-chegados concedeu-se isenção de impostos e esperava-se em troca serviço de guarda de fronteira. Sumy foi, de 1658 a 1765, o centro do regimento que levava o seu nome.", "fc9a8983"]},
"OLAYLAR_OK106:1703-05-17:0":{"b": ["Construção de Yenikale — o fecho do Estreito de Kerch", "d9067015"], "d": ["Depois da cedência de Azov à Rússia em 1700, a única porta do Mar Negro que abria para o Mar de Azov transformou-se numa linha de fronteira estratégica. O Império Otomano mandou construir uma nova fortificação no lugar de Akıntı Burnu, dez quilómetros a nordeste da cidade de Kerch, pondo a passagem do estreito ao alcance dos canhões; à fortaleza deu-se o nome de Yenikale, que é a própria palavra. A fortaleza permaneceu setenta anos como o fecho oriental da Crimeia e foi cedida à Rússia, juntamente com Kerch, pelo 19.º artigo do Tratado de Küçük Kaynarca de 1774.", "8f8533a1"]},
"OLAYLAR_OK106:1754-01-01:0":{"b": ["Fortaleza de Santa Isabel — a fronteira meridional da Rússia encosta-se à linha de incursões otomano-crimeia", "b9097272"], "d": ["A Rússia construiu uma nova fortaleza, de nome Santa Isabel, no território dos cossacos zaporozhianos. A razão declarada da fortaleza era proteger dos ataques otomanos e da Crimeia os imigrantes balcânicos instalados na Nova Sérvia; ou seja, a linha de fronteira russa desceu pela primeira vez até ao meio da estepe, sobre os caminhos das incursões. Este posto avançado foi o ponto de partida da expansão para o Mar Negro setentrional que começaria vinte anos depois com Küçük Kaynarca.", "8ac6527e"]},
"OLAYLAR_OK106:1847-05-31:0":{"b": ["Segundo Tratado de Erzurum — a fronteira do Shatt al-Arab e a cedência da costa do Khuzestão", "5d1f9103"], "d": ["A disputa fronteiriça otomano-iraniana, por resolver havia mais de um século, foi regulada por um segundo tratado, assinado em Erzurum depois de longas negociações conduzidas com a mediação britânica e russa. A totalidade da via fluvial do Shatt al-Arab ficou com os otomanos; em contrapartida, os povoados da margem oriental do rio — incluindo o porto de Muhammere e a ilha de Abadan, em frente — foram deixados aos Qajares. Assim, a faixa costeira do Khuzestão, considerada sob administração otomana desde a anexação de Baçorá em 1546, escapou-lhes trezentos anos depois. Mehmed Hurşid Paşa, membro da comissão de fronteiras constituída para fixar no terreno a linha traçada pelo tratado, percorreu a região entre 1848 e 1852 e escreveu o Seyâhatnâme-i Hudûd.", "8fe2f887"]},
"OLAYLAR_OK107:1514-09-15:0":{"b": ["Retirada de Tabriz — fim de uma ocupação de uma semana e regresso por Kars-Bayburt", "fd1542e3"], "d": ["Selim o Inflexível, que entrou em Tabriz em 6 de setembro depois da vitória de Çaldıran, ficou na cidade cerca de uma semana; fez emigrar para Istambul, com as famílias, o tesouro do xá Ismâil e parte dos artesãos e sábios da cidade. Quis passar o inverno em Karabağ e continuar a campanha no ano seguinte, mas, perante a oposição dos janízaros, desistiu deste plano e o exército regressou por Kars e Bayburt. Assim, Tabriz não ficou em mãos otomanas: Çaldıran foi uma vitória de batalha campal; o ganho territorial duradouro veio no ano seguinte com a campanha de Kemah, Diyarbekir e da Anatólia Oriental.", "9cc5fc19"]},
"OLAYLAR_OK107:1515-09-19:0":{"b": ["Anexação de Nusaybin, Derik e Silopi ao Império Otomano — o ramo meridional de Diyarbekir", "c3621d22"], "d": ["Depois da tomada de Âmid e da fundação do beilerbeilique de Diyarbekir, com a conquista dos beis curdos da região por İdrîs-i Bitlisî, Nusaybin, Derik e Silopi, a sul da planície de Mardin, passaram também para a administração otomana. Estes lugares foram organizados como centros de nahiye e kaza do novo beilerbeilique; alguns, como Cizre, foram deixados aos seus beis locais com o estatuto de yurtluk-ocaklık. Assim, a campanha da Anatólia Oriental iniciada depois de Çaldıran chegou à Alta Jazira.", "f975424e"]},
"OLAYLAR_OK109:1918-10-28:0":{"b": ["Declaração de independência da Checoslováquia — o primeiro Estado sucessor da herança dos Habsburgos", "8f40155f"], "d": ["Com a perda de força da Áustria-Hungria na guerra e as greves, manifestações e revoltas no interior do país, o Conselho Nacional declarou em 28 de outubro de 1918 a independência da Checoslováquia. Com base na situação eleitoral de 1911, foi constituída uma assembleia nacional provisória, e em 14 de novembro de 1918 o governo, à frente do qual foi colocado Masaryk, entrou em funções. O novo Estado obteve o seu lugar no direito internacional com o Tratado de Saint-Germain-en-Laye (10 de setembro de 1919). No mapa, a Checoslováquia aparece em 11 de novembro de 1918; a declaração de independência é duas semanas anterior.", "80a8405f"]},
"OLAYLAR_OK109:1918-10-29:0":{"b": ["Proclamação do Estado dos Eslovenos, Croatas e Sérvios — o Sabor croata rompeu os laços com os Habsburgos", "2e5ae559"], "d": ["O Sabor croata declarou em 29 de outubro de 1918 que cortava todos os laços de direito público da Croácia, da Eslavónia e da Dalmácia com a Áustria-Hungria; no mesmo dia celebrou-se em Liubliana a fundação do Estado dos Eslovenos, Croatas e Sérvios. Na Bósnia-Herzegovina, a administração austro-húngara transferiu o poder em 1 de novembro de 1918 para o governo do Conselho Nacional. Este Estado durou até à proclamação em Belgrado, em 1 de dezembro de 1918, do Reino dos Sérvios, Croatas e Eslovenos.", "9e0cf3b3"]},
"OLAYLAR_OK109:1918-10-30:0":{"b": ["Fundação da República da Áustria — o núcleo alemão da herança dos Habsburgos", "1ec8b06f"], "d": ["Quando se proclamou, em 29 de outubro, a fundação da Checoslováquia em Praga e do Estado dos Sérvios, Croatas e Eslovenos em Zagrebe, os alemães da Áustria fundaram também, em 30 de outubro, a República da Áustria. No mesmo dia, o Império Otomano assinava o Armistício de Mudros; o fim dos dois impérios caiu lado a lado no calendário.", "3772c9f7"]},
"OLAYLAR_OK109:1918-10-31:0":{"b": ["Revolução dos Ásteres — Károlyi tornou-se primeiro-ministro, a monarquia começou a desfazer-se na Hungria (a república popular foi proclamada em 16 de novembro)", "d7780d2e"], "d": ["Quando se percebeu a derrota das Potências Centrais, os sentimentos antimonárquicos reforçaram-se na Hungria e houve uma deriva para a esquerda. Em 31 de outubro de 1918, no fim da \\\"revolução dos ásteres\\\", o conde Mihály Károlyi, de opiniões radicais, tornou-se primeiro-ministro e a seguir foi proclamada a república popular; Károlyi foi eleito presidente efetivo em 11 de janeiro de 1919.", "0a48f4b7"]},
"OLAYLAR_OK109:1918-11-03:0":{"b": ["Armistício de Villa Giusti — a Áustria-Hungria depôs as armas, Trento e Trieste passaram para a Itália", "75da65fb"], "d": ["A assinatura, pelo imperador Carlos, do armistício com os italianos em Villa Giusti, em 3 de novembro de 1918, acelerou a desintegração do império. O TDV regista este dia expressamente como o da deposição das armas pela Áustria: \"A Áustria, que aceitou a derrota, depôs as armas em 3 de novembro, e a Alemanha em 11 de novembro.\" No mapa, Trento e Trieste passam neste dia da Áustria para a Itália — é a primeira cedência territorial visível no mapa da desintegração.", "a86d1725"]},
"OLAYLAR_OK109:1918-11-11:0":{"b": ["Independência da Polónia — o Conselho de Regência entregou o comando do exército a Piłsudski", "e8b546cf"], "d": ["Józef Piłsudski regressou a Varsóvia em 10 de novembro de 1918. Em 11 de novembro, o Conselho de Regência entregou-lhe o comando do exército; poucos dias depois deixou-lhe também a tarefa de formar o governo nacional.", "578314ea"]},
"OLAYLAR_OK109:1918-11-14:0":{"b": ["O exército sérvio ocupou Pécs (Peçuy) — começou a ocupação sérvia de Baranya", "68f0695f"], "d": ["Pécs, de importância estratégica por causa das minas de carvão, passou à ocupação sérvia em 14 de novembro de 1918. A ocupação sérvia de Pécs e da província de Baranya durou até agosto de 1921.", "7222b6bd"]},
"OLAYLAR_OK109:1918-11-14:1":{"b": ["O exército sérvio ocupou Timișoara (Temeşvar) — começou a administração militar sérvia do Banat", "3cc85350"], "d": ["As tropas sérvias ocuparam Timișoara em 14 de novembro de 1918, dispersaram as guardas nacionais e assumiram a administração militar e, pouco depois, civil do Banat. No início de dezembro, entraram também na cidade tropas francesas; a administração romena só foi estabelecida em julho-agosto de 1919.", "78697a6b"]},
"OLAYLAR_OK109:1918-11-19:0":{"b": ["As tropas sérvias entraram em Szigetvár — ocupação do sul de Somogy", "a06b1907"], "d": ["Do exército sérvio que avançou para norte da linha traçada pela convenção militar de Belgrado, 220 soldados sob o comando de Obren Petrović entraram, na noite de 18 para 19, em Szigetvár, sede de distrito de Somogy; as aldeias do distrito foram também ocupadas por esta força. A ocupação durou até agosto de 1921; Trianon deixou Szigetvár na Hungria.", "9485d5ab"]},
"OLAYLAR_OK109:1918-12-01:0":{"b": ["Fundação do Reino dos Sérvios, Croatas e Eslovenos e da Grande Roménia — no mesmo dia, dois Estados", "6fd85345"], "d": ["Com a desintegração da Áustria-Hungria, da união com a Sérvia dos eslavos separados do império resultou a fundação, em 1 de dezembro de 1918, do Reino dos Sérvios, Croatas e Eslovenos; cerca de 250.000 km² de território e 12.000.000 de habitantes. Os alicerces tinham sido lançados na Declaração de Corfu de 20 de julho de 1917; as assembleias de Podgorica em 26 de outubro, da Bósnia-Herzegovina em 28 de outubro e de Novi Sad em 25 de novembro tinham tomado a decisão de adesão. No mesmo dia, com a adesão da Transilvânia, da Bucovina e da Bessarábia por decisão dos seus próprios povos, formou-se a Grande Roménia. No mapa, o território do Reino da Sérvia passa para a Jugoslávia.", "4565e7a6"]},
"OLAYLAR_OK109:1918-12-01:1":{"b": ["O exército romeno entrou em Brașov (Brassó) e foi recebido em cerimónia", "4a917d27"], "d": ["O exército romeno entrou em Brașov em dezembro de 1918; os notáveis romenos da cidade receberam em cerimónia o exército e o general Berthelot.", "96d03f2f"]},
"OLAYLAR_OK109:1918-12-19:0":{"b": ["O exército italiano ocupou Knin", "7949dd0f"], "d": ["O exército italiano ocupou Knin em 19 de dezembro de 1918. A ocupação durou até 4 de abril de 1921, quando o exército italiano se retirou da cidade, depois do Tratado de Rapallo.", "f4363313"]},
"OLAYLAR_OK109:1918-12-29:0":{"b": ["As tropas checoslovacas tomaram Košice (Kassa)", "0989490f"], "d": ["Quando o 30.º Regimento de Infantaria, que leva o nome de Alois Jirásek, ocupou a cidade em 29 de dezembro de 1918, Košice foi de facto integrada na República Checoslovaca.", "2453b355"]},
"OLAYLAR_OK109:1919-04-20:0":{"b": ["O exército romeno entrou em Szatmár (19 de abril) e em Oradea (Varad, 20 de abril)", "3ee2bd72"], "d": ["No sábado de Páscoa, 19 de abril de 1919, em Satu Mare, a delegação local, chefiada pelo dr. Ilie Carol Barbul, recebeu na ponte do Someș a primeira patrulha da 2.ª Divisão de Cavalaria sob o comando do coronel Ressel. No dia seguinte, 20 de abril de 1919, as tropas romenas sob o comando do general Traian Moșoiu entraram em Oradea.", "9249e364"]},
"OLAYLAR_OK109:1919-06-28:0":{"b": ["Tratado de Versalhes — a restituição da Alsácia-Lorena à França passou para o direito", "3babdfcb"], "d": ["A Conferência de Paz de Paris reuniu-se em 18 de janeiro de 1919 e, em 28 de junho, foi assinado com a Alemanha o Tratado de Versalhes. O artigo 51.º do tratado restituiu à soberania francesa a Alsácia-Lorena (Estrasburgo, Metz, Colmar, Mulhouse), alemã desde 1871 — mas ligou a cedência não ao dia da assinatura, e sim, retroativamente, ao armistício de 11 de novembro de 1918. A mesma série de conferências produziu, com a Áustria, Saint-Germain (10 de setembro de 1919), com a Bulgária, Neuilly (27 de novembro de 1919), com a Hungria, Trianon (4 de junho de 1920) e, com o Império Otomano, Sèvres (10 de agosto de 1920).", "4ab970de"]},
"OLAYLAR_OK109:1919-07-22:0":{"b": ["As tropas romenas chegaram a Lugoj (Lugos) — administração romena no leste do Banat", "f65fc73c"], "d": ["O comboio com as tropas romenas chegou a Lugoj em 22 de julho de 1919 às 14 horas; a população da cidade recebeu o exército na estação, o prefeito de Caraș-Severin, George Dobrin, pronunciou o discurso de boas-vindas e o general Jitianu respondeu. Na parte do Banat atribuída à Roménia, a administração romena foi estabelecida em julho de 1919; a transferência jurídica deu-se com o Tratado de Trianon de 1920.", "b228ed28"]},
"OLAYLAR_OK109:1919-08-03:0":{"b": ["O exército romeno entrou em Timișoara (Temeşvar) — estabeleceu-se na cidade a administração romena", "8728e1d1"], "d": ["Em Timișoara, onde tinham entrado tropas sérvias em 14 de novembro de 1918 e francesas no início de dezembro, entraram na manhã de 3 de agosto de 1919 as primeiras unidades do exército romeno sob o comando do coronel Virgil Economu e estabeleceu-se na cidade a administração romena.", "0b1627d3"]},
"OLAYLAR_OK109:1919-08-12:0":{"b": ["O exército SHS entrou em Prekmurje — Murska Sobota e Lendava saíram da administração húngara", "21b2ba08"], "d": ["As tropas do Reino dos Sérvios, Croatas e Eslovenos entraram em 12 de agosto de 1919 em Prekmurje, para lá do rio Mura; a administração húngara na região terminou nesse dia. A transferência jurídica deu-se com o Tratado de Trianon de 1920.", "3ce8a913"]},
"OLAYLAR_OK109:1919-09-10:0":{"b": ["Tratado de Saint-Germain — a redução da Áustria passou para o direito", "e7b722d5"], "d": ["Depois da guerra, a Áustria assinou com os aliados o Tratado de Paz de Saint-Germain. Segundo o tratado, a Áustria reconhecia a independência da Hungria, da Checoslováquia e da Jugoslávia; aceitava não se unir à Alemanha sem o consentimento da Sociedade das Nações, abolir o serviço militar obrigatório e limitar o exército a 30.000 homens. É também o documento pelo qual a Checoslováquia obteve o seu lugar no direito internacional. A cedência no mapa tinha ocorrido um ano antes; este tratado registou-a.", "482c2ef4"]},
"OLAYLAR_OK109:1919-11-27:0":{"b": ["Tratado de Neuilly — a Bulgária perdeu a Trácia Ocidental e a costa do Egeu", "01f2b8c8"], "d": ["Com o fim da guerra em derrota, o czar Fernando teve de pedir o armistício e abdicar a favor do filho Boris (29 de setembro de 1918). Pelo Tratado de Neuilly, que pôs fim à guerra, a Bulgária sofreu uma perda territorial estratégica a favor dos sérvios, perdeu toda a Trácia Ocidental, teve de ceder à Grécia a costa do Mar Egeu e confirmou as disposições do Tratado de Bucareste que dava a Dobruja do Sul à Roménia. No mapa, a correspondência desta transferência não está no dia do tratado, mas em maio de 1920, quando a administração mudou de facto de mãos: Dedeağaç, Sofulu, Orestiada e Çirmen passam em 14 de maio, Gümülcine, İskeçe, Dimetoka e Ferecik em 27 de maio para a Grécia.", "d61eb549"]},
"OLAYLAR_OK109:1920-06-04:0":{"b": ["Tratado de Trianon — a Hungria perdeu dois terços do seu território", "84aff507"], "d": ["Segundo o Tratado de Trianon, assinado três meses depois da colocação de Horthy na regência, em 1 de março de 1920, a Hungria sofreu uma pesada perda de território e de população: dois terços do seu território de 283.000 km², excluída a Croácia, e sessenta por cento da sua população, incluindo mais de três milhões de húngaros, ficaram fora das fronteiras, e o exército foi reduzido a 35.000 homens. No mapa, a Regência da Hungria aparece com estas fronteiras reduzidas; a Transilvânia e a Alta Hungria passam também neste mesmo dia para as cores da Roménia e da Checoslováquia.", "6073745e"]},
"OLAYLAR_OK109:1920-06-04:1":{"b": ["O Banat foi repartido, Timișoara foi deixada à Roménia (Trianon art. 27/3 e 45)", "256b4aca"], "d": ["O Tratado de Trianon traçou a fronteira húngaro-romena pelo art. 27/3 e, pelo art. 45, a Hungria renunciou, a favor da Roménia, a todos os direitos e títulos sobre os antigos territórios da monarquia para lá desta fronteira; assim, a união da Transilvânia, do Banat, de Crișana e de Maramureș com a Roménia foi reconhecida no direito internacional. A região do Banat foi repartida entre a Roménia e a Sérvia; a cidade de Timișoara foi integrada no Reino da Roménia. A administração romena funcionava de facto em Timișoara desde 3 de agosto de 1919; o tratado passou esta situação para o direito.", "5ec9c446"]},
"OLAYLAR_OK109:1921-04-04:0":{"b": ["O exército italiano retirou-se de Knin", "a1d2e846"], "d": ["Depois do Tratado de Rapallo, o exército italiano retirou-se de Knin em 4 de abril de 1921; terminou a ocupação iniciada em 19 de dezembro de 1918.", "0af4a592"]},
"OLAYLAR_OK109:1921-06-12:0":{"b": ["A Itália entregou Šibenik ao Reino SHS", "9d07b12a"], "d": ["A ocupação italiana, iniciada em 6 de novembro de 1918, terminou em 12 de junho de 1921 com uma cerimónia a que assistiram representantes militares da Itália e do Reino SHS.", "3d4d272c"]},
"OLAYLAR_OK109:1921-08-20:0":{"b": ["As tropas sérvias retiraram-se de Szigetvár — a gendarmaria húngara assumiu a cidade", "97781b77"], "d": ["Depois da entrada em vigor de Trianon, as forças sérvias começaram a retirar-se de Barcs e Szigetvár em 17 de agosto e levaram tudo o que se podia transportar. Por volta do meio-dia de 20 de agosto entraram as unidades de gendarmaria húngara; à tarde, a assembleia municipal e os funcionários prestaram juramento e, às cinco horas, fez-se no edifício da câmara a entrega militar.", "1db599da"]},
"OLAYLAR_OK109:1921-08-22:0":{"b": ["Terminou a ocupação sérvia de Pécs (Peçuy) — o Exército Nacional Húngaro entrou na cidade", "f437115a"], "d": ["As tropas sérvias começaram a evacuar a região em 18 de agosto de 1921; em 20-21 de agosto, a administração da cidade e da província foi entregue aos representantes do governo húngaro e, em 22 de agosto, as unidades do Exército Nacional Húngaro entraram na cidade.", "0210d518"]},
"OLAYLAR_OK109:1921-11-13:0":{"b": ["O Bundesheer austríaco entrou em Burgenland — o território que Trianon deixou à Áustria foi de facto assumido", "7bfd6915"], "d": ["Trianon (1920) e Saint-Germain (1919) tinham deixado à Áustria a faixa de língua alemã da Hungria Ocidental; a primeira tentativa de tomada de posse, em 28 de agosto de 1921, fracassou com a resistência das tropas irregulares húngaras. Depois do Protocolo de Veneza (13 de outubro de 1921), a Comissão Geral Aliada aprovou em 11 de novembro a entrada do Bundesheer e o norte de Burgenland começou a ser assumido dois dias depois; o sul foi assumido em 6 de dezembro de 1921; a região de Sopron ficou na Hungria por plebiscito.", "c78d0f81"]},
"OLAYLAR_ONCE1000_1019:0330-05-11:0":{"b": ["Constantinopla foi inaugurada com cerimónia; o centro do império deslocou-se de facto para o Oriente", "e4d78842"], "d": ["A nova capital fundada por Constantino I foi inaugurada com cerimónia em 11 de maio de 330; Constantinopla tornou-se a capital do Império Bizantino (Romano do Oriente).", "482503e4"]},
"OLAYLAR_ONCE1000_1019:0969-07-06:0":{"b": ["O comandante Cevher es-Sıkıllî entrou em Fustat e conquistou o Egito; os Ikhshididas chegaram ao fim", "fd0410b1"], "d": ["Em nome do califa fatímida Muʿizz-lidînillâh, Cevher es-Sıkıllî entrou em Fustat (17 Şâban 358 / 6 de julho de 969); o Egito passou dos Ikhshididas para os Fatímidas, e a região onde o Cairo viria a ser fundado entrou sob o domínio fatímida.", "4aee6045"]},
"OLAYLAR_ONCE1000_1019:0990-03-31:0":{"b": ["Ebü'z-Zevvâd tomou Mossul; fundada a dinastia uqailida", "c3032f55"], "d": ["O uqailida Ebü'z-Zevvâd Muhammed b. Müseyyeb apoderou-se de Mossul (380 / 990); foi escolhido o primeiro dia da interseção de 380 hégira ∩ 990, 31 de março de 990 (tabela hégira-gregoriano, ±1-2 dias); o dia não consta da fonte.", "ecd80cfe"]},
"OLAYLAR_ONCE1281_GERIYE:1147-10-24:0":{"b": ["Afonso Henriques tomou Lisboa (Üşbûne); a cidade tornou-se o centro do novo Reino de Portugal", "24fddde8"], "d": ["Üşbûne foi tomada aos Almorávidas e passou para as mãos de Portugal (27 Cemâziyelevvel 542 / 24 de outubro de 1147).", "bd3b3add"]},
"OLAYLAR_ONCE1281_GERIYE:1229-12-31:0":{"b": ["Jaume I tomou a cidade de Maiorca (Medina Mayurqa)", "47fd675c"], "d": ["O rei de Aragão Jaume I tomou aos muçulmanos a cidade de Maiorca; Palma passou para a Coroa de Aragão.", "462f0592"]},
"OLAYLAR_ONCE1281_GERIYE:1238-05-12:0":{"b": ["Muhammed b. Yûsuf İbnü'l-Ahmer fundou o Estado Nasrida em Granada", "23f66f33"], "d": ["O Estado Nasrida foi fundado com centro em Granada (26 Ramazan 635 / 12 de maio de 1238).", "04a01554"]},
"OLAYLAR_ONCE1281_GERIYE:1238-06-01:0":{"b": ["Tratado de Stensby: a Ordem Teutónica devolveu a Estónia do Norte (Reval) ao rei da Dinamarca Valdemar II", "b64c584d"], "d": ["Com o acordo alcançado em Stensby, na Sjælland, em junho de 1238, Reval e a Estónia do Norte voltaram ao domínio dinamarquês (o dia não consta da fonte).", "e8ad663d"]},
"OLAYLAR_ONCE1281_GERIYE:1238-09-28:0":{"b": ["Capitulação de Valência: Jaume I tomou a cidade", "977120b3"], "d": ["Belensiye (Valência) passou para o rei de Aragão Jaume I por capitulação em 28 de setembro de 1238 (entrada solene a 9 de outubro).", "c3465b4f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1054-11-05:0":{"b": ["O ukaylida Kureyş mandou ler a khutba em nome de Tuğrul Bey", "9fb65fc0"], "d": ["Quando Tuğrul Bey veio à região por causa da campanha de Bagdade, o emir ukaylida Kureyş mandou ler a khutba em seu nome em Şaban de 446 / novembro de 1054; depois do assassinato do marwânida Süleyman, ficou gravemente ferido em 447/1055.", "43df7313"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1064-01-01:0":{"b": ["O sultão Alparslan conquistou Ani e entregou a administração da cidade ao Şeddâdî Ebû Şücâ‘ Menûçihr", "f2c51a49"], "d": ["Alparslan, que conquistou Ani em 456/1064, entregou a administração da cidade a Ebû Şücâ‘ Menûçihr, filho do Şeddâdî Ebü'l-Esvâr Şâvur. Menûçihr anexou também Kars aos seus territórios e, receando o exército bizantino que se aproximava, mandou reparar as muralhas destruídas durante a conquista; reinou em Ani durante cinquenta e quatro anos como vassalo seljúcida.", "6ddc5837"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1068-01-01:0":{"b": ["Alparslan apoderou-se de Ahıska", "31b9964f"], "d": ["Ahıska, tomada por Alparslan no tempo dos Seljúcidas (1068), passou em 1267-1268 para o domínio mongol.", "f2d87d84"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1068-01-01:1":{"b": ["Alparslan e os seus aliados arrasaram Tbilisi e Kartli", "ff50ab5d"], "d": ["O rei Bagrat tinha recuperado a maior parte das suas fortalezas; mas em 1068 Alparslan e os seus aliados arrasaram Tbilisi e Kartli.", "753e1b62"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1073-01-01:0":{"b": ["Filaretos reuniu na cidade de Hunu (região de Elbistan) os sacerdotes arménios, mandou eleger um catholicos e fez da cidade sede do catolicado", "66005693"], "d": ["Aproveitando a captura de Romano Diógenes na batalha de Manzikerta de 1071, Filaretos reuniu na cidade de Hunu os sacerdotes arménios e mandou eleger um catholicos. Assim ficou estabelecido o centro religioso de uma administração arménia separada de Bizâncio na região de Maraş-Elbistan-Malatya.", "146d6889"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1076-01-01:0":{"b": ["O sultão Melikşah, numa campanha à Geórgia, chegou até Kartli; confiou a responsabilidade da região a Serheng Savtegin", "830b979a"], "d": ["Melikşah, com Yuane, filho de Liparit, comandante georgiano que lhe permanecera fiel, fez uma campanha contra a Geórgia e chegou a Kartli; regressou com muitos prisioneiros e saque e confiou a responsabilidade da região a Serheng Savtegin (1076). O rei Giorgi II, vencendo as guerras que travou com Savtegin, recuperou alguns lugares.", "8a5912c3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1078-07-14:0":{"b": ["Melikşah entrou na Geórgia pelo Aras, saqueou a região de Somkheth e fez Yuane prisioneiro", "e62fd603"], "d": ["Quando o rei Giorgi II derrotou Savtegin e recuperou alguns lugares, o sultão Melikşah voltou a fazer campanha e entrou na Geórgia pelo Aras (471/1078-79); saqueou a região de Somkheth e fez Yuane prisioneiro e, deixando ali Savtegin com tropas de reforço, regressou. O emir Ahmed infligiu ao rei uma pesada derrota em Kouel e retomou Kars.", "57f4ff76"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1083-01-01:0":{"b": ["Süleyman Şah I fez campanha na Çukurova e conquistou Tarso, Adana, Aynizerbâ e Misis", "c443ee8b"], "d": ["Süleyman Şah, que assumira o título de sultão em 1082, fez nesse mesmo ano uma campanha na Çukurova e conquistou as cidades e fortalezas de Tarso, Adana, Aynizerbâ e Misis (1082-1083); em seguida, a convite da população de Antioquia, marchou sobre Antioquia com os filhos Kılıcarslan e Dâvud.", "e617bea2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-01-01:0":{"b": ["Çubuk Bey conquistou Harput e fundou o Beylik dos Çubukoğulları, que abrangia a região de Palu e Çemişkezek", "1f333d7d"], "d": ["Durante as incursões turcas dirigidas à Anatólia depois de 1071, Çubuk Bey conquistou Harput e fundou o beylik que compreendia as regiões de Palu e Çemişkezek. A vida do beylik foi breve; na década de 1110, o artuquida Belek tomou a cidade.", "5c951bf7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-04-29:0":{"b": ["O sultão Melikşah concedeu como iqta Bitlis e a sua região a Dilmaçoğlu Mehmed Bey; começou o Beylik dos Dilmaçoğulları", "7cdcb46f"], "d": ["Depois de o comandante-chefe do exército seljúcida, Fahrüddevle İbn Cehîr, ter tomado Bitlis e a sua região, o sultão Melikşah concedeu-a como iqta a Dilmaçoğlu Mehmed Bey, que participara em Manzikerta (478/1085). O beylik reinou em Bitlis e Erzen entre 1085 e 1394.", "da296fec"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-06-20:0":{"b": ["Müslim b. Kureyş foi derrotado e morto em Kurzâhil por Süleyman Şah", "fc482adb"], "d": ["O ukaylida Müslim b. Kureyş, que queria fundar um Estado árabe unido e independente do Grande Sultão Seljúcida, combateu Süleyman Şah quando mandou saquear a região de Antioquia; derrotado no lugar de Kurzâhil, morreu (24 de Safer de 478 / 20 de junho de 1085) e foi sepultado junto à Porta de Alepo.", "9f4da840"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1086-01-01:0":{"b": ["O sultão Melikşah veio ao Cáucaso com um grande exército e submeteu totalmente a região", "79dd07e4"], "d": ["Depois de o rei Giorgi II ir a Isfahan e aceitar a suserania de Melikşah, Melikşah veio ainda uma vez, em 1086, ao Cáucaso com um grande exército e submeteu totalmente a região; à Geórgia Oriental fora dado o nome de 'Didi Turkoba' (Grande Turquia).", "a15ba581"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1095-01-01:0":{"b": ["Çaka Bey foi morto pelo genro Kılıcarslan I durante um banquete", "20cdcec9"], "d": ["Anna Comnena, que regista que Çaka Bey foi morto pelo genro Kılıcarslan durante um banquete, dá 1097 como data da morte, mas isto é errado se se tiver em conta o cerco de Malatya em 1096 e a queda de Niceia em 1097; a data da morte deve ser 1095 (m. 488/1095 [?]).", "9a287bc8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1097-01-01:0":{"b": ["Kılıcarslan I cercou Malatya, que os Danismendidas também queriam tomar; levantou o cerco quando os Cruzados se dirigiram a Niceia", "4f036db3"], "d": ["No inverno de 490/1097, Kılıcarslan marchou sobre Malatya, que os Danismendidas também cobiçavam, e cercou a cidade durante algum tempo; ao saber que os exércitos cruzados se tinham posto a caminho, dirigiu-se a Niceia e Niceia perdeu-se (junho de 1097).", "4282aef8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1100-07-01:0":{"b": ["Gümüştegin Gazi emboscou e fez prisioneiro Boemundo, príncipe de Antioquia, levou-o a Niksar e encarcerou-o", "c43f8a71"], "d": ["O danismendida Gümüştegin, que cercava Malatya, emboscou e derrotou as forças de Boemundo, príncipe de Antioquia, que viera em auxílio; Boemundo foi levado primeiro a Sivas e depois a Niksar, e encarcerado. Com a aproximação de Balduíno, conde de Edessa, o cerco foi levantado.", "543833c3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1101-06-23:0":{"b": ["Ancara foi entregue a Bizâncio em conformidade com o acordo entre os Cruzados e o imperador Aleixo Comneno", "d64f8668"], "d": ["Durante a Primeira Cruzada, Raimundo de Toulouse ocupara Ancara sem encontrar resistência séria e os Turcos da fortaleza tinham sido passados a fio de espada; em conformidade com o acordo entre os Cruzados e Aleixo Comneno, a cidade foi entregue ao Império Bizantino a 23 de junho de 1101. A administração bizantina durou cerca de vinte anos.", "f8a37732"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1101-08-01:0":{"b": ["Gümüştegin, Kılıcarslan I e Rıdvân desbarataram perto de Merzifon o exército cruzado lombardo", "f2703ea8"], "d": ["Os Cruzados lombardos, que tinham tomado Ancara para libertar Boemundo do cativeiro e avançavam na direção de Çankırı, foram desbaratados em agosto de 1101 perto de Merzifon pelo exército turco conjunto de 20.000 homens de Gümüştegin, Kılıcarslan I, Rıdvân, melik de Alepo, e Karaca, emir de Harran.", "ddaa77e1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1102-01-01:0":{"b": ["Sökmen recebeu Hasankeyf; fundou-se o ramo de Hısnıkeyfâ dos Artuquidas", "07e6f974"], "d": ["Com a morte de Kürboğa, emir de Mossul, Sökmen, que apoiava Mûsâ em Mossul, ajudou-o a derrotar Çökürmüş em troca da promessa de Mûsâ; quando Mûsâ foi morto, foi a Hasankeyf e recebeu a cidade. Assim ficou fundado o ramo de Hısnıkeyfâ dos Artuquidas (1102-1232).", "fccc615e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1103-01-01:0":{"b": ["Sökmen tomou Mardin após a morte do sobrinho Yâkūtî", "a5099d54"], "d": ["Mardin estava sob o domínio de Yâkūtî, sobrinho de Sökmen; aproveitando a desavença surgida com a sua morte, Sökmen tomou a cidade em 1103 e uniu a si grande parte da região de Diyarbekir.", "43484644"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1103-08-01:0":{"b": ["Kılıcarslan I derrotou Gümüştegin Gazi perto de Maraş", "15ec5217"], "d": ["A libertação de Boemundo por Gümüştegin em troca de resgate e o descontentamento de Kılıcarslan, que reclamava uma parte do resgate, indispuseram os dois aliados; Kılıcarslan derrotou Gümüştegin perto de Maraş.", "64f2df55"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-01-01:0":{"b": ["Gümüştegin Gazi morreu em Sivas; o filho Emîr Gazi tomou a chefia da dinastia danismendida", "75915f65"], "d": ["Com a morte de Gümüştegin, os Danismendidas sofreram um grande abalo; Malatya foi entregue aos Seljúcidas e surgiram disputas pelo trono entre os membros da dinastia. O filho mais velho, Emîr Gazi, assumiu o governo.", "f184fc73"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-05-07:0":{"b": ["Sökmen el-Kutbî e Çökürmüş derrotaram e fizeram prisioneiros, perto de Harran (Belih), Balduíno de Bourg, conde de Edessa, e Josselin", "5240d89c"], "d": ["Balduíno de Bourg, conde cruzado de Edessa, e Josselin, conde de Tel Bashir, foram derrotados e feitos prisioneiros pelos muçulmanos na batalha de Harran, a 9 de Şaban de 497 / 7 de maio de 1104. Sökmen, herói da vitória, adoeceu e morreu em outubro do mesmo ano.", "3b141414"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-10-01:0":{"b": ["Sökmen morreu; sucedeu-lhe o filho İbrâhim", "c40e3436"], "d": ["Sökmen, que adoeceu pouco depois da vitória de Harran, morreu em outubro de 1104; o filho İbrâhim sucedeu-lhe no ramo de Hısnıkeyfâ e, com a morte de İbrâhim em 1108, o irmão Dâvud tornou-se soberano artuquida.", "3fb73425"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1110-01-01:0":{"b": ["Muhammed Tapar desbaratou as forças georgianas e destruiu algumas cidades", "372cbcc6"], "d": ["Quando o rei David II lançou uma nova operação de invasão com um grande exército obtido dos Kipchaques e chegou até Gandja, o sultão seljúcida Muhammed Tapar marchou sobre a Geórgia, desbaratou as forças georgianas e destruiu algumas cidades (503/1110).", "f381ea2e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1110-01-01:1":{"b": ["Melikşah (Şâhinşah), enviado pelo Grande Sultão Seljúcida Muhammed Tapar, sentou-se em Konya no trono dos Seljúcidas da Anatólia", "b8987991"], "d": ["Depois da morte de Kılıcarslan I, perante os ataques de Aleixo Comneno, Muhammed Tapar enviou à Anatólia o filho mais velho de Kılıcarslan, Melikşah; Melikşah veio a Konya, sentou-se no trono e lutou seis anos com Aleixo.", "a8488c23"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1111-09-01:0":{"b": ["Sökmen el-Kutbî morreu em Bâlis, nas margens do Eufrates; sucedeu-lhe o filho Zahîrüddin İbrâhim", "510ea223"], "d": ["Sökmen, que se juntara ao exército de Mevdûd, filho de Altuntegin, enviado por Muhammed Tapar contra os Cruzados, deixou o exército quando a doença se agravou e morreu em Bâlis em setembro de 1111. O filho İbrâhim tornou-se chefe dos Ahlatşahs e permaneceu até 1126/1127.", "1ca34ea9"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1112-01-01:0":{"b": ["O artuquida Belek fez de Palu o seu centro e confiscou as terras dos Çubukoğulları", "624ab91f"], "d": ["Com o domínio de Harput por Belek b. Behrâm em 1112, Palu passou dos Çubukoğulları para o ramo de Harput dos Artuquidas; Belek fez dela a capital.", "2d7c33df"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1118-01-01:0":{"b": ["David IV começou a instalar na Geórgia 45.000 famílias kipchaques", "559894b0"], "d": ["David, chegando a acordo com 45.000 famílias kipchaques do Cáucaso do Norte e das estepes do Sul da Rus, trouxe-as para a Geórgia a partir de 1118 e, com a sua ajuda, pôs fim em 1121 ao domínio seljúcida em Tbilisi.", "d4bc7246"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1119-01-01:0":{"b": ["Emîr Gazi derrotou Rogério, príncipe de Antioquia, e fez uma incursão a Antioquia", "7bd138a2"], "d": ["Emîr Gazi fez em maio de 1119 uma incursão a Antioquia com um exército de 7000 homens e derrotou Rogério, príncipe de Antioquia, que marchava contra ele.", "c575e81b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1121-08-12:0":{"b": ["O rei georgiano David derrotou em Didgori o exército muçulmano; abriu-se o caminho para Tbilisi e Ani", "03b19a6d"], "d": ["Contra o grande exército que o rei georgiano David (David II no TDV; David IV Agaşenebeli nas fontes georgianas) obtivera dos Kipchaques, Tuğrul, melik de Gandja, enviado pelo sultão seljúcida do Iraque Mahmûd, o atabegue Gündoğdu, Dübeys b. Sadaka, o artuquida İlgazi e Dilmaçoğlu Togan Arslan foram derrotados perto de Didgori a 12 de agosto de 1121. Em seguida, os Georgianos ocuparam Tbilisi, que há séculos estava sob domínio islâmico, e fizeram dela capital.", "d186cc45"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1122-11-19:0":{"b": ["Necmeddin İlgazi morreu; os filhos reinaram, Süleyman em Meyyâfârikīn e Timurtaş em Mardin", "5e1a6c08"], "d": ["İlgazi, soberano artuquida de Mardin, que travara uma grande luta contra os Cruzados a partir de Alepo, adoeceu na campanha da fortaleza de Zerdenâ com o sobrinho Belek e Tuğtegin, atabegue de Damasco, e morreu a 19 de novembro de 1122. Dos filhos, Süleyman reinou em Meyyâfârikīn e Timurtaş em Mardin; o sobrinho Süleyman reinou em Alepo.", "6f429e0c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1124-01-01:0":{"b": ["Com a tomada da região de Malatya por Emîr Gazi, Elbistan passou para a administração danismendida", "5be35d74"], "d": ["Elbistan, destruída por um grande terramoto em 1114, passou em 1124 para a administração dos Danismendidas, quando o danismendida Emîr Gazi tomou a região de Malatya.", "a81725b1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1129-01-01:0":{"b": ["Os Danismendidas passaram a controlar a região de Kastamonu", "e1be4a42"], "d": ["Em 1129, Ancara, Çankırı, Kastamonu e as costas do mar Negro passaram para o controlo de Emîr Gazi; a região de Kastamonu foi incorporada nas fronteiras danismendidas.", "df047345"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1129-01-01:1":{"b": ["Os Danismendidas passaram a controlar Çankırı, Kastamonu e as costas do mar Negro", "db4c771a"], "d": ["Os Danismendidas, o Estado mais poderoso da Anatólia no tempo de Emîr Gazi, passaram a controlar em 1129 Ancara, Çankırı, Kastamonu e as costas do mar Negro; a maior parte das terras que iam de Malatya ao Sakarya passou para a administração danismendida.", "1d1edb93"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1130-01-01:0":{"b": ["O Şeddâdî Fazl IV morreu na guerra empreendida por Kurti, emir de Erzen, para recuperar Dvin", "d8a7ad18"], "d": ["Fazl IV, que depois do cerco de Ani a recuperou e anexou Gandja e Dvin aos seus territórios, morreu em 524/1130 na guerra empreendida por Kurti, emir de Erzen, para recuperar Dvin; sucedeu-lhe o irmão, mas o filho Mahmûd veio a Ani e tomou o governo.", "7810bf30"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1131-01-01:0":{"b": ["O saltuquida Ziyâeddin Gazi derrotou o rei georgiano Ivane", "5ba067d6"], "d": ["Ziyâeddin Gazi, que participou na campanha organizada contra os Georgianos quando, em 1126, passaram İspir e Pasinler e chegaram a Oltu, derrotou em 1131 o rei Ivane.", "d91b0282"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1132-01-01:0":{"b": ["Com a morte de Ziyâeddin Gazi, o sobrinho İzzeddin Saltuk II tomou a chefia do beylik saltuquida", "726791ef"], "d": ["Ziyâeddin Gazi, parente do artuquida Timurtaş, morreu em 526/1132; o sobrinho İzzeddin Saltuk II tomou a chefia do beylik.", "a7412435"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1134-01-01:0":{"b": ["Emîr Gazi morreu; o filho mais velho, Melik Muhammed, foi proclamado soberano em Malatya", "1cf04ea6"], "d": ["Emîr Gazi (Melik Gazi), o soberano mais influente da Anatólia, morreu em 528/1134. O diploma de investidura, o cetro de ouro e os presentes enviados pelo califa abássida Müsterşid-Billâh e pelo sultão Sencer foram entregues a Melik Muhammed, que foi proclamado soberano em Malatya. Os irmãos Aynüddevle e Yağan revoltaram-se.", "e39192f6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:0":{"b": ["O sultão Mesud tomou Sivas; tomou Ancara, Çankırı e Kastamonu aos Danismendidas e deu-as ao filho Şâhinşah", "cc439683"], "d": ["Quando, com a morte de Melik Muhammed, os Danismendidas se dividiram em três ramos, o sultão seljúcida da Anatólia Mesud I marchou sobre Sivas, tomou a cidade e nomeou o filho mais novo, Şâhinşah, governador de Ancara, Çankırı e Kastamonu.", "6b775908"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:1":{"b": ["O sultão Mesud tomou Kastamonu aos Danismendidas e deixou-a ao filho Şâhinşah", "ae895779"], "d": ["O sultão Mesud, que tomou Sivas, deu ao filho mais novo, Şâhinşah, o governo também de Kastamonu, juntamente com Ancara e Çankırı.", "f8cfb811"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:2":{"b": ["O sultão Mesud tomou Çankırı aos Danismendidas e deixou-a ao filho Şâhinşah", "8047e8a8"], "d": ["Mesud I, aproveitando as disputas pelo trono danismendidas, apoderou-se de Ancara, Çankırı e Kastamonu e deixou a administração destas três cidades ao filho Şâhinşah.", "07d66793"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1143-06-17:0":{"b": ["O sultão Mesud iniciou o cerco de Malatya, que durou três meses; sem resultado, levantou-o a 14 de setembro de 1143", "4c2d2d2b"], "d": ["O sultão Mesud, que tomara Sivas da dinastia dividida em três com a morte do danismendida Melik Muhammed (537/1142), cercou Malatya a 1 de Zilhicce de 537 / 17 de junho de 1143; não tendo obtido resultado durante três meses, levantou o cerco a 2 de Rebîülevvel de 538 / 14 de setembro de 1143 e regressou a Konya.", "2dc53da5"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1143-12-06:0":{"b": ["Melik Muhammed morreu em Kayseri; os Danismendidas dividiram-se nos ramos de Sivas, Malatya e Kayseri", "1ee92ff3"], "d": ["Após a morte de Melik Muhammed em Kayseri, a 6 de dezembro de 1143 segundo Miguel o Sírio, o irmão Yağıbasan estabeleceu o seu domínio em Sivas, o filho Zünnûn em Kayseri e Aynüddevle em Malatya e Elbistan; os Danismendidas, divididos em três ramos, entraram numa luta destrutiva entre si.", "b07a9299"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1144-08-01:0":{"b": ["Dâvud, soberano artuquida de Hısnıkeyfâ, morreu; sucedeu-lhe o filho Fahreddin Kara Arslan", "4782f166"], "d": ["Dâvud, que se aliara ao artuquida de Mardin Timurtaş contra Zengî, atabegue de Mossul, morreu a 1 de agosto de 1144; o filho Fahreddin Kara Arslan entendeu-se com o sultão seljúcida da Anatólia Mesud I contra Zengî.", "48a2c46f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1153-03-29:0":{"b": ["Na sequência de uma conspiração armada pelo emir de Ani Fahreddin Şeddâd, o exército saltuquida foi derrotado pelo rei georgiano Dimitri; İzzeddin Saltuk foi feito prisioneiro", "f936d922"], "d": ["Şeddâd, emir de Ani, que pedira a filha de Saltuk e fora recusado, fez saber que queria vender a cidade a Saltuk e entrar ao seu serviço; quando Saltuk veio com o seu exército, avisou o rei georgiano. O exército saltuquida foi gravemente derrotado pelo rei Dimitri, Saltuk foi feito prisioneiro e libertou-se por um resgate de 100.000 dinares.", "0d47e21f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1155-01-01:0":{"b": ["Com a morte do sultão Mesud, foram dados ao genro danismendida Yağıbasan Amásia, Ancara e a Capadócia", "295fac37"], "d": ["Quando, com a morte de Mesud, Kılıcarslan II subiu ao trono (1155), dos dois genros de Mesud pertencentes à dinastia danismendida foram dados a Yağıbasan Amásia, Ancara e a Capadócia, e a Zünnûn as cidades de Kayseri e Sivas; os irmãos, reclamando direitos ao trono, revoltaram-se.", "b6540bd8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1155-03-07:0":{"b": ["Fahreddin Şeddâd foi feito prisioneiro pelos Georgianos; em Ani, com a revolta das monjas arménias, foi substituído pelo irmão Fazl V", "2e64eb02"], "d": ["Depois de o rei georgiano Dimitri derrotar o exército saltuquida, as monjas arménias, que reagiram ao comportamento de Fahreddin Şeddâd, revoltaram-se e puseram em Ani, em lugar de Saltuk, o irmão Fazl V (550/1155); o emirado de Fazl V terminou em 1161 com a entrega de Ani ao rei georgiano.", "56cd50fc"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1161-01-01:0":{"b": ["O rei georgiano Giorgi apoderou-se de Ani", "8081e228"], "d": ["O rei georgiano Giorgi, depois de infligir em 1154 uma pesada derrota ao soberano saltuquida İzzeddin Saltuk, apoderou-se em 1161 da cidade de Ani; o emirado şeddâdî terminou quando o clero se revoltou e entregou a cidade ao rei georgiano.", "357c7a97"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1161-08-01:0":{"b": ["Sökmen, Ahlatşah, İzzeddin Saltuk e Devletşah cercaram Ani; com o abandono do acampamento por Saltuk, os muçulmanos foram derrotados", "d651d8fe"], "d": ["Depois de o rei georgiano Giorgi se apoderar de Ani, Sökmen II, xá de Ahlat, İzzeddin Saltuk II, Fahrüddevle Devletşah, bey de Erzen e Bitlis, e outros emires turcos uniram-se e cercaram a cidade. Com a chegada do rei Giorgi, Saltuk deixou o acampamento sem avisar os outros beys; os muçulmanos foram derrotados, muitos foram mortos e 9000 foram feitos prisioneiros.", "2345b0e8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1162-01-01:0":{"b": ["Os Georgianos invadiram Dvin", "e8f2a041"], "d": ["Os Georgianos, que tomaram Ani em 1161, invadiram no ano seguinte Kars e Dvin; depois, a campanha conjunta dos beys muçulmanos derrotou a Geórgia em 1163.", "b28be1b3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1162-01-01:1":{"b": ["Os Georgianos invadiram Kars e Dvin", "a7388ca5"], "d": ["Os Georgianos, depois de tomarem Ani em 1161, invadiram no ano seguinte Kars e Dvin; após matarem grande número de muçulmanos e queimarem mesquitas e casas, regressaram a Tbilisi.", "2a892f7b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1163-01-01:0":{"b": ["O exército conjunto dos beys muçulmanos derrotou o rei georgiano Giorgi; Giorgi foi obrigado a restituir Ani", "346b30b1"], "d": ["O grande exército formado por iniciativa do sultão Tuğrul e do atabegue Şemseddin İldeniz infligiu em 558/1163 uma pesada derrota ao rei da Geórgia Giorgi, e Giorgi foi obrigado a restituir Ani.", "a59e4ef4"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1163-07-01:0":{"b": ["O exército aliado dos beys turcos derrotou o exército georgiano perto da fortaleza de Lukri", "58d3a0d5"], "d": ["Mais de 50.000 mujahidin, entre os quais İldeniz, Sökmen, İzzeddin Saltuk, İbn Aksungur e Arslanşah, invadiram a Geórgia; em julho de 1163 os Georgianos foram derrotados nas imediações da fortaleza de Lukri, o rei Giorgi fugiu abandonando a bagagem e foi obrigado a restituir Ani.", "7ac70a0b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1164-08-04:0":{"b": ["Yağıbasan, melik de Sivas, morreu em Çankırı; começou nova luta entre os Danismendidas", "59448eb7"], "d": ["Yağıbasan, que fora a Çankırı obter ajuda do melik seljúcida Şâhinşah contra Kılıcarslan II, morreu ali a 4 de agosto de 1164; foi sepultado no cemitério da madraça que mandara construir em Niksar. É controverso quem lhe sucedeu depois da morte.", "0efd18be"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1165-01-01:0":{"b": ["Kılıcarslan II tomou aos Danismendidas a região de Darende e Gedük (Şarkışla)", "917ee1e6"], "d": ["Kılıcarslan II, aproveitando a luta interna da dinastia depois da morte de Yağıbasan, anexou em 1165 a região de Elbistan, Darende e Gedük.", "7f39a47e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1168-01-01:0":{"b": ["İzzeddin Saltuk II morreu; o filho Nâsırüddin Muhammed subiu ao trono", "40c0ab87"], "d": ["Depois de İzzeddin Saltuk, que morreu em 563/1168, o filho Nâsırüddin Muhammed subiu ao trono saltuquida; a Grande Mesquita de Erzurum foi construída em 1179 em seu nome.", "18b4b682"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1170-09-14:0":{"b": ["Kılıcarslan II mandou reconstruir Aksaray e fez dela, com o nome de Dârüzzafer, uma base militar", "e0f2e591"], "d": ["Kılıcarslan II fez da cidade de Aksaray, que em 566 (1170-71) mandou reconstruir e a que deu o nome de Dârüzzafer, uma base militar; mandando construir mesquitas, zâviyes, madraças e um caravançarai, instalou ali os gazis e sábios que trouxera do Azerbaijão.", "0ddd80f6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1172-01-01:0":{"b": ["A população de Sivas revoltou-se e matou İsmâil; com o apoio de Nûreddin Zengî, Zünnûn subiu ao trono danismendida em Sivas", "ab96caf2"], "d": ["Em Sivas, a população revoltou-se contra İsmâil, devido à fome e porque não distribuía as reservas dos armazéns; İsmâil e a esposa foram mortos. Os notáveis da cidade convidaram Zünnûn, que se refugiara junto de Nûreddin; Zünnûn, com a ajuda de Nûreddin, subiu ao trono danismendida em Sivas em 567/1172, mas pouco depois fugiu para Niksar sob a pressão de Kılıcarslan II.", "374133e0"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1175-01-01:0":{"b": ["Kılıcarslan II tomou Niksar aos Danismendidas e anexou-a ao domínio seljúcida", "e49e3971"], "d": ["Kılıcarslan II conquistou no verão de 1175 Sivas, Niksar, Comana, Tokat e outros territórios danismendidas; um dos centros danismendidas, Niksar, onde Yağıbasan está sepultado no cemitério da sua madraça, passou para as mãos dos Seljúcidas.", "aa58d509"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1175-01-01:1":{"b": ["Kılıcarslan II tomou Tokat à província danismendida desaparecida e anexou-a ao domínio seljúcida", "1894c403"], "d": ["Depois da morte do atabegue Nûreddin Mahmud Zengî em 569/1174, Kılıcarslan II, desrespeitando as condições do tratado, conquistou no verão de 1175 Sivas, Niksar, Comana, Tokat e outros territórios danismendidas; Zünnûn e Şâhinşah refugiaram-se em Bizâncio e o ramo de Sivas dos Danismendidas desapareceu.", "dbfcc454"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1180-05-28:0":{"b": ["Kılıcarslan II tomou a Bizâncio Uluborlu, Kütahya e a região de Dorileia (Eskişehir)", "807be33d"], "d": ["Como o imperador Manuel não cumpriu as condições do tratado e não mandou demolir a fortaleza de Dorileia, Kılıcarslan II mandou devastar em 573/1177 o vale do Meandro; Uluborlu, Kütahya e Dorileia passaram em 576/1180 para o domínio seljúcida.", "60e80418"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1184-01-01:0":{"b": ["O rei georgiano David marchou sobre Erzurum; regressou perante a resistência da população", "07419985"], "d": ["O rei georgiano David marchou sobre Erzurum, derrotou Nâsırüddin Muhammed e fê-lo retirar-se para a cidade; perante a coragem e a determinação do povo turco, saqueou os arredores e recuou (580/1184-85).", "85711193"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1184-04-14:0":{"b": ["Kılıcarslan II repartiu o país entre os seus onze filhos", "b1ee119d"], "d": ["Na velhice, Kılıcarslan II repartiu o país entre os filhos; Tokat coube ao filho mais velho, Rükneddin Süleyman Şah. O país seljúcida foi dividido em onze partes.", "09e83cd3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1185-01-01:0":{"b": ["O governador Isaac Ducas Comneno revoltou-se contra o imperador Andrónico e proclamou a independência de Chipre", "445f5db0"], "d": ["Quando Chipre continuava a ser uma província de Bizâncio, o governador Isaac Ducas Comneno revoltou-se contra o imperador Andrónico Comneno e proclamou a independência, e Chipre saiu em 1185 do domínio bizantino.", "00f3ca97"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1185-07-10:0":{"b": ["Sökmen II (Xá-i Ermen), Ahlatşah, morreu durante o cerco de Mossul", "f492f6ba"], "d": ["Quando Saladino cercou de novo Mossul em 1185, chegou a notícia de que o seu aliado Sökmen morrera (9 de Rebîülâhir de 581 / 10 de julho de 1185). Saladino, não regressando de mãos vazias da campanha de Ahlat, tomou Meyyâfârikīn, que ficara sem soberano.", "2692f19a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1190-05-17:0":{"b": ["O exército cruzado sob o comando de Frederico Barba-Ruiva derrotou o exército seljúcida e entrou em Konya", "f1f901b6"], "d": ["Barba-Ruiva, imperador alemão, que passou de Galípoli à Anatólia em março de 1190, entrou perto de Uluborlu em território seljúcida e, a 17 de maio de 1190, derrotou o exército de Kutbüddin Melikşah e dos outros meliks seljúcidas e entrou em Konya, capital esvaziada pelo sultão.", "0d30744a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1192-08-26:0":{"b": ["Kılıcarslan II morreu durante o cerco de Aksaray; sucedeu-lhe Keyhusrev I", "083f9fae"], "d": ["Kılıcarslan II, que cercava Aksaray com Gıyâseddin Keyhusrev durante a luta com os filhos, adoeceu e morreu a 15 de Şaban de 588 / 26 de agosto de 1192; Keyhusrev subiu ao trono em Konya.", "1f04ea47"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1193-05-18:0":{"b": ["O Ahlatşah Begtemür foi morto pelo genro Hezâr Dînârî", "12078a3c"], "d": ["Cerca de dois meses e meio depois da morte de Saladino, Bedreddin Aksungur Hezâr Dînârî, genro de Begtemür e um dos comandantes de Seyfeddin Begtemür, matou-o a 18 de maio de 1193. Hezâr Dînârî encarcerou o filho de sete anos de Begtemür e a esposa numa fortaleza da região de Erzâs.", "e0117ffd"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1196-11-24:0":{"b": ["Gıyâseddin Keyhusrev cedeu o trono ao irmão Rükneddin Süleyman Şah e partiu para o exílio", "557c281e"], "d": ["Keyhusrev I, que lutava com os irmãos, foi obrigado a ceder o trono a Süleyman Şah II (Rükneddin) (593/1196) e deixou Konya; Süleyman Şah tomou os territórios dos irmãos e estabeleceu a unidade do país.", "129847ea"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1197-01-01:0":{"b": ["Amaury de Lusignan assumiu o título de rei de Chipre; no mesmo ano foi reconhecido também como rei de Jerusalém pelos Cruzados de Acre", "c38ed247"], "d": ["Amaury assumiu o título de rei em 1197 e foi reconhecido no mesmo ano como rei de Jerusalém pelos Cruzados de Acre; o Reino de Chipre tornou-se a base naval do Oriente cruzado.", "1d28312c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1199-01-06:0":{"b": ["Levon cingiu na catedral de Tarso a coroa enviada por Henrique VI, imperador do Sacro Império Romano-Germânico, e tornou-se o primeiro rei do Reino Arménio da Cilícia", "99ceea3a"], "d": ["O príncipe rupénida Levon cingiu na catedral de Tarso a coroa enviada por Henrique VI, imperador do Sacro Império Romano-Germânico, e foi consagrado pelo representante do papa; o principado rupénida transformou-se no Reino Arménio da Cilícia.", "05fe804d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1201-06-23:0":{"b": ["Süleyman Şah II tomou Malatya ao irmão Muizzüddin Kayser Şah", "fff1df20"], "d": ["Süleyman Şah, que se moveu contra o irmão Muizzüddin Kayser Şah, melik de Malatya, que resistia a submeter-se a ele, tomou a cidade a 19 de Ramazan de 597 / 23 de junho de 1201.", "65e22bbb"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1202-01-01:0":{"b": ["Campanha de Süleyman Şah II à Geórgia: os Seljúcidas, surpreendidos no acampamento por um ataque georgiano, sofreram graves perdas; Behram Şah, bey mengücüquida de Erzincan, foi feito prisioneiro", "3ee9e922"], "d": ["Süleyman Şah II, que partiu em campanha em 1202 contra os Georgianos que atacavam as terras turcas, foi atacado enquanto descansava no acampamento por um ataque georgiano e sofreu graves perdas; entre os prisioneiros estava também Behram Şah, bey mengücüquida de Erzincan.", "4151b3d2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1202-06-25:0":{"b": ["Süleyman Şah II pôs fim à dinastia saltuquida e concedeu Erzurum como iqta ao irmão Tuğrul Şah", "37a63791"], "d": ["O sultão seljúcida da Anatólia Süleyman Şah II, que veio a Erzurum durante a campanha da Geórgia, encarcerou Melikşah e aboliu o beylik saltuquida (2 de Şevval de 598 / 25 de junho de 1202) e deu Erzurum ao irmão Mugīsüddin Tuğrul Şah, melik de Elbistan. Os territórios saltuquidas permaneceram nas mãos de Tuğrul Şah até 1225.", "6d717627"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1204-01-01:0":{"b": ["Süleyman Şah II morreu; subiu ao trono o filho menor Kılıcarslan III", "838d74dd"], "d": ["Süleyman Şah II, que não obtivera resultado da campanha da Geórgia de 1202, morreu no caminho em 1204, quando marchava para uma segunda campanha da Geórgia (600/1204). Sucedeu-lhe o filho menor Kılıcarslan III; durante o seu reinado de sete ou oito meses foi conquistada a região de Isparta.", "6d8da37d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1204-08-29:0":{"b": ["Os Georgianos fizeram uma incursão ao Azerbaijão, entraram no país dos Ahlatşahs e saquearam a região de Manzikerta e Erciş", "beb13519"], "d": ["Os Georgianos, depois de uma incursão bem-sucedida ao Azerbaijão em 601/1204-05, entraram no país dos Ahlatşahs e avançaram até Manzikerta e depois até aos lados de Erciş, queimando e destruindo tudo; não saiu nenhum exército ao seu encontro.", "5c1e0212"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1205-03-01:0":{"b": ["Gıyâseddin Keyhusrev I foi a Konya e sentou-se pela segunda vez no trono dos Seljúcidas da Anatólia", "f6332e53"], "d": ["Keyhusrev, que fora obrigado a ir para a fortaleza do sogro na região de Trebizonda por causa da ocupação de Constantinopla pelos Cruzados (referida como fevereiro de 1204), veio à cidade durante a menoridade de Kılıcarslan III e sentou-se pela segunda vez no trono (Receb de 601 / março de 1205).", "59c0db32"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1207-01-01:0":{"b": ["Keyhusrev I tomou a região de Denizli", "47cabadd"], "d": ["No período do segundo sultanato de Gıyâseddin Keyhusrev I (1205-1211), as regiões de Denizli e Antália foram tomadas (603/1207); Antália foi tomada a 5 de março de 1207.", "190b906c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1211-06-01:0":{"b": ["Keyhusrev I morreu na batalha contra o exército bizantino perto de Alaşehir; o exército bizantino também sofreu graves perdas", "fdac0ce7"], "d": ["Keyhusrev morreu na batalha que travou contra o exército bizantino perto de Alaşehir; o exército bizantino também sofreu perdas muito graves. O corpo foi primeiro sepultado em Alaşehir e depois levado a Konya e enterrado no Mausoléu dos Sultões, junto à Mesquita de Alâeddin (finais de junho de 1211).", "fd58f9bc"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1211-06-15:0":{"b": ["Os dignitários do Estado reuniram-se em Konya e decidiram entronizar o melik de Malatya, İzzeddin Keykâvus; Keykâvus I foi proclamado sultão em Kayseri", "f80be390"], "d": ["Com a morte de Keyhusrev I (608/1211), os dignitários do Estado decidiram, por ser o filho mais velho, entronizar o melik de Malatya, İzzeddin Keykâvus, e enviaram um mensageiro para que viesse a Kayseri; o irmão Alâeddin Keykubad não reconheceu o seu sultanato.", "09e0f400"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1212-01-01:0":{"b": ["Keykubad não reconheceu o sultanato do irmão mais velho Keykâvus I e revoltou-se; fechou-se na fortaleza de Ancara e rendeu-se", "13cc17e2"], "d": ["Alâeddin Keykubad, que se revoltou contra İzzeddin Keykâvus, proclamado sultão em Kayseri com a morte do pai, cercou Kayseri com o rei arménio Leão e com o tio Tuğrul Şah, melik de Erzurum; não obtendo resultado, retirou-se para a fortaleza de Ancara e, esgotadas as provisões, rendeu-se com a condição de que não fosse causado dano a ele nem à população (608/1212).", "7b48bb7a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:0":{"b": ["İzzeddin Keykâvus I morreu em Viranşehir, perto de Malatya, nos preparativos para uma campanha a Alepo", "61f16209"], "d": ["İzzeddin Keykâvus, que marchou sobre Alepo, onde, depois da morte (1216) do eyúbida el-Melikü'z-Zâhir de Alepo, subira ao trono o seu filho de tenra idade, aliou-se ao artuquida de Âmid Nâsırüddin Mahmud e a Kökböri, senhor de Arbil; adoeceu quando chegou a Malatya e morreu em Viranşehir, perto de Malatya (Şevval de 616 / janeiro de 1220).", "a8264a2f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:1":{"b": ["Alâeddin Keykubad foi libertado da prisão e proclamado soberano em Sivas", "2e697d48"], "d": ["Keykubad, libertado da prisão com a morte de İzzeddin Keykâvus I, foi proclamado sultão em Sivas (616/1220). Contra a invasão mongol, mandou cercar de muralhas Konya, Sivas e Kayseri.", "c731bdd7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:2":{"b": ["Os Mongóis derrotaram pela primeira vez os Georgianos", "b869830b"], "d": ["Os Mongóis derrotaram os Georgianos pela primeira vez em 1220 e entraram na Geórgia em 1231.", "7f39fa9d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1225-01-13:0":{"b": ["O rei arménio Hetum pediu a paz a Keykubad; fez-se a paz em troca de um tributo anual de 40.000 peças de ouro e de auxílio militar", "0d137195"], "d": ["Em virtude das queixas dos comerciantes contra os Francos e os Arménios, Keykubad declarou em 622 (1225) guerra aos Arménios e aos Cruzados; o rei arménio Hetum enviou um emissário e pediu a paz. O rei pagaria todos os anos ao sultão 40.000 peças de ouro e, quando o sultão quisesse, enviaria 1000 cavaleiros e 500 engenheiros de máquinas de guerra.", "9d0f1a8e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1228-01-01:0":{"b": ["Alâeddin Keykubad tomou Erzincan e eliminou o ramo de Erzincan dos Mengücükoğulları", "edfdc566"], "d": ["Keykubad, que agiu contra os Mengücükoğulları, desejosos de independência, anexou em 625/1228 Erzincan às terras dos Seljúcidas da Anatólia; ao melik Muzafferüddin, da dinastia, senhor de Şarkîkarahisar, foram dados Kırşehir como iqta e Efsûs como propriedade, juntamente com alguns lugares.", "ba31e942"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1228-01-01:1":{"b": ["Terminou o governo do melik Muzafferüddin, soberano do ramo de Şarkîkarahisar dos Mengücükoğulları; Kırşehir foi-lhe dada como iqta", "1ec2fd55"], "d": ["Alâeddin Keykubad eliminou em 1228 o ramo de Erzincan dos Mengücükoğulları; ao melik Muzafferüddin, da dinastia, senhor de Şarkîkarahisar, foram dados Kırşehir como iqta e a vila de Efsûs como propriedade, juntamente com alguns lugares.", "e17ab2ba"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1232-01-01:0":{"b": ["Os exércitos seljúcidas tomaram algumas fortalezas na Geórgia; a rainha Rusudan propôs a paz e aceitou prometer a filha Tamara a Keyhusrev II", "2a057d64"], "d": ["No tempo de Alâeddin Keykubad I, em 1232, Kemâleddin Kâmyâr e Mübârizüddin Çavlı fizeram uma campanha à Geórgia e tomaram algumas fortalezas; a rainha Rusudan, que não conseguiu resistir ao exército seljúcida, propôs a paz e aceitou prometer a filha Tamara a Gıyâseddin Keyhusrev II, filho de Keykubad.", "c8ce3253"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1234-01-01:0":{"b": ["O ramo de Harput passou para as mãos dos Seljúcidas da Anatólia", "f2572ad0"], "d": ["Alâeddin Keykubad tomou Harput em 631/1234 contra a marcha dos aiúbidas à Anatólia; terminou o domínio do ramo artuquida de Harput (depois de Kösedağ, a cidade passou para as mãos dos Ilcânidas).", "b0bea54d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1236-01-01:0":{"b": ["Os Mongóis ocuparam de novo a Geórgia e enviaram os notáveis georgianos para a Mongólia", "245ae81a"], "d": ["Quando os Mongóis ocuparam de novo a Geórgia em 633/1235-36, enviaram os notáveis georgianos para a Mongólia; estes permaneceram ali durante anos. Os Mongóis utilizaram grande número de soldados georgianos nas campanhas.", "159ea654"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1237-05-31:0":{"b": ["Alâeddin Keykubad I morreu envenenado por carne de caça; sucedeu-lhe o filho Gıyâseddin Keyhusrev II", "5d74714c"], "d": ["Keykubad, que encerrou a época de ascensão dos Seljúcidas, morreu no dia seguinte, envenenado pela carne de caça que comeu no banquete dado aos emissários na festa do Ramazan (4 de Şevval de 634 / 31 de maio de 1237); em vez do herdeiro İzzeddin Kılıcarslan, Keyhusrev II subiu ao trono pelo empenho dos estadistas.", "7b42c0c6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1239-01-01:0":{"b": ["O exército mongol sob o comando de Curmagan Noyan tomou e destruiu Kars durante a campanha da Geórgia", "f510f715"], "d": ["Em 636/1239, o exército mongol sob o comando de Curmagan Noyan tomou e destruiu Kars durante a campanha da Geórgia; a cidade permaneceu sob a administração dos Ilcânidas até 1336.", "38d144da"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1242-01-01:0":{"b": ["O comandante mongol Baycu Noyan tomou Erzurum e passou a população a fio de espada", "118b9e3a"], "d": ["Baycu Noyan, comandante mongol no Azerbaijão, aproveitando o enfraquecimento dos Seljúcidas com a revolta dos Babaîs, tomou Erzurum no final de 1242, passou a população a fio de espada e regressou a Mugan para atacar de novo a Anatólia na primavera.", "dcfa189c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:0":{"b": ["Os Mongóis, que ocuparam a Anatólia após Kösedağ, tomaram Amásia e administraram-na com governadores mongóis", "3b39a0ad"], "d": ["Os Mongóis, que ocuparam a Anatólia depois da batalha de Kösedağ de 1243, tomaram Amásia, e a cidade passou a ser administrada por governadores mongóis.", "a9d1a1e2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:1":{"b": ["Depois da derrota de Kösedağ, Kayseri caiu nas mãos dos Mongóis após uma resistência de dez dias", "5600cbe9"], "d": ["Após a batalha de Kösedağ (1243), Kayseri caiu nas mãos dos Mongóis depois de uma resistência de dez dias e sofreu grande destruição.", "924187ac"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:2":{"b": ["A rainha Rusudan aceitou pagar tributo aos Mongóis e reconheceu oficialmente o Grande Cã como suserano", "99d19c31"], "d": ["A rainha Rusudan, ao compreender que não poderia com os Mongóis, aceitou submeter-se pagando tributo e reconheceu oficialmente em 1243 o Grande Cã como suserano. Depois da morte de Rusudan, os Mongóis dividiram o Cáucaso em oito províncias.", "c61c6116"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:3":{"b": ["O Emirado de Tokat foi dado a Muînüddin Süleyman Pervâne pelos Ilcânidas depois de Kösedağ", "f2938da6"], "d": ["Os Ilcânidas, que depois da batalha de Kösedağ passaram a dominar o Estado Seljúcida da Anatólia, deram o Emirado de Tokat a Muînüddin Süleyman Pervâne; em 1276, Tokat estava sob a administração de Nûreddin Cibrîl.", "d931de12"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1244-01-01:0":{"b": ["O comandante mongol Yasavur Noyan tomou Malatya por pouco tempo", "98759910"], "d": ["Os Mongóis não obtiveram resultado das primeiras tentativas contra Malatya depois da vitória de Kösedağ (1243); Yasavur Noyan tomou a cidade por pouco tempo em 1244 e em 1258 foi destruída por Baycu Noyan.", "78c903ae"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1246-01-01:0":{"b": ["Os estadistas proclamaram sultão, na aldeia de Altuntaş, em Akşehir, o melik de Uluborlu İzzeddin Keykâvus", "20d6f3e7"], "d": ["Os estadistas proclamaram sultão, na aldeia de Altuntaş, em Akşehir, İzzeddin Keykâvus, que era melik de Uluborlu (Borgulu) na altura da morte de Gıyâseddin Keyhusrev II (643/1246).", "e7c6a924"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1247-01-01:0":{"b": ["O rei Hetum I enviou o irmão Sempad a Caracórum e formou com o irmão de Möngke Cã uma aliança contra os Mamelucos", "7413b5e5"], "d": ["O rei Hetum I, enviando o irmão Sempad a Caracórum, iniciou a aliança formal com o Império Mongol.", "769d4bcf"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1251-01-01:0":{"b": ["Os dois Davids, regressados da Mongólia depois da subida ao trono de Mengü Cã, reinaram juntos na Geórgia", "f1640157"], "d": ["Depois da subida ao trono do Grande Cã mongol Mengü Cã (1251), os dois Georgianos de nome David, por ele incumbidos, regressaram de Caracórum ao seu país e reinaram juntos; depois Batu Cã e Hulagu procuraram estabelecer o domínio na Geórgia.", "96249933"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1255-01-01:0":{"b": ["Kılıcarslan IV foi derrotado por Keykâvus II na batalha de Ahmedhisarı, perto de Kayseri", "edac92e9"], "d": ["Depois da morte de Celâleddin Karatay, Kılıcarslan proclamou-se sultão independente em Kayseri (652/1254); no ano seguinte, na batalha travada no lugar chamado Ahmedhisarı, perto de Kayseri, foi derrotado por Keykâvus.", "d64649d2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1257-01-01:0":{"b": ["Os Mongóis, sob o comando de Yaşmut, tomaram Meyyâfârikīn após longo cerco; Mardin resistiu oito meses", "c2328a27"], "d": ["Hulagu, ao partir em 1257 para a campanha da Síria, encarregou uma unidade sob o comando de Yaşmut de tomar Mardin e Meyyâfârikīn; Meyyâfârikīn caiu após longo cerco e a fortificada Mardin resistiu mais de oito meses.", "18f326a7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1257-03-05:0":{"b": ["Kılıcarslan IV, trazido de Burgulu a Konya, foi posto sozinho no trono seljúcida", "cb3eced9"], "d": ["Depois da derrota de Sultanhanı (654/1256), Kılıcarslan IV, que estava em Burgulu (Uluborlu), foi trazido a Konya e posto sozinho no trono seljúcida a 16 de Safer de 655 / 5 de março de 1257; quando Keykâvus II veio a Konya a 14 de Rebîülâhir de 655 / 1 de maio de 1257, enviou contra Kılıcarslan o seu comandante Ali Bahadır.", "32f17269"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1258-01-08:0":{"b": ["Keykâvus II tomou sob o seu domínio Malatya, Sivas, Tokat e Amásia; Kılıcarslan retirou-se para Erzincan", "d4834ad1"], "d": ["Quando İzzeddin Keykâvus, com a ajuda dos seus célebres comandantes, pôs sob o seu domínio Malatya, Sivas, Tokat e Amásia, Kılıcarslan IV foi obrigado a retirar-se para Erzincan (656/1258); em seguida, por decreto de Mengü Cã, o país foi dividido em dois (657/1259).", "5954d32b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1259-01-01:0":{"b": ["Por decreto de Mengü Cã, o país seljúcida foi dividido em dois entre Keykâvus II e Kılıcarslan IV", "4dacbe83"], "d": ["Depois da partida de Baycu da Anatólia, Keykâvus II foi de novo entronizado em Konya (1 de maio de 1257); por decreto de Mengü Cã, o país foi dividido entre Keykâvus e Kılıcarslan. Keykâvus, que não aceitava o domínio mongol, refugiou-se em Bizâncio em 660/1262.", "c7df29bf"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1260-01-01:0":{"b": ["Kara Arslan, soberano artuquida de Mardin, aceitou o domínio ilcânida", "c6b7b1a6"], "d": ["Mardin sofreu fome e peste durante o cerco mongol de mais de 8 meses; Kara Arslan, que assumiu o governo com a morte de Necmeddin Gazi, reconheceu o domínio mongol em troca da devolução de Dârâ, Habur, Nusaybin e Re'sülayn aos Artuquidas e foi confirmado por Hulagu como senhor de Mardin em 659/1261.", "ff8d14de"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1260-01-01:1":{"b": ["Quando os Mongóis foram derrotados pelos Mamelucos e se retiraram para a Pérsia, os Mamelucos atacaram a Cilícia e devastaram o país", "505db4aa"], "d": ["Quando os Mongóis ilcânidas, derrotados pelos Mamelucos, se retiraram para a Pérsia, os Mamelucos atacaram a Cilícia e devastaram o país; este é o início efetivo dos ataques mamelucos.", "89ccf21b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:0":{"b": ["Muînüddin Pervâne mandou os Mongóis matar Kılıcarslan IV e pôs no trono o filho menor Keyhusrev III", "27f0dc7a"], "d": ["Quando Kılıcarslan foi forçado a aceitar que Sinope lhe fosse dada como propriedade, o vizir Muînüddin Pervâne mandou os Mongóis matá-lo (664/1266) e pôs no seu lugar o filho de tenra idade Keyhusrev III; Pervâne tornou-se senhor sem rival do Estado.", "4aa91de1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:1":{"b": ["Baybars desceu à Cilícia e fez prisioneiro Leão, filho do rei de Sis Hethum", "2cefee6a"], "d": ["O sultão mameluco Baybars desceu em 1266 à Cilícia e fez prisioneiro Leão, filho do rei de Sis Hethum; pelo acordo posterior, o rei arménio restituiria as cidades e fortalezas que ocupara e Leão seria libertado (em 1268 só Besni ficou com os Arménios).", "e5f53d00"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:2":{"b": ["Berke, cã da Horda de Ouro, chegou até Tbilisi", "23866ba3"], "d": ["Berke Cã chegou até Tbilisi em 1266; o nível de prosperidade da Geórgia sob domínio ilcânida era, apesar disso, bastante elevado.", "013e2621"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1268-01-01:0":{"b": ["Os atabegues que governavam as regiões de Ahıska, Ardahan e Artvin (Atabegado de Samtshe/Meshet) assumiram a administração da região", "71bb5a86"], "d": ["Entre 1268 e 1578, os atabegues, administradores das regiões de Ahıska, Ardahan e Artvin, mantiveram nas suas mãos a administração da região e, nesse período, permaneceram dependentes dos Estados ilcânida, Kara Koyunlu e Ak Koyunlu.", "44bea8bb"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1269-01-01:0":{"b": ["Hetum I abdicou e deixou o trono ao filho Leão II; o reino tornou-se de facto vassalo dos Mamelucos", "3d94aadc"], "d": ["Hetum I abdicou e cedeu o lugar ao filho Leão II; Leão II, forçado a pagar um grande tributo anual, fez do reino de facto um vassalo dos Mamelucos.", "cd7ade63"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1271-01-01:0":{"b": ["O sultão mameluco Baybars enviou contra Chipre uma frota de dezassete navios; o ataque fracassou por causa de uma tempestade", "cfeb4521"], "d": ["Baybars, quando tomava em 1271 as últimas fortalezas e cidades dos Cruzados na Palestina e na Síria, enviou contra Chipre uma frota de dezassete navios, mas o ataque fracassou por causa da tempestade que surgiu.", "c0ba5344"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1275-01-01:0":{"b": ["Foi fundado o Beylik dos Sâhib Ataoğulları em Afyonkarahisar e arredores", "c909e2f5"], "d": ["Os filhos e netos de Sâhib Ata, vizir dos Seljúcidas da Anatólia, fundaram um beylik em Afyonkarahisar e arredores (1275-1341).", "26972b2f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1277-06-04:0":{"b": ["Os Ilcânidas, ao descobrirem a traição de Muînüddin Süleyman Pervâne, puseram fim à sua vida", "9a7cc34e"], "d": ["Após a partida de Baybars da Anatólia, Abaka Cã, que veio com um grande exército, mandou massacrar 200.000 pessoas sob o pretexto de cooperação com os Mamelucos; ao descobrirem também a traição de Pervâne, puseram fim à sua vida e passaram a administrar o Estado Seljúcida da Anatólia com funcionários enviados de Tabriz (morte de Pervâne em 676/1277).", "c7bb6ee3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1280-05-03:0":{"b": ["Mesud II, filho de Keykâvus II, veio a Sinope e foi à capital ilcânida para se apresentar diante de Abaka Cã", "9b43e13f"], "d": ["Mesud II, filho e herdeiro de Keykâvus II, veio a Sinope em 679/1280 e foi depois à capital ilcânida e apresentou-se diante de Abaka Cã; Abaka Cã deu-lhe a administração de Erzurum, Erzincan, Sivas, Diyarbekir e Harput.", "0ddb3753"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1282-04-11:0":{"b": ["Argun Cã proclamou Mesud II sultão e mandou matar Keyhusrev III", "0afda15b"], "d": ["Depois de Ahmed Teküder ter repartido os territórios seljúcidas entre Mesud II e Keyhusrev III, Argun Cã, vencedor da luta pelo trono ilcânida, proclamou sultão Mesud II, que se encontrava em Tabriz (681/1282), e mandou matar Keyhusrev III, que aguardava em Erzurum.", "ffa63120"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1284-03-20:0":{"b": ["Mesud II regressou à Anatólia e subiu ao trono como sultão seljúcida, primeiro em Kayseri e depois em Konya", "ca5c28f4"], "d": ["Mesud II regressou à Anatólia com a aprovação de Argun e subiu ao trono em 683/1284 em Kayseri e em Konya; sob o domínio dos comandantes e governadores mongóis, permaneceu um 'soberano de sombra' e lutou contra os Karamanoğulları, os Eşrefoğulları e os Germiyanoğulları.", "c089c457"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1288-11-22:0":{"b": ["O vizir seljúcida Sâhib Ata Fahreddin Ali morreu perto de Akşehir", "9c7034f1"], "d": ["Sâhib Ata, que serviu Keykâvus como nâib-i saltanat (657/1259), foi encarcerado na fortaleza de Osmancık em 670/1271-72 e nomeado de novo vizir em 674/1275-76, faleceu a 25 de Şevval de 687 / 22 de novembro de 1288 na aldeia de Nâdir, de Akşehir, após a campanha com o exército aliado seljúcida-mongol contra os Karamanoğulları, no final de 686 / início de 1288, e foi sepultado no seu mausoléu em Konya.", "f8bf5f4a"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0481-01-01:0":{"b": ["Clóvis sucedeu ao pai, Childerico, como rei dos Francos Sálios; o centro do poder era Tournai", "e4d35fd1"], "d": ["Clóvis tornou-se, em 481, aos quinze anos, rei dos Francos Sálios, sucedendo ao pai, Childerico I. Nessa data, os Francos Sálios tinham avançado até ao rio Somme e o centro do seu poder era Tournai.", "d4c684f8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0486-01-01:0":{"b": ["Clóvis derrota Siágrio na batalha de Soissons; o resto do domínio romano a sul do Somme passa para os Francos", "afa05aa7"], "d": ["Clóvis atacou em 486 o general romano Siágrio; derrotado na batalha de Soissons, Siágrio refugiou-se junto do rei visigodo Alarico II e foi-lhe entregue. A partir daí, Clóvis transferiu a sua residência para Soissons e foi tomando aos poucos a Bélgica Segunda (capital Reims).", "f20e6e70"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0496-12-25:0":{"b": ["Clóvis é batizado em Reims pelo bispo Remígio (Natal)", "16299c9a"], "d": ["Clóvis, após a vitória sobre os Alamanos, foi a Reims e, no dia de Natal de 496, foi batizado por São Remígio juntamente com três mil Francos. O batismo voltou para Clóvis os olhares da população católica dos reinos da Borgonha e dos Visigodos.", "2d58bf65"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0507-01-01:0":{"b": ["Clóvis mata em Vouillé (perto de Poitiers) o rei visigodo Alarico II; o território visigodo até aos Pirenéus passa para os Francos", "e8ea0c78"], "d": ["Clóvis, depois de concluir em 506 a submissão dos Alamanos, marchou no ano seguinte contra o rei visigodo Alarico II. Em Vouillé, perto de Poitiers, matou Alarico pela sua própria mão; a parte do reino visigodo que se estendia até aos Pirenéus, exceto a Septimânia, foi incorporada no Estado franco.", "e632a672"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0511-11-27:0":{"b": ["Clóvis morre; é sepultado em Paris, que fizera capital nos últimos anos; a unidade do reino fica como herança merovíngia", "c6c9caa4"], "d": ["Clóvis passou os últimos anos em Paris e fez dela a capital do reino; eliminando os pequenos reis francos de centros como Cambrai e Colónia, tornou-se o único rei de todas as tribos francas. Morreu em 511.", "eeb42f8c"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0756-01-01:0":{"b": ["Pepino III, com as campanhas de Itália, toma aos Lombardos o Exarcado de Ravena e doa-o ao papa; nasce o Estado Pontifício", "f6bbc975"], "d": ["Pepino III fez duas campanhas em Itália, em 754 e 756, a pedido do papa Estêvão II; doando ao papa o Exarcado de Ravena, tomado ao rei lombardo Aistulfo, tornou-se o criador do Estado temporal do papado. Pepino deu ao papa o título de 'Patrício dos Romanos'.", "0e4f19d8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0800-12-25:0":{"b": ["Carlos Magno é proclamado e coroado imperador em Roma, em São Pedro, pelo papa Leão III", "3d72f37d"], "d": ["Carlos Magno foi a Roma em 800 com o propósito de restauração; no dia de Natal seguinte, ao levantar-se da oração na basílica de São Pedro, foi coroado pelo papa Leão III e proclamado imperador e augusto.", "d6956767"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0814-01-28:0":{"b": ["Carlos Magno morre em Aachen e é sepultado no mesmo dia na igreja de Nossa Senhora", "915d6f61"], "d": ["Carlos Magno passou em Aachen (Aix) a maior parte dos últimos anos. No início de 814 teve febre; morreu a 28 de janeiro de 814, de pleurisia, depois de receber a comunhão, e foi sepultado no mesmo dia na igreja de Nossa Senhora, em Aachen; sucedeu-lhe o filho, Luís o Piedoso.", "8ce37094"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0842-02-14:0":{"b": ["Juramentos de Estrasburgo: Carlos o Calvo e Luís o Germânico juram aliança em Estrasburgo", "b462f12a"], "d": ["No ano seguinte à vitória de Fontenoy, Carlos o Calvo e Luís o Germânico reforçaram a sua aliança com os Juramentos de Estrasburgo; Carlos prestou o juramento na língua germânica do povo de Luís, e Luís na língua românica dos súbditos de Carlos.", "02ceae89"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0843-08-10:0":{"b": ["Tratado de Verdun: o Império Carolíngio é dividido em três (Frância Ocidental, Frância Média, Frância Oriental)", "1b628d03"], "d": ["Os filhos de Luís o Piedoso repartiram o império, em agosto de 843, pelo tratado concluído em Verdun: Carlos o Calvo ficou com o oeste da linha Mosa-Saône-Ródano (Frância Ocidental, incluindo a Marca de Espanha), Luís o Germânico com o leste do Reno (Baviera, Turíngia, Francónia, Saxónia; e ainda a região de Speyer-Worms-Mainz), e Lotário com a Itália, o título imperial e a faixa nos vales do Reno-Ródano.", "5bda08ed"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0875-12-25:0":{"b": ["Carlos o Calvo cinge a coroa imperial em Roma", "49f42456"], "d": ["Carlos o Calvo, que desceu a Itália após a morte de Luís II com o apoio do papa João VIII, recebeu em Pavia a coroa de rei de Itália e em Roma a coroa imperial.", "d63d65ae"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0893-01-28:0":{"b": ["Carlos o Simples é coroado rei em Reims; começa um reino rival contra Odo", "ccc4acd5"], "d": ["Carlos III 'o Simples' fora excluído, por ser jovem, quando Carlos o Gordo foi deposto em 887; durante o reinado de Odo, com o reconhecimento de alguns notáveis, foi coroado em Reims a 28 de janeiro de 893 e, com a aliança do imperador, forçou Odo a abandonar uma parte da Nêustria. Com a morte de Odo em 898, ficou com todo o reino.", "cd52d1cb"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0911-01-01:0":{"b": ["Tratado de Saint-Clair-sur-Epte: Carlos o Simples cede aos Normandos a atual Normandia", "fd0306b0"], "d": ["Carlos III fez em 911 um tratado com os Normandos em Saint-Clair-sur-Epte; uma parte dos Normandos foi batizada e foi-lhes cedido o território que mais tarde seria conhecido como ducado da Normandia. A história do casamento de Rollo com a irmã do rei é a narrativa de Dudo e é muito duvidosa.", "5798ced7"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0923-06-15:0":{"b": ["Batalha de Soissons: o rei Roberto I morre, o duque da Borgonha Raul é eleito rei", "4430302d"], "d": ["Roberto, eleito rei em 922 contra Carlos o Simples, morreu na batalha de Soissons; os partidários de Roberto, vencedores, elegeram rei o duque da Borgonha Raul (Rodolfo). Carlos, confiando no conde de Vermandois, Herberto, foi feito prisioneiro e morreu em Péronne em 929.", "9c2c291f"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0955-08-10:0":{"b": ["Batalha de Lechfeld: Otão I põe fim às incursões húngaras", "7bd31ba4"], "d": ["Otão marchou contra os Húngaros que cercavam Augsburgo e, com a grande vitória obtida em Lechfeld a 10 de agosto de 955, libertou a Alemanha das incursões húngaras; no mesmo ano derrotou também os Eslavos.", "fbb1b763"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0962-02-02:0":{"b": ["Otão I cinge em Roma a coroa imperial; início do Sacro Império Romano-Germânico", "24571f97"], "d": ["Otão passou a Itália a pedido de auxílio do papa João XII contra Berengário; depois de chegar a Pavia no Natal de 961, cingiu a coroa imperial em Roma a 2 de fevereiro de 962 e confirmou os direitos e privilégios papais. O povo de Roma jurou obter a aprovação do imperador na eleição do papa.", "6e725f97"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1016-04-23:0":{"b": ["Etelredo II morre; Canuto é eleito rei pelos notáveis reunidos em Southampton", "35653e3c"], "d": ["Após a morte de Etelredo II, a 23 de abril de 1016, o dinamarquês Canuto foi eleito rei pela assembleia de notáveis de Southampton; Londres, porém, permaneceu fiel a Edmundo. Canuto venceu na grande batalha de Assandun e, após a morte de Edmundo em novembro de 1016, foi eleito, no início de 1017, rei de toda a Inglaterra.", "3a49dfc2"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:0":{"b": ["O rei Henrique I dá o Ducado da Borgonha ao irmão Roberto; começa o Ducado Capetíngio da Borgonha (primeira casa ducal)", "18dcd0ab"], "d": ["Henrique I, que era rei de França, concedeu em 1032 o Ducado da Borgonha ao irmão Roberto; dele descende a primeira casa ducal capetíngia, que durou até 1361.", "cbb03a09"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:1":{"b": ["Rodolfo III, último rei do Reino da Borgonha (Arles), morre; o seu país passa a Conrado II (imperador alemão) — Basileia entra nos territórios imperiais", "4dc8eb08"], "d": ["Rodolfo III (993-1032), último rei do Reino da Borgonha (Borgonha Jurana/Arles), ao morrer sem herdeiros deixou os seus territórios ao imperador Conrado II. Esta herança é a fonte dos direitos imperiais que abrangiam, estendendo-se do Jura ao Aar, parte da atual Suíça, assim como Franche-Comté, Lyonnais, Dauphiné, Saboia e Provença, conhecidos depois do século XIII como Reino de Arles. Desde 888 a autoridade do reino era reconhecida nos bispados de Besançon, Basileia, Lausana, Genebra e Sion.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:2":{"b": ["Rodolfo III, último rei do Reino da Borgonha (Arles), morre; o seu país passa a Conrado II (imperador alemão) — Genebra entra nos territórios imperiais", "be189789"], "d": ["Rodolfo III (993-1032), último rei do Reino da Borgonha (Borgonha Jurana/Arles), ao morrer sem herdeiros deixou os seus territórios ao imperador Conrado II. Esta herança é a fonte dos direitos imperiais que abrangiam, estendendo-se do Jura ao Aar, parte da atual Suíça, assim como Franche-Comté, Lyonnais, Dauphiné, Saboia e Provença, conhecidos depois do século XIII como Reino de Arles. Desde 888 a autoridade do reino era reconhecida nos bispados de Besançon, Basileia, Lausana, Genebra e Sion.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:3":{"b": ["Rodolfo III, último rei do Reino da Borgonha (Arles), morre; o seu país passa a Conrado II (imperador alemão) — Lyon entra nos territórios imperiais", "78601ea1"], "d": ["Rodolfo III (993-1032), último rei do Reino da Borgonha (Borgonha Jurana/Arles), ao morrer sem herdeiros deixou os seus territórios ao imperador Conrado II. Esta herança é a fonte dos direitos imperiais que abrangiam, estendendo-se do Jura ao Aar, parte da atual Suíça, assim como Franche-Comté, Lyonnais, Dauphiné, Saboia e Provença, conhecidos depois do século XIII como Reino de Arles. Desde 888 a autoridade do reino era reconhecida nos bispados de Besançon, Basileia, Lausana, Genebra e Sion.", "54aa5fa8"]}
});
